/* DAWAH X — ahmad, অধ্যায় 72 · খণ্ড 72 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][72]=[[14201,14201,"","আমরা মোশির সঙ্গে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَفْضَلُ ‏ ‏الصَّدَقَةِ ‏ ‏صَدَقَةٌ ‏ ‏عَنْ ‏ ‏ظَهْرِ غِنًى ‏ ‏وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏ ‏وَالْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى ‏","","",""],[14202,14202,"","আমরা মূসাকে কথা বলেছি আমার ভালো বাবার সাথে, তিনি আমাকে বললেন, \"ওহ, খোদা, \"ওহ, \"ওহ, সে বলবে তার বাসায় মানুষটি আছে কিনা এবং আমরা তাকে খাওয়াতে বাধ্য করেছি।\" তিনি বললেন, যদি তার বাড়িতে মানুষটি তার বাড়ি থেকে আসে, তাহলে সে বলবে, আমরা তাকে আদেশ দিয়েছি এবং তার সাথে আমাদের সম্পর্ক বজায় রাখতে হবে। যদি সেই ব্যক্তি তার মনে প্রবেশ করে থাকেন, তাহলে তিনি ঈশ্বরের নাম উল্লেখ করেছেন, যখন তিনি বাস্তব । MedPP এবং ডিনার বলেছে আমরা করেছি.","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏جَابِرًا ‏ ‏أَسَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِذَا دَخَلَ الرَّجُلُ بَيْتَهُ يُسَلِّمُ وَالْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ قَالَ نَعَمْ قَالَ وَسَأَلْتُ ‏ ‏جَابِرًا ‏ ‏أَسَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا دَخَلَ الرَّجُلُ بَيْتَهُ فَذَكَرَ اسْمَ اللَّهِ حِينَ يَدْخُلُ وَحِينَ يَطْعَمُ قَالَ الشَّيْطَانُ لَا مَبِيتَ لَكُمْ وَلَا عَشَاءَ هَاهُنَا وَإِنْ دَخَلَ فَلَمْ يَذْكُرْ اسْمَ اللَّهِ عِنْدَ دُخُولِهِ قَالَ أَدْرَكْتُمْ الْمَبِيتَ وَإِنْ لَمْ يَذْكُرْ اسْمَ اللَّهِ عِنْدَ مَطْعَمِهِ قَالَ أَدْرَكْتُمْ الْمَبِيتَ وَالْعَشَاءَ قَالَ نَعَمْ ‏","","",""],[14203,14203,"","আমরা আমার উত্তম বাবার কথা বলেছি, তিনি আমাদের একজন প্রতিবেশীকে বলেছেন, তিনি যেন আমাদের পুরুষদের দাস হিসেবে কাজ করতে বলেন।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏جَابِرًا ‏ ‏عَنْ خَادِمِ الرَّجُلِ إِذَا كَفَاهُ الْمَشَقَّةَ وَالْحَرَّ فَقَالَ ‏ ‏أَمَرَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَدْعُوَهُ فَإِنْ كَرِهَ أَحَدٌ أَنْ يَطْعَمَ مَعَهُ فَلْيُطْعِمْهُ أُكْلَةً فِي يَدِهِ ‏","","",""],[14204,14204,"","আমরা মূসা কে বলেছিলাম আমার সুন্দর বাবার একটা ছেলের সাথে কথা বলেছি। সে আমাকে উত্তর দিতে বলবে না যখন সে ভালো থাকবে আর সে গম চুরি করবে না। আর আমাকে একটা কথা বলবে। জীবনের জন্য অথবা সে শুনতে পারে.","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏أَسَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَزْنِي الزَّانِي حِينَ يَزْنِي وَهُوَ مُؤْمِنٌ وَلَا يَسْرِقُ حِينَ يَسْرِقُ وَهُوَ مُؤْمِنٌ قَالَ ‏ ‏جَابِرٌ ‏ ‏لَمْ أَسْمَعْهُ قَالَ ‏ ‏جَابِرٌ ‏ ‏وَأَخْبَرَنِي ‏ ‏ابْنُ عَمْرٍو ‏ ‏أَنَّهُ قَدْ سَمِعَهُ ‏","","",""],[14205,14205,"","আমরা মোশির সঙ্গে কথা বলেছিলাম । অনেক কপটতা মারা যেতে পারে.","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏جَابِرًا ‏ ‏أخْبَرَهُ ‏ ‏أَنَّهُمْ غَزَوْا غَزْوَةً بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَالْمَدِينَةِ ‏ ‏فَهَاجَتْ عَلَيْهِمْ رِيحٌ شَدِيدَةٌ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا لِمَوْتِ ‏ ‏مُنَافِقٍ ‏ ‏فَرَجَعْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَوَجَدْنَا ‏ ‏مُنَافِقًا ‏ ‏عَظِيمَ النِّفَاقِ قَدْ مَاتَ ‏","","",""],[14206,14206,"","আমরা মূসাকে আমার প্রিয় পিতার বাধ্য হতে বলছি, সে বারবিকিউ ছেড়ে দিবে, তারপর সে এটাকে তার মাথায় ভাগ করবে। তাকে বলতে হবে যে আমরা আছি। লোকেরা জন্ম নিয়ে আপনাকে বিক্রি করার চেষ্টা করে ।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا فُتِحَتْ ‏ ‏حُنَيْنٌ ‏ ‏بَعَثَ ‏ ‏سَرَايَا ‏ ‏فَأَتَوْا بِالْإِبِلِ وَالشَّاءِ ‏ ‏فَقَسَمَهَا ‏ ‏فِي ‏ ‏قُرَيْشٍ ‏ ‏قَالَ فَوَجَدْنَا أَيُّهَا ‏ ‏الْأَنْصَارُ ‏ ‏عَلَيْهِ فَبَلَغَهُ ذَلِكَ فَجَمَعَنَا فَخَطَبَنَا فَقَالَ ‏ ‏أَلَا تَرْضَوْنَ أَنَّكُمْ ‏ ‏أُعْطِيتُمْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَاللَّهِ لَوْ سَلَكَتْ النَّاسُ وَادِيًا وَسَلَكْتُمْ شِعْبًا لَاتَّبَعْتُ شِعْبَكُمْ قَالُوا رَضِينَا يَا رَسُولَ اللَّهِ ‏","","",""],[14207,14207,"","আমরা মূসাকে কথা বলেছি আমার প্রিয় বাবার সাথে আমি কথা বলেছি যে আমাকে শাস্তি প্রদানের জন্য উত্তর দিতে হবে। তাদের কপটতা তাঁর কাছে প্রার্থনা করেছে এবং তার কাজের খেলনাগুলো সরবরাহ করবে। গৃহীত এবং প্রদান করা হয়েছে","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ ‏ ‏الْعَقَبَةِ ‏ ‏قَالَ شَهِدَهَا سَبْعُونَ فَوَافَقَهُمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَبَّاسُ بْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏آخِذٌ بِيَدِهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ أَخَذْتُ وَأَعْطَيْتُ ‏","","",""],[14208,14208,"","আমরা মূসা কথা বলেছিলাম তার কথা ভুল ছিল। আমি শুনেছি নবী প্রার্থনা করলেন, তিনি এটা ছেড়ে দেবেন এবং বলেন তিনি চলে যাবেন। তারপর আপনি চলে যাবেন এবং নির্মাণ করবেন এবং তারপর তারা বেরিয়ে যাবে। তারপর তারা বের হয়ে যাবে। আমি আপনাদের কাছে ফিরে যেতে দেব এবং তারপর তারা বের হয়ে যাবে। এটা.","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ أَخْبَرَهُ أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَيَخْرُجُ أَهْلُ ‏ ‏مَكَّةَ ‏ ‏مِنْهَا ثُمَّ لَا يَعْمُرُوهَا ‏ ‏أَوْ لَا تُعْمَرُ ‏ ‏إِلَّا قَلِيلًا ثُمَّ تُعْمَرُ وَتَمْتَلِئُ ‏ ‏وَتُبْنَى ثُمَّ يَخْرُجُونَ مِنْهَا فَلَا يَعُودُونَ إِلَيْهَا أَبَدًا ‏","","",""],[14209,14209,"","আমরা মূসা-এর সাথে কথা বলেছি এবং আমরা বাবার বাবা-মা'র সাথে কথা বলেছি, তাকে উত্তর দিতে চাই। সে আত্মসমর্পণ করবে। সে বলছে সে কখনো শহরের একজন যাত্রীকে হত্যা করবে না। হিংস্র মৃত্যুর ধূসর দিক, সংরক্ষিত রোগের মধ্যে রয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏وَقُتَيْبَةُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَسِيرَنَّ رَاكِبٌ فِي جِهَةِ ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ ‏ ‏قُتَيْبَةُ ‏ ‏فِي جَانِبِ ‏ ‏الْمَدِينَةِ ‏ ‏فَيَقُولَنَّ لَقَدْ كَانَ فِي هَذِهِ مَرَّةً حَاضِرٌ مِنْ الْمُؤْمِنِينَ كَثِيرٌ ‏","","",""],[14210,14210,"","আমরা মূসাকে আমার ছেলেকে নিয়ে কথা বলেছি সে এই ছেলেকে বলেছে, সে বলে ছেলেটির কথা শোনে। সে বলবে কেউ বলে না খুন করার জন্য কাউকে খুন করার জন্য সে খুন করতে চায়।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏جَابِرًا ‏ ‏أَخْبَرَهُ أَنَّهُ قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَحِلُّ لِأَحَدٍ يَحْمِلُ فِيهَا السِّلَاحَ لِقِتَالٍ ‏ ‏فَقَالَ ‏ ‏قُتَيْبَةُ ‏ ‏يَعْنِي ‏ ‏الْمَدِينَةَ ‏","","",""],[14211,14211,"","আমরা মোশির সঙ্গে কথা বলেছিলাম । শান্তি ত্যাগ করে আত্মসমর্পণ করে তারপর আগুনে পড়ে যায়, যে কিনা উলটা পরে যায়, আমরা প্রার্থনা করব ঋণের মধ্যে থেকে তা নিয়ে যাব এবং এটা নিয়ে যাব। আমি তোমাকে এটা পরতে আদেশ দিচ্ছি না... ...কিন্তু তুমি তাকে আবার জিততে পাঠাচ্ছি। লর্ড তার কাছে প্রার্থনা করে তাকে ক্ষমা করে দেয় এবং অপরাধীর কাছে আত্মসমর্পণ করে এবং হয়ত সে তার থেকে পালিয়ে যায়। এই ভুলের একটি splaces.","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْدَى إِلَيْهِ رَاهِبٌ مِنْ ‏ ‏الشَّامِ ‏ ‏جُبَّةً ‏ ‏مِنْ ‏ ‏سُنْدُسٍ ‏ ‏فَلَبِسَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ أَتَى الْبَيْتَ فَوَضَعَهَا وَأُخْبِرَ بِوَفْدٍ يَأْتِيهِ فَأَمَرَهُ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏أَنْ يَلْبَسَ ‏ ‏الْجُبَّةَ ‏ ‏لِقُدُومِ الْوَفْدِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَصْلُحُ لَنَا لِبَاسُهَا فِي الدُّنْيَا وَيَصْلُحُ لَنَا لِبَاسُهَا فِي الْآخِرَةِ وَلَكِنْ خُذْهَا يَا ‏ ‏عُمَرُ ‏ ‏فَقَالَ أَتَكْرَهُهَا وَآخُذُهَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَا آمُرُكَ أَنْ تَلْبَسَهَا وَلَكِنْ تُرْسِلُ بِهَا إِلَى أَرْضِ ‏ ‏فَارِسَ ‏ ‏فَتُصِيبُ بِهَا مَالًا فَأَبَى ‏ ‏عُمَرُ ‏ ‏فَأَرْسَلَ بِهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏النَّجَاشِيِّ ‏ ‏وَكَانَ قَدْ أَحْسَنَ إِلَى مَنْ ‏ ‏فَرَّ ‏ ‏إِلَيْهِ مِنْ ‏ ‏أَصْحَابِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[14212,14212,"","আমরা মোসে এবং আমরা এমন এক ছেলের কথা বলেছিলাম, যিনি তার কথা ভালোমতো বলেছিলেন । আমি তার কাছে প্রার্থনা করছি, আমি তার কাছে যাই না, আর আমি মুক্তভাবে সেবা করি না, যাজকের পোশাক পরবো না।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏وَحَسَنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏وَقَالَ ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏جَابِرًا ‏ ‏عَنْ ‏ ‏مِيثَرَةٍ ‏ ‏قَالَ ‏ ‏الْأُرْجُوَانِ ‏ ‏فَقَالَ ‏ ‏جَابِرٌ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَرْكَبُهَا وَلَا أَلْبَسُ قَمِيصًا مَكْفُوفًا بِحَرِيرٍ وَلَا أَلْبَسُ ‏ ‏الْقَسِّيَّ ‏","","",""],[14213,14213,"","আমরা মূসাকে বলেছিলাম, আমরা একটা ছেলেকে বলেছি, প্রভুর অন্ত্যেষ্টিক্রিয়ার জন্য আমার উত্তম বাবার কাছ থেকে দূরে সরিয়ে নিতে। তার জীবন হুমকির মুখে ছিল লর্ডের সাথে তার শান্তি বজায় রাখার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنِ ‏ ‏الْبَهْزِيَّةِ أُمِّ مَالِكٍ ‏ ‏كَانَتْ ‏ ‏تُهْدِي فِي ‏ ‏عُكَّةٍ ‏ ‏لَهَا سَمْنًا لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَيْنَمَا بَنُوهَا يَسْأَلُونَهَا عَنْ ‏ ‏إِدَامٍ ‏ ‏وَلَيْسَ عِنْدَهَا شَيْءٌ ‏ ‏فَعَمَدَتْ إِلَى ‏ ‏نِحْيِهَا الَّتِي كَانَتْ ‏ ‏تُهْدِي فِيهِ السَّمْنَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدَتْ فِيهِ سَمْنًا فَمَا زَالَ يُقِيمُ لَهَا ‏ ‏إِدَامَ ‏ ‏بَنِيهَا حَتَّى عَصَرَتْهُ فَأَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَعَصَرْتِيهِ فَقَالَتْ نَعَمْ قَالَ لَوْ ‏ ‏تَرَكْتِيهِ مَا زَالَ ذَلِكَ مُقِيمًا ‏","","",""],[14214,14214,"","আমরা মোশির সঙ্গে আমার উত্তম বাবার কাছ থেকে দূরে থাকার বিষয়ে কথা বলেছিলাম, যিনি ঈশ্বরের জন্য প্রার্থনা করেছিলেন । তাকে শেখানো হয়েছে, আর যদি তুমি তাকে তার থেকে খেতে না পারো... ...তাহলে তোমাকে এটা করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ أَتَاهُ رَجُلٌ يَسْتَطْعِمُهُ ‏ ‏فَأَطْعَمَهُ ‏ ‏شَطْرَ ‏ ‏وَسْقِ ‏ ‏شَعِيرٍ فَمَا زَالَ الرَّجُلُ يَأْكُلُ مِنْهُ هُوَ وَامْرَأَتُهُ وَوَصِيفٌ لَهُمْ حَتَّى كَالُوهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ لَمْ تَكِيلُوهُ لَأَكَلْتُمْ مِنْهُ وَلَقَامَ لَكُمْ ‏","","",""],[14215,14215,"","আমরা মোশির সঙ্গে কথা বলেছিলাম । সে ঈশ্বরের কাছে বলবে কে করবে না বলে আমি তোমাকে যেতে দেব না যদি সে এটা করে।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏بَنَّةَ الْجُهَنِيَّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ عَلَى قَوْمٍ فِي الْمَسْجِدِ ‏ ‏أَوْ فِي الْمَجْلِسِ ‏ ‏يَسُلُّونَ سَيْفًا بَيْنَهُمْ يَتَعَاطَوْنَهُ بَيْنَهُمْ غَيْرَ مَغْمُودٍ فَقَالَ ‏ ‏لَعَنَ اللَّهُ مَنْ يَفْعَلُ ذَلِكَ ‏ ‏أَوَ لَمْ أَزْجُرْكُمْ عَنْ هَذَا فَإِذَا سَلَلْتُمْ السَّيْفَ فَلْيَغْمِدْهُ الرَّجُلُ ثُمَّ لِيُعْطِهِ كَذَلِكَ ‏","","",""],[14216,14216,"","আমরা কথা বলেছি, গভর্নর দু'বার বলেছেন আমরা দু'বার কাজ করেছি। আপনি কি শুনেছেন ছেলেটি প্রার্থনা করেছে এবং সে বলল যে সে নাকি শক্তির মধ্যে আছে ঈশ্বর আমাদের উদ্ধার করেছেন এবং আমরা আল্লাহকে হত্যা করেছি। মানুষ, তুমি প্রার্থনা করার সময় প্রার্থনায় যাওনি।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏وَحَسَنٌ ‏ ‏وَاللَّفْظُ لَفْظُ ‏ ‏حَسَنٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏هَلْ سَمِعْتَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ الرَّجُلُ فِي صَلَاةٍ مَا انْتَظَرَ الصَّلَاةَ قَالَ انْتَظَرْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً لِصَلَاةِ الْعَتَمَةِ فَاحْتَبَسَ عَلَيْنَا حَتَّى كَانَ قَرِيبًا مِنْ شَطْرِ اللَّيْلِ ‏ ‏أَوْ بَلَغَ ذَلِكَ ‏ ‏ثُمَّ جَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّيْنَا ثُمَّ قَالَ اجْلِسُوا فَخَطَبَنَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ النَّاسَ قَدْ صَلَّوْا وَرَقَدُوا وَأَنْتُمْ لَمْ تَزَالُوا فِي صَلَاةٍ مَا انْتَظَرْتُمْ الصَّلَاةَ ‏","","",""],[14217,14217,"","আমরা আমার শ্বশুর আব্বাকে কথা বলেছি। আমি লর্ডকে শুনেছি। সে বলবে, যদি আমি ওকে তাঁর মুখে যেতে ভালোবাসি, আমরা শ্বাস নেই। আমরা শ্বাস নেই।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جَابِرٌ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا أَحَدُكُمْ أَعْجَبَتْهُ الْمَرْأَةُ فَوَقَعَتْ فِي نَفْسِهِ فَلْيَعْمِدْ إِلَى امْرَأَتِهِ فَلْيُوَاقِعْهَا فَإِنَّ ذَلِكَ يَرُدُّ مِنْ نَفْسِهِ ‏","","",""],[14218,14218,"","আমরা আমার বাবার সাথে কথা বলেছি যে আমি দিনের মানুষের মৃত্যুর জবাব চাই। জাবের তার কাছে প্রার্থনা শুনতে শুনেছেন। তুমি অন্য রাতের বাইরে থেকে অন্য রাত পড়তে।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الرَّجُلِ ‏ ‏يُوتِرُ ‏ ‏عِشَاءً ثُمَّ يَرْقُدُ قَالَ ‏ ‏جَابِرٌ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ خَافَ مِنْكُمْ أَنْ لَا يَقُومَ مِنْ اللَّيْلِ ‏ ‏فَلْيُوتِرْ ‏ ‏ثُمَّ لِيَرْقُدْ وَمَنْ طَمِعَ مِنْكُمْ الْقِيَامَ ‏ ‏فَلْيُوتِرْ ‏ ‏مِنْ آخِرِ اللَّيْلِ فَإِنَّ قِرَاءَةَ آخِرِ اللَّيْلِ مَحْضُورَةٌ وَذَلِكَ أَفْضَلُ ‏","","",""],[14219,14219,"","আমরা মূসা কথা বলেছি আমার বাবার সাথে দেখা করতে যে সে এটা করতে পারবে। সে বলেছিল, রাত এক ঘণ্টা পর সে তার সাথে শান্তি চায় না। আমি তাকে দিতে না.","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ اللَّيْلِ سَاعَةً لَا يُوَافِقُهَا عَبْدٌ مُسْلِمٌ يَسْأَلُ اللَّهَ خَيْرًا إِلَّا أَعْطَاهُ وَهِيَ كُلَّ لَيْلَةٍ ‏","","",""],[14220,14220,"","আমরা মোশির সঙ্গে কথা বলেছিলাম । বইয়ের শান্তি আর দুঃখের কথা আমি কোন কিছু করিনি, যা বলে আমরা ঈশ্বরকে খুন করি, আমি কিছুই করিনি।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏نُعْمَانَ بْنَ قَوْقَلٍ ‏ ‏جَاءَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَرَأَيْتَ إِذَا صَلَّيْتُ ‏ ‏الْمَكْتُوبَاتِ ‏ ‏وَصُمْتُ رَمَضَانَ وَحَرَّمْتُ الْحَرَامَ وَأَحْلَلْتُ الْحَلَالَ وَلَمْ أَزِدْ عَلَى ذَلِكَ شَيْئًا أَفَأَدْخُلُ الْجَنَّةَ قَالَ نَعَمْ فَقَالَ وَاللَّهِ لَا أَزِيدُ عَلَى ذَلِكَ شَيْئًا ‏","","",""],[14221,14221,"","আমরা মোশির সঙ্গে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏أَشَدَّ النَّاسِ تَخْفِيفًا فِي الصَّلَاةِ ‏","","",""],[14222,14222,"","আমরা মূসা কে বলেছিলাম, বাবার সাথে দেখা করার সময় আমরা একটা ছেলের সাথে কথা বলেছি। সে বলেছিল সে যেন প্রতিবেশীকে জিজ্ঞেস করে সে সূর্যাস্ত আর ডিনার করবে।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏هَلْ جَمَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ قَالَ نَعَمْ زَمَانَ غَزْوِنَا ‏ ‏بَنِي الْمُصْطَلِقِ ‏","","",""],[14223,14223,"","আমরা মূসা-এর কথা বলেছি, আমার বাবা, পাইলট, আমি আমার ছেলের প্রতি বাধ্যতা দেখানোর জন্য এক ছেলেকে বলেছিলাম। যুদ্ধ","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏جَابِرًا ‏ ‏عَنْ التَّصْفِيقِ وَالتَّسْبِيحِ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏التَّصْفِيقُ لِلنِّسَاءِ فِي الصَّلَاةِ وَالتَّسْبِيحُ لِلرِّجَالِ ‏","","",""],[14224,14224,"","আমরা আমার প্রিয় বাবার সঙ্গে কথা বলেছিলাম, যিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏غَزَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِتَّ مِرَارٍ قَبْلَ صَلَاةِ الْخَوْفِ وَكَانَتْ صَلَاةُ الْخَوْفِ فِي السَّنَةِ السَّابِعَةِ ‏","","",""],[14225,14225,"","আমরা মূসা কে বলেছিলাম, আমার বাবার সবচেয়ে ভালো কথা বলতে গেলে আমি রহস্যের উত্তর দেব অথবা আমি একটি জীবন-ভর্তি ঈশ্বর পেতে চেষ্টা করব। তার জন্য প্রার্থনা করে... ...এবং আমাদের আত্মার অনুগ্রহে... ...সে আমার তিন দিনের প্রচারককে ছেড়ে দিবে...","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الْغُسْلِ قَالَ ‏ ‏جَابِرٌ ‏ ‏أَتَتْ ‏ ‏ثَقِيفٌ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِنَّ أَرْضَنَا أَرْضٌ بَارِدَةٌ فَكَيْفَ تَأْمُرُنَا بِالْغُسْلِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا ‏ ‏أَنَا فَأَصُبُّ عَلَى رَأْسِي ثَلَاثَ مَرَّاتٍ وَلَمْ يَقُلْ غَيْرَ ذَلِكَ ‏","","",""],[14226,14226,"","আমরা মূসা কে বলেছিলাম, আমি আমার বাবার সাথে দেখা করতে এসেছি।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الرَّجُلِ ‏ ‏يُبَاشِرُ ‏ ‏الرَّجُلَ ‏ ‏فَقَالَ ‏ ‏جَابِرٌ ‏ ‏زَجَرَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ ‏","","",""],[14227,14227,"","আর তাকে ফোন করে আমি একজন প্রতিবেশীকে জিজ্ঞেস করবো, সে কিভাবে চলে যায়।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الْمَرْأَةِ تُبَاشِرُ الْمَرْأَةَ قَالَ زَجَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ ‏","","",""],[14228,14228,"","আর তাকে ফোন করে আমি একজন প্রতিবেশীর কাছে জিজ্ঞেস করব যে মাছ চায় আর তার হাত ধরে রাখতে চায়। ড্রিংক করো।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الرَّجُلِ يُرِيدُ الصِّيَامَ وَالْإِنَاءُ عَلَى يَدِهِ لِيَشْرَبَ مِنْهُ فَيَسْمَعُ النِّدَاءَ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏كُنَّا نُحَدَّثُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِيَشْرَبْ ‏","","",""],[14229,14229,"","আর প্রতিবেশীদের কাছে তাকে ফোন করে আমি বলেছিলাম যে, ভাববাদী তার কাছে প্রার্থনা করেছিলেন, তিনি সূর্যের শপথটা বলবেন ।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَطْلُعُ الشَّمْسُ فِي قَرْنِ شَيْطَانٍ ‏","","",""],[14230,14230,"","আর তাকে ফোন করে আমি জাবেরকে তার ওপর দিয়ে যেতে বলব তাকে জানতে এমনকি সে দেখতেও চায়।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ رُكُوبِ الْهَدْيِ قَالَ ‏ ‏جَابِرٌ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏ارْكَبْهَا بِالْمَعْرُوفِ حَتَّى تَجِدَ ظَهْرًا ‏","","",""],[14231,14231,"","আমরা মূসা সম্বন্ধে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَوْمِ عَاشُورَاءَ ‏ ‏أَنْ نَصُومَهُ ‏","","",""],[14232,14232,"","আমরা মূসা এবং তার পুত্রদের কথা বলেছি, আমরা আমার প্রিয় ছেলের কথা বলেছিলাম। আমি বলছি, আমি এক যুবককে উত্তর দেব যে তার কাছে প্রার্থনা করেছে। সে তার কাছে প্রার্থনা করেছে এবং শহরের দুঃখের কারণে আশীর্বাদ লাভ করবে। আমি মনে করি সে এমন এক মানুষের কাছে এসেছে যে কিনা প্রেমে পড়েছে, ঈশ্বর তাকে আদেশ দিয়েছেন আর আত্মসমর্পণ করেছেন। আমরা প্রভুকে তার কাছে যেতে পারি যাকে তিনি আত্মসমর্পণ করেছেন। তিনি এখন মুক্ত। তিনি তাঁর প্রতি অনুগ্রহশীল। তিনি তাঁর প্রতি অনুগ্রহ প্রকাশ করেছেন। এবং তিনি তাঁর প্রতি তাঁর আনুগত্য প্রকাশ করেছেন। এবং তিনি তাঁর প্রতি তাঁর প্রেম প্রকাশ করেছেন। এবং তাঁর প্রতি তাঁর পিতার অনুগ্রহ রয়েছে, এবং তাঁর প্রতি তাঁর প্রতি তাঁর প্রেম রয়েছে, যিনি তাঁর প্রতি তাঁর প্রতি তাঁর প্রতি তাঁর প্রেম রয়েছে। এবং তাঁর প্রতি তাঁর প্রতি তাঁর প্রেম রয়েছে, তাঁর প্রতি তাঁর প্রতি তাঁর প্রতি তাঁর প্রেম, এবং তাঁর প্রতি তাঁর পিতার আস্থা। এবং তাঁর প্রতি তাঁর প্রতি তাঁর প্রতি তাঁর পুত্রের ভূমিকা রয়েছে, যিনি তাঁর প্রতি, যিনি বশীভূত । তিনি নিজে নিজে নিজে নিজে নিজে নিজে নিজে নিজে নিজে নিজে নিজে নিজে নিজে তাঁর উপর আস্থা রেখে দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ النَّحْرِ فَقَالَ ‏ ‏جَابِرٌ ‏ ‏صَلَّى بِنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَتَقَدَّمَ رِجَالٌ فَنَحَرُوا وَظَنُّوا أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ نَحَرَ فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ نَحَرَ أَنْ يُعِيدَ نَحْرًا آخَرَ وَلَا يَنْحَرُوا حَتَّى يَنْحَرَ ‏","","",""],[14233,14233,"","আমরা মূসা কে বলেছিলাম, আমার বাবার বড় ভাইর প্রতি বাধ্যতা দেখানোর জন্য আমি একটা ছেলেকে বলেছিলাম। সে যদি বলেছিল, \"তার কাছে প্রার্থনা করতো, তার কাছে প্রার্থনা করতো...\" তার সকল রাষ্ট্রের কাছে আত্মসমর্পণ করা হয়েছে যে তিনি বলেছেন যে তিনি একই রকম হবেন।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الرَّجُلِ ‏ ‏يُوَالِي ‏ ‏مَوَالِيَ ‏ ‏الرَّجُلِ بِغَيْرِ إِذْنِهِ فَقَالَ كَتَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى كُلِّ بَطْنٍ عُقُولَهُمْ ثُمَّ كَتَبَ أَنَّهُ لَا يَحِلُّ أَنْ ‏ ‏يُوَالِيَ ‏ ‏مَوَالِيَ ‏ ‏رَجُلٍ بِغَيْرِ إِذْنِهِ ‏","","",""],[14234,14234,"","আমরা একটা মূসা কথা বলেছি আর আমরা একটা ছেলে কথা বলেছি যে বাবার অদ্ভুত প্রেম নিয়ে ঘোরাফেরা করছে। আমিও তাই মনে করি \"ঠিক\"","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏وَحَسَنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الْمُؤْمِنِ كَمَثَلِ السُّنْبُلَةِ تَخِرُّ مَرَّةً وَتَسْتَقِيمُ مَرَّةً وَمَثَلُ الْكَافِرِ مَثَلُ الْأَرْزِ لَا يَزَالُ مُسْتَقِيمًا حَتَّى يَخِرَّ وَلَا يَشْعُرَ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏الْأَرْزَةِ ‏","","",""],[14235,14235,"","আমরা মূসা আমাদের একটি ছেলেকে কথা বলেছি আমার সৎ বাবার বাধ্য হতে বলা হয়েছে। আমি বলেছিলাম, আমি সূর্য ও সূর্যের শাসন সম্পর্কে প্রতিবেশীকে জিজ্ঞাসা করব। সূর্যটা যদি আমি হরিণের মতো করে ফেলি অথবা হারি, তাহলে সূর্য চুপ হয়ে গেল।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ خُسُوفِ الشَّمْسِ وَالْقَمَرِ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ إِذَا خُسِفَا أَوْ أَحَدُهُمَا فَإِذَا رَأَيْتُمْ ذَلِكَ فَصَلُّوا حَتَّى ‏ ‏يَنْجَلِيَ ‏ ‏خُسُوفُ أَيِّهِمَا خُسِفَ ‏","","",""],[14236,14236,"","আমরা মূসা আমাদের বলেছেন যে আমার শ্বশুর আব্বাকে মারার ব্যাপারে উত্তেজিত একটি ছেলে আছে। আমি তাকে খুন করার কারণ জানতে চাই। একটি ভালো জীবন বলে যে একজন অত্যাচারীর দ্বারা সে উজ্জ্বল হতে শিখেছে। স্বপ্নার যে মানুষের হাতে আঘাত লাগে, সে বলে জাবের আর আমি তাকে জানতাম না যে কেউ তাকে খুন করেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الْقَتِيلِ الَّذِي قُتِلَ فَأَذَّنَ فِيهِ ‏ ‏سُحَيْمٌ ‏ ‏فَقَالَ ‏ ‏جَابِرٌ ‏ ‏أَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُحَيْمًا ‏ ‏أَنْ يُؤَذِّنَ فِي النَّاسِ أَلَا لَا يَدْخُلُ الْجَنَّةَ إِلَّا مُؤْمِنٌ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏وَلَا أَعْلَمُهُ قُتِلَ أَحَدٌ ‏","","",""],[14237,14237,"","আমরা ভালো করেই বলেছি একটা ছেলেকে মেরে ফেলার জন্য। নরক বলেছিল, আমরা ভালো আছি। মোশির একজনকে হত্যা করা হয়েছে... ...যে সব থেকে ভালো মানুষ আগে খুন হয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الْقَتِيلِ الَّذِي قُتِلَ فَأَذَّنَ فِيهِ ‏ ‏سُحَيْمٌ ‏ ‏قَالَ كُنَّا ‏ ‏بِحُنَيْنٍ ‏ ‏فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُحَيْمًا ‏ ‏أَنْ يُؤَذِّنَ فِي النَّاسِ أَنْ لَا يَدْخُلَ الْجَنَّةَ إِلَّا مُؤْمِنٌ ‏ ‏قَالَ ‏ ‏وَلَا أَعْلَمُهُ قُتِلَ أَحَدٌ ‏ ‏قَالَ ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَتَلَ أَحَدًا ‏","","",""],[14238,14238,"","আমরা মূসা-এর কথা বলেছি। আমরা আমার বাবার সবচেয়ে ভালো কথা বলেছি। ছেলেটি বলে যে, আমি ঈশ্বরকে এসব বলার জন্য তাকে জিজ্ঞেস করব। বাতাসে এক যুবক বলেছিল, \"সে তার কথা শুনবে\"। তার সারা জীবন।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏أَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الطِّيَرَةِ وَالْعَدْوَى شَيْئًا ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏سَمِعْتُهُ يَقُولُ ‏ ‏كُلُّ عَبْدٍ طَائِرُهُ فِي عُنُقِهِ ‏","","",""],[14239,14239,"","আমরা মূসাকে বলেছিলাম তার ছেলেকে বিভ্রান্ত করতে আর তাকে যেতে হবে। আমার মনে হয় তার ভাই মৃত অবস্থায় আসার চেয়ে ভালো চলে যাবে.","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَفَّنَ أَحَدُكُمْ أَخَاهُ فَلْيُحْسِنْ كَفَنَهُ وَصَلُّوا عَلَى الْمَيِّتِ أَرْبَعَ تَكْبِيرَاتٍ فِي اللَّيْلِ وَالنَّهَارِ سَوَاءً ‏","","",""],[14240,14240,"","আমরা মোশির সঙ্গে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ثَمَنِ السِّنَّوْرِ وَهُوَ الْقِطُّ ‏","","",""],[14241,14241,"","আমরা মোশির সঙ্গে কথা বলেছিলাম । ঈশ্বরের ভালবাসা।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَجَنَازَةُ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏بَيْنَ أَيْدِيهِمْ اهْتَزَّ لَهَا عَرْشُ الرَّحْمَنِ ‏","","",""],[14242,14242,"","আমরা মূসা আমাদের বলেছেন যে আমার শ্বশুর আব্বার জন্য পরিচিত তিনি এই ভবিষ্যদ্বাণী শুনেছেন যে আমি শুধু খেতে চাই এবং আমি আপনার আত্মা না জিতব. এবং রক্ষা করুন, তারা কিভাবে আত্মা অনুপ্রাণিত করে।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَأْكُلُ أَهْلُ الْجَنَّةِ فِيهَا وَيَشْرَبُونَ وَلَا يَمْتَخِطُونَ وَلَا يَتَغَوَّطُونَ وَلَا يَبُولُونَ إِنَّمَا طَعَامُهُمْ ‏ ‏جُشَاءٌ ‏ ‏رَشْحٌ ‏ ‏كَرَشْحِ ‏ ‏الْمِسْكِ ‏ ‏فَيُلْهَمُونَ التَّسْبِيحَ وَالتَّحْمِيدَ كَمَا يُلْهَمُونَ النَّفَسَ ‏","","",""],[14243,14243,"","আমরা দু'জন বাক্য নিয়ে কথা বলেছি এবং আমরা আমার শ্বশুর আব্বার ব্যাপারে কথা বলেছি। ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করেছেন বধির এবং একজন এবং চমৎকার এবং চমৎকার ব্যক্তি হিসেবে তিনি তার সাথে যোগ দেবেন। ভালো, তার লোকদের যেতে হবে আর সে তার পিঠে ঝুলে আছে।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏اشْتِمَالِ ‏ ‏الصَّمَّاءِ ‏ ‏وَالِاحْتِبَاءِ ‏ ‏فِي ثَوْبٍ وَاحِدٍ وَأَنْ يَرْفَعَ الرَّجُلُ إِحْدَى رِجْلَيْهِ عَلَى الْأُخْرَى وَهُوَ مُسْتَلْقٍ عَلَى ظَهْرِهِ ‏","","",""],[14244,14244,"","আমরা দুটো যুক্তি নিয়ে কথা বলেছি আর আমাদের বাবার ভালোর বাইরে যেতে দেয়া উচিত নয়, ঈশ্বরকে খুঁজতে গিয়ে বলতে যে ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং বলতে বাধ্য, ঈশ্বর আছে শুধু বোকা বানানো, ঈশ্বরের প্রার্থনা তিনি তার মিথ্যাকে ছেড়ে দিয়েছেন... ...সে এটা দেখে নি আর তোমার মুখ বন্ধ করে দিবে.","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدًا ‏ ‏لِحَاطِبٍ ‏ ‏جَاءَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَشْتَكِي ‏ ‏حَاطِبًا ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ لَيَدْخُلَنَّ ‏ ‏حَاطِبٌ ‏ ‏النَّارَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَبْتَ لَا يَدْخُلُهَا فَإِنَّهُ شَهِدَ ‏ ‏بَدْرًا ‏ ‏وَالْحُدَيْبِيَةَ ‏","","",""],[14245,14245,"","আমরা আমার বাবার কথা বলেছি আর সে টাইমার খুঁজছে আর সে আরো একটু পেতে চেষ্টা করছে, ঈশ্বর তাকে আশীর্বাদ করুন আর প্রভুর কাছে নিজেকে সমর্পণ করুন। ঈশ্বর তাকে আদেশ দিয়েছেন যে ঈশ্বর তার প্রাণ জয় করতে পারবেন।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏وَإِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏جَاءَ عَبْدٌ فَبَايَعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْهِجْرَةِ وَلَمْ ‏ ‏يَشْعُرْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ عَبْدٌ فَجَاءَ سَيِّدُهُ يُرِيدُهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعْنِيهِ فَاشْتَرَاهُ بِعَبْدَيْنِ أَسْوَدَيْنِ ثُمَّ لَمْ يُبَايِعْ أَحَدًا بَعْدُ حَتَّى يَسْأَلَهُ أَعَبْدٌ هُوَ ‏","","",""],[14246,14246,"","আমরা দু'টি বাক্য নিয়ে কথা বলেছি এবং ভুলে গেছি যে আমার বাবার অশ্রদ্ধার কথা, প্রেমিকরা শুধু তাদের কাজ সমাধান করার জন্য ফিরে আসবে। ঈশ্বরের কাছে এই আজ্ঞা দেওয়া হয়েছে এবং ঈশ্বরের প্রতি ভয় দ্বারা পরাজিত হবে । হাত, আমার বিল্ডিং থেকে, তুমি এটা ধরে রাখবে যতক্ষণ না আমরা এটা চুরি করে ফেলি। তারা বলবে না যে ঈশ্বরের ইচ্ছা আছে। সে তাদের হত্যা করতে বের হয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ ‏ ‏قَالَ ‏ ‏رُمِيَ يَوْمَ الْأَحْزَابِ ‏ ‏سَعْدُ بْنُ مُعَاذٍ ‏ ‏فَقَطَعُوا ‏ ‏أَكْحَلَهُ ‏ ‏فَحَسَمَهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالنَّارِ فَانْتَفَخَتْ يَدُهُ ‏ ‏فَحَسَمَهُ ‏ ‏فَانْتَفَخَتْ يَدُهُ ‏ ‏فَحَسَمَهُ ‏ ‏أُخْرَى فَانْتَفَخَتْ يَدُهُ فَنَزَفَهُ فَلَمَّا رَأَى ذَلِكَ قَالَ ‏ ‏اللَّهُمَّ لَا تُخْرِجْ نَفْسِي حَتَّى تُقِرَّ عَيْنِي مِنْ ‏ ‏بَنِي قُرَيْظَةَ ‏ ‏فَاسْتَمْسَكَ ‏ ‏عِرْقُهُ فَمَا قَطَرَ قَطْرَةً حَتَّى نَزَلُوا عَلَى حُكْمِ ‏ ‏سَعْدٍ ‏ ‏فَأُرْسِلَ إِلَيْهِ فَحَكَمَ أَنْ تُقْتَلَ رِجَالُهُمْ ‏ ‏وَيُسْتَحْيَا نِسَاؤُهُمْ ‏ ‏وَذَرَارِيُّهُمْ ‏ ‏لِيَسْتَعِينَ بِهِمْ الْمُسْلِمُونَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصَبْتَ حُكْمَ اللَّهِ فِيهِمْ وَكَانُوا أَرْبَعَ مِائَةٍ فَلَمَّا فُرِغَ مِنْ قَتْلِهِمْ ‏ ‏انْفَتَقَ ‏ ‏عِرْقُهُ فَمَاتَ ‏","","",""],[14247,14247,"","আমরা দুটো যুক্তি নিয়ে কথা বলেছি এবং ভুলে গেছি যে বাবার বিদায়ের কথা তার চেয়ে বেশী। আমার বাবা মনে রাখার জন্য লিখেছিলেন যে ঈশ্বর তাকে উদ্ধার করেছেন এবং জিজ্ঞেস করেছেন। আমি ঈশ্বরের ইচ্ছার সাথে প্রতারণা করিনি, ঈশ্বর তাকে তার ইচ্ছার প্রতি দৃষ্টি প্রদান করেছেন আর তার ইচ্ছার প্রতি আদেশ দিয়েছেন যে আমি যেন তাকে যেতে পারি ওদের কাছে এমন কোন উপায় নেই যে তাকে মেরে ফেলবে... ...যে তাকে সাহায্য করবে।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏حَاطِبَ بْنَ أَبِي بَلْتَعَةَ ‏ ‏كَتَبَ إِلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏يَذْكُرُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَادَ غَزْوَهُمْ فَدُلَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمَرْأَةِ الَّتِي مَعَهَا الْكِتَابُ فَأَرْسَلَ إِلَيْهَا فَأُخِذَ كِتَابُهَا مِنْ رَأْسِهَا وَقَالَ يَا ‏ ‏حَاطِبُ ‏ ‏أَفَعَلْتَ قَالَ نَعَمْ أَمَا إِنِّي لَمْ أَفْعَلْهُ غِشًّا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏غِشًّا يَا رَسُولَ اللَّهِ ‏ ‏وَلَا نِفَاقًا قَدْ عَلِمْتُ أَنَّ اللَّهَ مُظْهِرٌ رَسُولَهُ وَمُتِمٌّ لَهُ أَمْرَهُ غَيْرَ أَنِّي كُنْتُ عَزِيزًا بَيْنَ ظَهْرِيهِمْ وَكَانَتْ وَالِدَتِي مِنْهُمْ فَأَرَدْتُ أَنْ أَتَّخِذَ هَذَا عِنْدَهُمْ فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏أَلَا أَضْرِبُ رَأْسَ هَذَا قَالَ ‏ ‏أَتَقْتُلُ رَجُلًا مِنْ أَهْلِ ‏ ‏بَدْرٍ ‏ ‏مَا يُدْرِيكَ لَعَلَّ اللَّهَ عَزَّ وَجَلَّ قَدْ اطَّلَعَ عَلَى أَهْلِ ‏ ‏بَدْرٍ ‏ ‏فَقَالَ اعْمَلُوا مَا شِئْتُمْ ‏","","",""],[14248,14248,"","আমরা দু'জন বাক্য নিয়ে কথা বলেছি এবং আমরা আমার বাবার ভালোর জন্য যেতে দেব না। আমি ঈশ্বরের ইচ্ছার জন্য প্রার্থনা করবো এবং আদালতে আত্মসমর্পণ করবো। আল্লাহই হবেন, তাকে বলে ভালো কথা হবে কারণ আমি ভেবেছিলাম সে তার ভাই, গর্ভজাত বা পশু থেকে কিছু একটা নিয়ে এসেছে।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏اسْتَأْذَنَتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْحِجَامَةِ ‏ ‏فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَا طَيْبَةَ ‏ ‏أَنْ ‏ ‏يَحْجُمَهَا ‏ ‏قَالَ ‏ ‏حَسِبْتُ أَنَّهُ كَانَ أَخَاهَا مِنْ الرَّضَاعَةِ أَوْ غُلَامًا لَمْ ‏ ‏يَحْتَلِمْ ‏","","",""],[14249,14249,"","আমরা দু'জন বাক্য দিয়েছি আর আমার বাবাকে ছেড়ে যেতে দিবেন না, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর আমার সাথে যা ঘটেছে তা শহরের কাছে আত্মসমর্পণ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُمْ كَانُوا إِذَا حَضَرُوا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَبَعَثَ بِالْهَدْيِ فَمَنْ شَاءَ مِنَّا أَحْرَمَ وَمَنْ شَاءَ تَرَكَ ‏","","",""],[14250,14250,"","আমরা দুটো যুক্তি নিয়ে কথা বলেছি আর আমাদের বাবার নখের পাশে যেতে দেয়া উচিত না।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى أَنْ يُبَالَ فِي الْمَاءِ الرَّاكِدِ ‏","","",""],[14251,14251,"","আমরা দুজন ঘোড়া নিয়ে কথা বলেছি আর মানুষ বলেছে যে আমার বাবার শাড়িতে সাহায্য করা নিয়ে কথা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَدْخُلُ النَّارَ أَحَدٌ مِمَّنْ بَايَعَ تَحْتَ الشَّجَرَةِ ‏","","",""],[14252,14252,"","আমরা দুটো তর্কের কথা বলেছি আর আমাদের বাবার অস্পষ্ট ধারণা নিয়ে কথা বলতে হবে না। সে আমাকে কে ঘুমাত সেটা বলবে। সে আমাকে দেখেও আমার সাথে কখনো কিছু করতে পারবে না। মানুষকে বলা হয় তার সাথে শয়তানের খেলা করতে।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ رَآنِي فِي النَّوْمِ فَقَدْ رَآنِي إِنَّهُ لَا يَنْبَغِي لِلشَّيْطَانِ أَنْ يَتَمَثَّلَ فِي صُورَتِي وَقَالَ إِذَا حَلَمَ أَحَدُكُمْ فَلَا يُخْبِرَنَّ النَّاسَ بِتَلَعُّبِ الشَّيْطَانِ بِهِ فِي الْمَنَامِ ‏","","",""],[14253,14253,"","আমরা দুটো ঘোড়ার কথা বলেছি আর আমি আমার বাবাকে শাড়ি দিয়ে সাহায্য করার কথা বলেছি। ঈশ্বর তাকে আদেশ দিয়েছেন আর তিনি বললেন যদি তুমি তাকে পছন্দ কর, তাহলে সে জিতবে। সে দেশের তৃতীয়াংশ নিতে না, আর সে তার কাপুরুষদের সাথে না পেরেই তার পথ পরিবর্তন করতে পারে না, যার কাছে ছিল।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا رَأَى أَحَدُكُمْ الرُّؤْيَا يَكْرَهُهَا فَلْيَبْزُقْ عَنْ يَسَارِهِ ثَلَاثًا ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏فَلْيَبْصُقْ ‏ ‏وَلْيَسْتَعِذْ بِاللَّهِ مِنْ الشَّيْطَانِ ثَلَاثًا وَلْيَتَحَوَّلْ عَنْ جَنْبِهِ الَّذِي كَانَ عَلَيْهِ ‏","","",""],[14254,14254,"","আমরা দুটো যুক্তির কথা বলেছি আর তাকে ছেড়ে দিতে দিবেন না, ঈশ্বর আদেশ দিয়েছেন আর সে এমন একজন লোকের মাধ্যমে চলে যাবে যে বারে আটকে ছিল।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ أَمَرَ رَجُلًا كَانَ يَتَصَدَّقُ بِالنَّبْلِ فِي الْمَسْجِدِ أَنْ لَا يَجِيءَ بِهَا إِلَّا وَهُوَ آخِذٌ ‏ ‏بِنُصُولِهَا ‏","","",""],[14255,14255,"","আমরা দুটো ঘোড়ার কথা বলেছি আর আমি আমার বাবাকে বড় করার জন্য সাহায্য করেছি, ঈশ্বর তাকে দাবি করেছেন আর সে বলবে যে সে যা হারিয়েছে তা সে হারিয়ে ফেলেছে.","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ خَيْرَ مَا رُكِبَتْ إِلَيْهِ ‏ ‏الرَّوَاحِلُ ‏ ‏مَسْجِدِي ‏ ‏هَذَا ‏ ‏وَالْبَيْتُ الْعَتِيقُ ‏","","",""],[14256,14256,"","তিনি আমাকে ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং প্রয়োজনের সময়ে তিনি তা পৌঁছে দিয়েছিলেন । ভাগ্য, তাকে আত্মসমর্পণ করতে হবে, তাকে শেখাব কেন সে নিজের কিছু করতে চায়। সে বলল, সে আমাকে তোমাকে মারতে চায় না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ شِنْظِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَرْسَلَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ فَانْطَلَقْتُ ثُمَّ رَجَعْتُ وَقَدْ قَضَيْتُهَا فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَّمْتُ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيَّ قَالَ فَوَقَعَ فِي نَفْسِي مَا اللَّهُ بِهِ أَعْلَمُ قَالَ قُلْتُ لَعَلَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَدَ عَلَيَّ أَنْ أَبْطَأْتُ فَسَلَّمْتُ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيَّ فَوَقَعَ فِي نَفْسِي مَا اللَّهُ أَعْلَمُ أَشَدُّ مِنْ الْأُولَى ثُمَّ سَلَّمْتُ فَرَدَّ عَلَيَّ وَقَالَ ‏ ‏أَمَا إِنَّهُ لَمْ يَمْنَعْنِي أَنْ أَرُدَّ عَلَيْكَ إِلَّا أَنِّي كُنْتُ أُصَلِّي فَكَانَ عَلَى رَاحِلَتِهِ مُتَوَجِّهًا لِغَيْرِ الْقِبْلَةِ ‏","","",""],[14257,14257,"","আমরা আমার বাবার কাছ থেকে আসা প্রায় ১২টা গল্প বলেছিলাম, আমার বাবার ডানা নিয়ে। আল্লাহ তোমার শান্তি আছে, আমি তোমার দিকে ঘুরিয়ে দেব।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏وَاصِلٌ ‏ ‏مَوْلَى ‏ ‏أَبِي عُيَيْنَةَ ‏ ‏حَدَّثَنِي ‏ ‏خَالِدُ بْنُ عُرْفُطَةَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ نَافِعٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَارْتَفَعَتْ رِيحُ ‏ ‏جِيفَةٍ ‏ ‏مُنْتِنَةٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَدْرُونَ مَا هَذِهِ الرِّيحُ هَذِهِ رِيحُ الَّذِينَ يَغْتَابُونَ الْمُؤْمِنِينَ ‏","","",""],[14258,14258,"","আমরা সেই বধিরদের কথা বলেছিলাম, যাদের আমরা বাবার মৃত্যুর কথা বলেছিলাম, সে ঈশ্বরের কাছ থেকে নিজেকে রক্ষা করতে পারবে। তারা ঈশ্বরের কাছে গিয়ে নিজেকে ফিরিয়ে আনতে চায়, ঈশ্বর তাকে বিজ্ঞানের কাজের কাছে সমর্পণ করতে আদেশ দিয়েছেন। সে এটা একটা মেয়েকে দিয়ে দেবে, যে কিনা মারা গেছে... ...সে আমাদের কাছ থেকে গন্ধ পেয়েছে, আর আমাদের কাছ থেকে নিয়ে নিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابَهُ مَرُّوا بِامْرَأَةٍ فَذَبَحَتْ لَهُمْ شَاةً وَاتَّخَذَتْ لَهُمْ طَعَامًا فَلَمَّا رَجَعَ قَالَتْ يَا رَسُولَ اللَّهِ إِنَّا اتَّخَذْنَا لَكُمْ طَعَامًا فَادْخُلُوا فَكُلُوا فَدَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ وَكَانُوا لَا يَبْدَءُونَ حَتَّى يَبْتَدِئَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لُقْمَةً فَلَمْ يَسْتَطِعْ أَنْ ‏ ‏يُسِيغَهَا ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذِهِ شَاةٌ ذُبِحَتْ بِغَيْرِ إِذْنِ أَهْلِهَا فَقَالَتْ الْمَرْأَةُ يَا نَبِيَّ اللَّهِ إِنَّا لَا نَحْتَشِمُ مِنْ آلِ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏وَلَا يَحْتَشِمُونَ مِنَّا نَأْخُذُ مِنْهُمْ وَيَأْخُذُونَ مِنَّا ‏","","",""],[14259,14259,"","আমরা সেই বধিরদের কথা বলেছিলাম যাদের আমরা বলেছি যে ঈশ্বর আমার উপর আছেন। ঈশ্বর নিরাপদে আছেন এবং বাবা ভালো আছেন এবং চলে গেছেন। আপনি এটা চান। আপনি যদি চান, আমি আপনাকে বলছি, আমি আপনাকে বলছি, ঈশ্বর আপনাকে বলছি, আমি আপনাকে বলছি, ঈশ্বর আপনাকে বলছি, আমি শেষ হয়ে যেতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمَّارٌ ‏ ‏سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏أَكَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏رُطَبًا وَشَرِبُوا مَاءً فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا مِنْ النَّعِيمِ الَّذِي تُسْأَلُونَ عَنْهُ ‏","","",""],[14260,14260,"","আমরা বধিরদের কথা বলেছি এবং পার্থক্যটা নিয়ে কথা বলেছি। যুদ্ধের যাত্রা বন্ধ করতে পারবে, সে বলেছিল, আমি তাকে মেরে ফেলব, না হয় আমি তাকে মেরে ফেলব। তার কাছে সে তাকে হঠাৎ করেই দেখেছে সে কি বলছে, আমার ছেলের জন্য না যদি তার মা তাকে খুন করতে না হয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ رَأَيْتُ كَأَنِّي فِي ‏ ‏دِرْعٍ ‏ ‏حَصِينَةٍ وَرَأَيْتُ بَقَرًا مُنَحَّرَةً ‏ ‏فَأَوَّلْتُ ‏ ‏أَنَّ ‏ ‏الدِّرْعَ ‏ ‏الْحَصِينَةَ ‏ ‏الْمَدِينَةُ ‏ ‏وَأَنَّ الْبَقَرَ هُوَ وَاللَّهِ خَيْرٌ قَالَ فَقَالَ لِأَصْحَابِهِ لَوْ أَنَّا أَقَمْنَا ‏ ‏بِالْمَدِينَةِ ‏ ‏فَإِنْ دَخَلُوا عَلَيْنَا فِيهَا قَاتَلْنَاهُمْ فَقَالُوا يَا رَسُولَ اللَّهِ وَاللَّهِ مَا دُخِلَ عَلَيْنَا فِيهَا فِي الْجَاهِلِيَّةِ فَكَيْفَ يُدْخَلُ عَلَيْنَا فِيهَا فِي الْإِسْلَامِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ فَقَالَ شَأْنَكُمْ إِذًا ‏ ‏قَالَ فَلَبِسَ لَأْمَتَهُ قَالَ فَقَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏رَدَدْنَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْيَهُ فَجَاءُوا فَقَالُوا يَا نَبِيَّ اللَّهِ شَأْنَكَ إِذًا فَقَالَ ‏ ‏إِنَّهُ لَيْسَ لِنَبِيٍّ إِذَا لَبِسَ لَأْمَتَهُ أَنْ يَضَعَهَا حَتَّى يُقَاتِلَ ‏","","",""],[14261,14261,"","আমরা নখের কথা বলেছিলাম এবং একটা ভাঙা ছেলেকে বলেছিলাম যে, আমরা আমার ছেলের কথা বলছি । আর তারপর সে আমাকে বলেছে তুমি যা যা যা যা করেছ, তা আমার কাছে বলে দিয়েছে... ...আমি তোমাকে বলেছি আর সে বলেছে যে সে তার স্ত্রী.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَكَثِيرُ بْنُ هِشَامٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ لَهُ فَرَجَعْتُ إِلَيْهِ وَهُوَ عَلَى رَاحِلَتِهِ فَسَلَّمْتُ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيَّ وَرَأَيْتُهُ يَرْكَعُ وَيَسْجُدُ فَتَنَحَّيْتُ عَنْهُ ثُمَّ قَالَ لِي مَا صَنَعْتَ فِي حَاجَتِكَ فَقُلْتُ صَنَعْتُ كَذَا وَكَذَا فَقَالَ ‏ ‏أَمَا إِنَّهُ لَمْ يَمْنَعْنِي أَنْ أَرُدَّ عَلَيْكَ إِلَّا أَنِّي كُنْتُ أُصَلِّي ‏","","",""],[14262,14262,"","আমি আমার দৃঢ়প্রত্যয়কে কিছু সাহায্য করার চেষ্টা করার কথা বলেছিলাম। আমি ঈশ্বরের বার্তাবাহকের সাথে ছিলাম এবং তার কাছে প্রার্থনা করেছিলাম, যেন আমরা এক চমৎকার লক্ষণের কাছে পৌঁছে দিতে পারি। সে আমাকে বলেছিল, সে তার প্রভুর কাছে প্রার্থনা করতে শুরু করল... ...আর তারপর শান্তি ফিরে এল... ...আর তারপর সে একদিন তার ক্লাস নিয়ে গেল, আর সে তা নিয়ে গেল।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ الْمَدَائِنِيُّ مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏أَنْبَأَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَانْتَهَيْنَا إِلَى ‏ ‏مَشْرَعَةٍ ‏ ‏فَقَالَ أَلَا ‏ ‏تُشْرِعُ ‏ ‏يَا ‏ ‏جَابِرُ ‏ ‏قَالَ فَقُلْتُ بَلَى قَالَ فَنَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَشْرَعْتُ ‏ ‏قَالَ ثُمَّ ذَهَبَ لِحَاجَتِهِ وَوَضَعْتُ لَهُ وَضُوءًا فَجَاءَ ‏ ‏فَتَوَضَّأَ ثُمَّ قَامَ فَصَلَّى فِي ثَوْبٍ وَاحِدٍ خَالَفَ بَيْنَ طَرَفَيْهِ فَقُمْتُ خَلْفَهُ فَأَخَذَ بِأُذُنِي فَجَعَلَنِي عَنْ يَمِينِهِ ‏","","",""],[14263,14263,"","ঈশ্বরের দোহাই আমার সাথে কথা বলে, আমাকে ভালবাসা দেয়ার চেয়ে ভালো ছেলে হবার চেয়ে ভালো। একবার যখন সূর্য থেকে সূর্য উঠে আসে, তখন সেই একই বিষয় ভুলে যান । সেই বাসাটা প্রায় তিন রাত ধরে বাসা বলেছিল এবং তাদের মধ্যে কিছুজন বলেছিল । কেটে ফেলতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنِي ‏ ‏ثَوْرُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ وَقْتِ الصَّلَاةِ فَقَالَ صَلِّ مَعِي ‏ ‏فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصُّبْحَ حِينَ طَلَعَ الْفَجْرُ ثُمَّ صَلَّى الظُّهْرَ حِينَ ‏ ‏زَاغَتْ ‏ ‏الشَّمْسُ ثُمَّ صَلَّى الْعَصْرَ حِينَ كَانَ ‏ ‏فَيْءُ ‏ ‏الْإِنْسَانِ مِثْلَهُ ‏ ‏ثُمَّ صَلَّى الْمَغْرِبَ حِينَ وَجَبَتْ الشَّمْسُ ثُمَّ صَلَّى الْعِشَاءَ حِينَ غَيْبُوبَةِ ‏ ‏الشَّفَقِ ‏ ‏ثُمَّ صَلَّى الصُّبْحَ فَأَسْفَرَ ثُمَّ صَلَّى الظُّهْرَ حِينَ كَانَ ‏ ‏فَيْءُ ‏ ‏الْإِنْسَانِ مِثْلَهُ ثُمَّ صَلَّى الْعَصْرَ حِينَ كَانَ ‏ ‏فَيْءُ ‏ ‏الْإِنْسَانِ مِثْلَيْهِ ثُمَّ صَلَّى الْمَغْرِبَ قَبْلَ غَيْبُوبَةِ ‏ ‏الشَّفَقِ ‏ ‏ثُمَّ صَلَّى الْعِشَاءَ فَقَالَ بَعْضُهُمْ ثُلُثَ اللَّيْلِ وَقَالَ بَعْضُهُمْ ‏ ‏شَطْرَهُ ‏","","",""],[14264,14264,"","আমরা তাদের কথা বলেছি তোমাকে মারার চেষ্টা করে। আমার বাবার দোষ আমার বাবার উপর ক্ষমার ব্যাপার। তার মঙ্গলভাবে এবং উত্তম ব্যক্তি হবে তার জীবন ।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏عُتْبَةَ ‏ ‏وَقَالَ ‏ ‏عَلِيٌّ ‏ ‏أَنْبَأَنَا ‏ ‏عُتْبَةُ بْنُ أَبِي حَكِيمٍ ‏ ‏حَدَّثَنِي ‏ ‏حُصَيْنُ بْنُ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُصَبِّحٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏فِي ‏ ‏نَوَاصِيهَا ‏ ‏الْخَيْرُ وَالنَّيْلُ إِلَى يَوْمِ الْقِيَامَةِ وَأَهْلُهَا مُعَانُونَ عَلَيْهَا فَامْسَحُوا ‏ ‏بِنَوَاصِيهَا ‏ ‏وَادْعُوا لَهَا بِالْبَرَكَةِ وَقَلِّدُوهَا وَلَا تُقَلِّدُوهَا ‏ ‏بِالْأَوْتَارِ ‏ ‏وَقَالَ ‏ ‏عَلِيٌّ ‏ ‏وَلَا تُقَلِّدُوهَا الْأَوْتَارَ ‏","","",""],[14265,14265,"","আমরা বাবার স্বপ্ন তোর উপর করুণা দেখানোর জন্য বলেছিলাম, তোমার বাবা তাকে বলে দিয়েছে যে তাকে তার ছেলেকে ছেড়ে দিতে হবে। কথা বললে যদি আমি এটা নিরাপদ স্থানে চলে যাই।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَطَاءٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الْمَلِكِ بْنَ جَابِرِ بْنِ عَتِيكٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا حُدِّثَ الْإِنْسَانُ حَدِيثًا وَالْمُحَدِّثُ يَلْتَفِتُ حَوْلَهُ فَهُوَ أَمَانَةٌ ‏","","",""],[14266,14266,"","আমি ঈশ্বরের কাছে প্রার্থনা করেছিলাম যেন তিনি এটা জানতেন এবং তিনি তার নিজের খাবারে বলতেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ جَابِرٍ الْحَضْرَمِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي الطَّاعُونِ الْفَارُّ مِنْهُ كَالْفَارِّ يَوْمَ الزَّحْفِ وَمَنْ صَبَرَ فِيهِ كَانَ لَهُ أَجْرُ شَهِيدٍ ‏","","",""],[14267,14267,"","আমরা বাবার সঙ্গে কথা বলেছিলাম যে, আমাদের অন্ত্যেষ্টিক্রিয়ার সময় আমরা যখন লড়াই করি, তখন আমাদের খারাপ সময় ছিল । তার কিছু দুঃখ, আমি ঈশ্বরের কাছে প্রার্থনা করব, তিনি তাকে হাত দেবেন, তিনি তাকে তাঁর লোক বলে দিয়েছিলেন, তলোয়ারের মধ্যে সবচেয়ে দ্রুততম।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏حَدَّثَنَا ‏ ‏عُمَارَةُ بْنُ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَسْعَدَ بْنِ زُرَارَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِهِ رَأَى نَاسًا مُجْتَمِعِينَ عَلَى رَجُلٍ فَسَأَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا رَجُلٌ جَهَدَهُ الصِّيَامُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ ‏ ‏الْبِرُّ ‏ ‏الصِّيَامَ فِي السَّفَرِ ‏","","",""],[14268,14268,"","আমরা ঈশ্বরের একজন সন্তান হিসেবে আমার শত্রুকে কথা বলেছি। সে ঈশ্বরের প্রতি প্রার্থনা করে। সে তাকে চিনেছে আর এক বছর কলারে সে একটা গোপন কলারে একটা যুক্তি পরিবর্তন করতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏أَنْبَأَنَا ‏ ‏عُبَيْدُ اللَّهِ يَعْنِي ابْنَ عَمْرٍو الرَّقِّيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُمْرَةٌ فِي رَمَضَانَ تَعْدِلُ حَجَّةً ‏","","",""],[14269,14269,"","আমরা ঈশ্বরের প্রেমের কথা বলছি, কিন্তু আমরা ঈশ্বরের দোহাই চেষ্টা করেছি, কিন্তু ঈশ্বরের দোহাই, আমরা কাপুরুষের কাছে এটা স্বীকার করেছি, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তাকে আত্মসমর্পণ করতে হবে। আমি তাকে ঈশ্বরের হাতে দেখেছি, কিন্তু আমি তাকে আগে কখনো দেখিনি। তিনি আকাশের দিকে তাকিয়ে বলেছেন, তিনি যা বলেছেন, তা তিনি করেছেন। আমরা তাকে খুঁজছি। আমরা তাকে বলেছিলাম, আমি তাকে বলছি, আমি তাকে বলছি, ( গীতসংহিতা ৩৭: ১১) ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তাঁর সঙ্গে কথা বলার জন্য তাঁকে আত্মসমর্পণ করতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَرَأَيْتَ ‏ ‏إِنْ جَاهَدْتُ فِي سَبِيلِ اللَّهِ بِنَفْسِي وَمَالِي حَتَّى أُقْتَلَ صَابِرًا ‏ ‏مُحْتَسِبًا ‏ ‏مُقْبِلًا غَيْرَ ‏ ‏مُدْبِرٍ ‏ ‏أَأَدْخُلُ الْجَنَّةَ قَالَ نَعَمْ فَلَمَّا ‏ ‏وَلَّى ‏ ‏دَعَاهُ فَقَالَ إِلَّا أَنْ يَكُونَ عَلَيْكَ دَيْنٌ لَيْسَ لَهُ عِنْدَكَ وَفَاءٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[14270,14270,"","আমরা ঈশ্বরের ছেলের সাথে কথা বলেছি যে কাপুরুষের ব্যাপারে কথা বলা হয়েছে, একজন মহিলা আমার ছেলেকে ঈশ্বরের অনুগ্রহে ফিরিয়ে নিয়ে যাবে যে তিনি আমার ছেলেকে আনন্দ থেকে উদ্ধার করেছেন। ঈশ্বর আপনার মুখে বলেন যে, তিনি তার পশুগুলোকে ফেলে দিয়েছেন, তিনি তার সন্তানদের দিয়ে চলে গেছেন । তিন বছরের মা আর অন্য দুই মেয়ে।","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏جَاءَتْ ‏ ‏امْرَأَةُ سَعْدِ بْنِ الرَّبِيعِ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِابْنَتَيْهَا مِنْ ‏ ‏سَعْدٍ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ هَاتَانِ ابْنَتَا ‏ ‏سَعْدِ بْنِ الرَّبِيعِ ‏ ‏قُتِلَ أَبُوهُمَا مَعَكَ فِي ‏ ‏أُحُدٍ ‏ ‏شَهِيدًا وَإِنَّ عَمَّهُمَا أَخَذَ مَالَهُمَا فَلَمْ يَدَعْ لَهُمَا مَالًا وَلَا يُنْكَحَانِ إِلَّا وَلَهُمَا مَالٌ قَالَ فَقَالَ يَقْضِي اللَّهُ فِي ذَلِكَ قَالَ فَنَزَلَتْ ‏ ‏آيَةُ الْمِيرَاثِ ‏ ‏فَأَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى عَمِّهِمَا فَقَالَ ‏ ‏أَعْطِ ابْنَتَيْ ‏ ‏سَعْدٍ ‏ ‏الثُّلُثَيْنِ وَأُمَّهُمَا الثُّمُنَ وَمَا بَقِيَ فَهُوَ لَكَ ‏","","",""],[14271,14271,"","আমরা ঈশ্বরের দোহাই দিয়ে ঈশ্বরের সাথে খেলেছি... ...যে কিনা একটি ব্যাতিক্রমীর জন্য বাপ্তাইজিত ছেলে, তার শান্তি কামনা করে... দুজন প্রতিনিধি আমাকে বলেছিল, আমি লর্ডকে তার জন্য প্রার্থনা করতে দেখেছি।","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏أَنْبَأَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏صَلَّى بِأَصْحَابِهِ فِي بَيْتِهِ فَقُلْنَا لَهُ صَلِّ بِنَا كَمَا رَأَيْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَالَ ‏ ‏فَصَلَّى بِنَا فِي مِلْحَفَةٍ فَشَدَّهَا تَحْتَ ‏ ‏الثَّنْدُوَتَيْنِ ‏ ‏وَقَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي ‏","","",""],[14272,14272,"","আমরা ভাবছিলাম আমরা ঈশ্বর দ্বারা ভালো কাজ করেছি এবং আমরা এর থেকে ভাল কিছু করেছি। প্রার্থনা কর, আল্লাহ যদি তার কাছে প্রার্থনা করেন এবং তাকে কিছু জিজ্ঞেস করেন এবং তখন লোকজন যেন হারিয়ে যায়। আমার বাবা তা কোম্পানির কাছে এমন করতো যে তিনি দুর্ঘটনার মধ্যে দিয়ে যেতে না পারতেন। এটা আমার আর তার ছেলের মধ্যে থাকা পাপের নিদর্শন থেকে। উদযাপন করতে, ভালো এবং ভালো, কাঠবিড়ালীর কথা উল্লেখ না করতে, আমি পছন্দ করি আমি কিন্তু আমি এটা দেখেছি, তুমি নিরাপদ, তুমি বলতে পারো প্রথম লড়াই করতে। আমি জানি, আমি জানি, তুমি প্রথম লড়াই করতে পারবে। আমি কি বলেছি? আমি জানি, আমি এটা আমার পছন্দ করি। আমি এটা আমার কাছে একটা সহজ ছিল না। আমি মনে করি, আমি এটা আমার কাছে একটা জিনিস আছে, আমি মনে করি, আমি জানি, আমি এটা আমার কাছে এটা একটা ভাল। আমি যা করছি, আমি মনে করি, আমি শুধু একটা ছোট ছোট মেয়ে। আমি যদি আমার মনে করি, আমি এটা আমার মনে করি, আমি চাই, আমি চাই, আমি এটা আমার কাছে এটা আমার কাছে একটা ভাল সময়। আমি শুধু একটা জিনিস। আমি যা করছি, আমি চাই, আমি চাই, আমি যদি আমি চাই, আমি চাই, আমি চাই, আমি এটা আমার কাছে এটা আমার কাছে একটা ছোট ছিলাম, আমি শুধু একটা ছোট জীবন-----পাক্ষাও করবো। আমি এটা আমার কাছে এটা একটা জিনিস। কিন্তু আমি শুধু একটা জিনিস। কিন্তু আমি যখন আমি চাই, আমি চাই, আমি চাই, আমি এটা আমার কাছে এটা একটা জিনিস। আমি চাই, আমি চাই, আমি এটা আমার কাছে এটা আমার কাছে এটা একটা জিনিস। আমি যখন আমি এটা আমার কাছে এটা আমার জীবনের জীবন-- আর যদি তুমি প্রতারণা না করো","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏أَنْبَأَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صُفُوفِنَا فِي الصَّلَاةِ صَلَاةِ الظُّهْرِ ‏ ‏أَوْ الْعَصْرِ ‏ ‏فَإِذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَنَاوَلُ شَيْئًا ثُمَّ تَأَخَّرَ فَتَأَخَّرَ النَّاسُ فَلَمَّا قَضَى الصَّلَاةَ قَالَ لَهُ ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏شَيْئًا صَنَعْتَهُ فِي الصَّلَاةِ لَمْ تَكُنْ ‏ ‏تَصْنَعُهُ قَالَ ‏ ‏عُرِضَتْ عَلَيَّ الْجَنَّةُ بِمَا فِيهَا مِنْ الزَّهْرَةِ وَالنَّضْرَةِ فَتَنَاوَلْتُ مِنْهَا قِطْفًا مِنْ عِنَبٍ لِآتِيَكُمْ بِهِ فَحِيلَ بَيْنِي وَبَيْنَهُ وَلَوْ أَتَيْتُكُمْ بِهِ لَأَكَلَ مِنْهُ مَنْ بَيْنَ السَّمَاءِ وَالْأَرْضِ لَا يُنْقِصُونَهُ شَيْئًا ثُمَّ عُرِضَتْ عَلَيَّ النَّارُ فَلَمَّا وَجَدْتُ سَفْعَهَا تَأَخَّرْتُ عَنْهَا وَأَكْثَرُ مَنْ رَأَيْتُ فِيهَا النِّسَاءُ اللَّاتِي إِنْ اؤْتُمِنَّ أَفْشَيْنَ وَإِنْ يُسْأَلْنَ بَخِلْنَ وَإِنْ يَسْأَلْنَ ‏ ‏أَلْحَفْنَ ‏ ‏قَالَ ‏ ‏حُسَيْنٌ ‏ ‏وَإِنْ أُعْطِينَ لَمْ يَشْكُرْنَ ‏ ‏وَرَأَيْتُ فِيهَا ‏ ‏لُحَيَّ بْنَ عَمْرٍو ‏ ‏يَجُرُّ ‏ ‏قُصْبَهُ ‏ ‏فِي النَّارِ وَأَشْبَهُ مَنْ رَأَيْتُ بِهِ ‏ ‏مَعْبَدُ بْنُ أَكْثَمَ الْكَعْبِيُّ ‏ ‏قَالَ ‏ ‏مَعْبَدٌ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏أَيُخْشَى عَلَيَّ مِنْ شَبَهِهِ وَهُوَ وَالِدٌ فَقَالَ لَا أَنْتَ مُؤْمِنٌ وَهُوَ كَافِرٌ ‏ ‏قَالَ ‏ ‏حُسَيْنٌ ‏ ‏وَكَانَ أَوَّلَ مَنْ حَمَلَ ‏ ‏الْعَرَبَ ‏ ‏عَلَى عِبَادَةِ الْأَوْثَانِ ‏ ‏قَالَ ‏ ‏حُسَيْنٌ ‏ ‏تَأَخَّرْتُ عَنْهَا وَلَوْلَا ذَلِكَ لَغَشِيَتْكُمْ ‏","","",""],[14273,14273,"","আমরা আমার বাবার সাথে কথা বলেছি যে একজন প্রতিবেশী যে যুদ্ধ করছিল তার কথা। জয় তার বাবার ভুল বলছে এবং তাকে মারার জন্য মেঘ আছে। তার ৬ বছর হবে তাদের বলার জন্য। অনুসরণ করো, আমি তার জন্য পাপ করেছি, আমরা যা বলি তা বলে থাকি","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْجَوَّابِ ‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ رُزَيْقٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يُقَالُ لَهُ ‏ ‏أَبُو شُعَيْبٍ ‏ ‏وَكَانَ لَهُ غُلَامٌ لَحَّامٌ فَقَالَ لَهُ اجْعَلْ لَنَا طَعَامًا ‏ ‏لَعَلِّي ‏ ‏أَدْعُو رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَادِسَ سِتَّةٍ فَدَعَاهُمْ فَاتَّبَعَهُمْ رَجُلٌ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذَا قَدْ اتَّبَعَنَا أَفَتَأْذَنُ لَهُ قَالَ نَعَمْ ‏","","",""],[14274,14274,"","আমরা দুই দাড়ির কথা বলেছি, অথবা না, অবশ্যই আমার ছেলের উত্তর শুনে আমরা খুশি হয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏شُرَحْبِيلُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ثَمَنِ الْكَلْبِ وَقَالَ طُعْمَةٌ جَاهِلِيَّةٌ ‏","","",""],[14275,14275,"","আমরা নিশ্চিত হয়েছি যে নাবিকদের অনুসন্ধানের মাধ্যমে আমরা ঈশ্বরের সাহায্য নিয়ে কথা বলেছি। গুড লর্ড বলেছে যে ঈশ্বর লর্ডকে জয় করেছেন এবং লর্ড কখনো লর্ডের কাছে আসেনি। গাড়িতে করে নিচে, অর্ধেক বাসা।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏أَبَا الزُّبَيْرِ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَذْكُرُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فِيمَا سَقَتْ الْأَنْهَارُ وَالسَّيْلُ الْعُشُورُ وَفِيمَا سُقِيَ ‏ ‏بِالسَّانِيَةِ ‏ ‏نِصْفُ الْعُشُورِ ‏","","",""],[14276,14276,"","আমরা বাবাকে একটা মোস্টের কথা বলেছিলাম বাবা কি খুশি হতে পারে তা নিয়ে। আমি ঈশ্বরের কাছে ছিলাম, সে নরকের বিশ্ব উদ্ধার করবে এবং কয়েক বছর পর সে ভাগ হয়ে যাবে। আমি এটা করব। আমি এটা করতে চাই। আমি জানি, আমি যদি আমার বন্ধু, আমি আমার বন্ধু, আমি আমার বন্ধু, আমি আমার বাবা, আমি আমার বাবা, আমি আমার সাথে ছিলাম, আমি আমার বাবা, আমি কিন্তু আমি আমার বাবা, আমি যদি আমার সাথে নেই। আমি আমার বাবা, আমি আমার বাবা, আমি আমার সাথে ছিলাম, আমি যদি আমার বাবা, আমি আমার বাবা, আমি এই পৃথিবীর মানুষ হয়ে যাই। আমি যদি না থাকি, আমি জানি যে, আমি এই পৃথিবীতে নেই, আমি কি করবো। আমি জানি যে, আমি কি করবো। আমি জানি না, আমি যদি না, আমি জানি, আমি জানি যে, আমি এই পৃথিবীটি আমার বাবাও না। আমি যদি না কেন, আমি এই পৃথিবী থেকে বড় হয়ে যাবে। আমি এই পৃথিবীতে থাকবো। আমি যদি এই ভণ্ডকে মেরে ফেলি তাহলে তাকে মেরে ফেলব, কিন্তু ঈশ্বর আমার সাথে কথা বলতে পারেন আমি এত সুখী হতে যাচ্ছি, তাদের আশ্রয় বা সুরক্ষা থেকে বঞ্চিত করা হচ্ছে। ঐ মোটাটা, ধূসর দ্বারা অনুপ্রাণিত।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو شِهَابٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ ‏ ‏الْجِعْرَانَةِ ‏ ‏وَهُوَ يَقْسِمُ فِضَّةً فِي ثَوْبِ ‏ ‏بِلَالٍ ‏ ‏لِلنَّاسِ فَقَالَ ‏ ‏رَجُلٌ ‏ ‏يَا رَسُولَ اللَّهِ اعْدِلْ فَقَالَ ‏ ‏وَيْلَكَ وَمَنْ يَعْدِلُ إِذَا لَمْ أَعْدِلْ لَقَدْ خِبْتُ إِنْ لَمْ أَكُنْ أَعْدِلُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ دَعْنِي أَقْتُلْ هَذَا الْمُنَافِقَ فَقَالَ مَعَاذَ اللَّهِ أَنْ يَتَحَدَّثَ النَّاسُ أَنِّي أَقْتُلُ أَصْحَابِي إِنَّ هَذَا وَأَصْحَابَهُ يَقْرَءُونَ الْقُرْآنَ لَا ‏ ‏يُجَاوِزُ ‏ ‏حَنَاجِرَهُمْ ‏ ‏أَوْ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ ‏ ‏مُرُوقَ ‏ ‏السَّهْمِ مِنْ الرَّمِيَّةِ ‏","","",""],[14277,14277,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি যে সমস্ত দড়িগুলো উৎপন্ন করেছেন, সেগুলো পেশ করবেন যাতে তিনি তার উদ্‌বিগ্নতা দূর করতে পারেন । এতে ক্ষতিগ্রস্ত হবে, হয় ভেঙ্গে পড়বে।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ ‏ ‏عَنْ ‏ ‏الرَّبِيعِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مَوْلُودٍ يُولَدُ عَلَى الْفِطْرَةِ حَتَّى يُعْرِبَ عَنْهُ لِسَانُهُ فَإِذَا أَعْرَبَ عَنْهُ لِسَانُهُ إِمَّا شَاكِرًا وَإِمَّا كَفُورًا ‏","","",""],[14278,14278,"","আমরা কথা বলেছি কিভাবে আমি একবার করতে এবং আমার সর্বোচ্চ দুটি শক্তি দিয়ে করতে পারি। ঈশ্বর বলেছেন যে আমরা একজন পিপাসার্ত হবে। সে বলেছে, সে এটা করেছে। আমরা তার ভেতরে দুই ইঞ্চির কথা বলতে পারি। আমরা জানি, আমরা কি ভাবে এটা করতে পারি? আমি এটা করতে পারি। আমি এটা করতে পারি। আমি এটা করতে পারি। আমি জানি না, আমি এটা করতে পারি। আমি এটা করতে পারি। আমি জানি না যে, আমি যদি আমার কাছে এটা করি, আমি এটা করতে পারি। আমি এটা আমার কাছে একটা সহজ। আমি যা চাই, আমি যদি চাই, আমি চাই, আমি শুধু এটা করি, আমি শুধু চাই, আমি শুধু চাই, আমি যদি এটা করি, আমি চাই, আমি এটা করি, আমি এটা করি, আমি এটা করি, আমি যদি আমার কাছে একটা ছোট নই। আমি চাই, আমি চাই যে আমি এটা করি, আমি এটা আমার কাছে একটা ছোট কাজ করি। আমাদের কথাবার্তা মদ খেয়ে আমাদের ক্ষুধার্থি হওয়ার কথা ছিল।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏وَحُصَيْنُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَصَابَنَا عَطَشٌ ‏ ‏بِالْحُدَيْبِيَةِ ‏ ‏فَجَهَشْنَا ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ يَدَيْهِ ‏ ‏تَوْرٌ ‏ ‏فِيهِ مَاءٌ فَقَالَ بِأَصَابِعِهِ هَكَذَا فِيهَا وَقَالَ ‏ ‏خُذُوا بِسْمِ اللَّهِ قَالَ فَجَعَلَ الْمَاءُ ‏ ‏يَتَخَلَّلُ ‏ ‏مِنْ بَيْنِ أَصَابِعِهِ كَأَنَّهَا عُيُونٌ فَوَسِعَنَا وَكَفَانَا ‏ ‏وَقَالَ ‏ ‏حُصَيْنٌ ‏ ‏فِي حَدِيثِهِ فَشَرِبْنَا وَتَوَضَّأْنَا ‏","","",""],[14279,14279,"","আমরা আমার বাবাকে একটা মুরগির চেয়েও বেশি কিছু বলেছি, সে ঈশ্বরকে বলে। আর আমরা যা ভাবছি তা করাই ভুল।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏حَجَّاجِ بْنِ أَبِي زَيْنَبَ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِعْمَ الْإِدَامُ الْخَلُّ مَا أَقْفَرَ بَيْتٌ فِيهِ خَلٌّ ‏","","",""],[14280,14280,"","আমরা আমাদের বাবার সাথে তার ভালবাসার কথা বলেছিলাম, ঈশ্বরের দয়ায় আমরা ঈশ্বরের দয়ায় ভ্রমণ করেছি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏نَحَرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏سَبْعِينَ بَدَنَةً الْبَدَنَةُ عَنْ سَبْعَةٍ ‏","","",""],[14281,14281,"","বাবা আমার রক্ত নিয়ে কথা বলার চেষ্টা করছেন বলে আমরা বাবাকে বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ جَعْفَرُ بْنُ أَبِي وَحْشِيَّةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏دَعَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَا طَيْبَةَ ‏ ‏فَحَجَمَهُ ‏ ‏قَالَ فَسَأَلَهُ كَمْ ضَرِيبَتُكَ قَالَ ثَلَاثَةُ ‏ ‏آصُعٍ ‏ ‏قَالَ فَوَضَعَ عَنْهُ ‏ ‏صَاعًا ‏","","",""],[14282,14282,"","আমরা প্রভুর হাত দিয়ে ঈশ্বরের উত্তর নিয়ে কথা বলেছি। ঈশ্বর ওকে প্রার্থনা করেছেন এবং পাপবাজকে উদ্ধার করেছেন। ভালো মানুষ সবসময় মনোযোগ দেয়।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّائِبَةُ ‏ ‏جُبَارٌ ‏ ‏وَالْجُبُّ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏ ‏قَالَ ‏ ‏و قَالَ ‏ ‏الشَّعْبِيُّ ‏ ‏الرِّكَازُ ‏ ‏الْكَنْزُ ‏ ‏الْعَادِيُّ ‏","","",""],[14283,14283,"","আমরা প্রভুর হাত কথা বলেছিলাম... ...ঈশ্বরের উত্তর নিয়ে কথা বলছি, সে ঈশ্বরের ইচ্ছার কথা জিজ্ঞেস করলো, আর সে আমার কাছে পৌঁছে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ الْيَوْمَ عَلَى دِينٍ وَإِنِّي مُكَاثِرٌ بِكُمْ الْأُمَمَ فَلَا تَمْشُوا بَعْدِي ‏ ‏الْقَهْقَرَى ‏","","",""],[14284,14284,"","বাবা আমার মন পরিবর্তন করে বলেছিলেন, ভালো কথা বলেছেন, তিনি আমাদের সাথে তাঁর সাথে থাকবেন, তিনি তাকে বহন করবেন, এটা একটা অন্ত্যেষ্টিক্রিয়া। আপনি কি মনে করবেন? আমি জানি না, আপনি কি? আপনি আমার বাবা আমার বাবা আমার সাথে আছেন? ভাল, আমার বাবা আমার বাবা আমার সাথে আছেন, ভালো আছেন, তিনি বললেন, তিনি আমাদের সাথে আছেন, তিনি আমাদের সাথে আছেন। তিনি আমাদের সাথে আছেন, তিনি আমাদের সাথে আছেন, তিনি আমাদের সাথে আছেন। তিনি আমাদের সাথে আছেন, তিনি আমাদের সাথে আছেন। তিনি আমাদের সাথে আছেন। তিনি আমাদের সাথে আছেন, তিনি আমাদের সাথে আছেন। তিনি আমাদের সাথে আছেন। তারা মৃত না তারপর কবর তারা প্রদর্শন করা হয়.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ مِقْسَمٍ ‏ ‏حَدَّثَنِي ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَرَّتْ بِنَا جَنَازَةٌ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقُمْنَا مَعَهُ فَذَهَبْنَا لِنَحْمِلَهَا إِذَا هِيَ جَنَازَةُ يَهُودِيَّةٍ فَقُلْنَا يَا رَسُولَ اللَّهِ إِنَّهَا جَنَازَةُ يَهُودِيَّةٍ قَالَ ‏ ‏إِنَّ لِلْمَوْتِ ‏ ‏فَزَعًا ‏ ‏فَإِذَا رَأَيْتُمْ الْجِنَازَةَ فَقُومُوا لَهَا ‏","","",""],[14285,14285,"","আমার হিংসার কথা বলেছিলাম, এক পরিশ্রমী ছেলে আমার সঙ্গে কথা বলেছিল । ( আদিপুস্তক ১: ২৭) ঈশ্বরের কাছে এবং ঈশ্বরের কাছে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏وَمُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏عَطَاءٌ ‏ ‏وَقَالَ ‏ ‏ابْنُ مُصْعَبٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَتْ لِرِجَالٍ فُضُولُ أَرَضِينَ فَكَانُوا يُؤَاجِرُونَهَا عَلَى الثُّلُثِ وَالرُّبُعِ وَالنِّصْفِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَزْرَعْهَا أَوْ لِيَمْنَحْهَا أَخَاهُ فَإِنْ أَبَى فَلْيُمْسِكْ أَرْضَهُ ‏","","",""],[14286,14286,"","আমরা সেই ঈর্ষাপরায়ণ বাবার সম্বন্ধে কথা বলেছিলাম, যিনি ঈশ্বরকে বলে যে ঈশ্বর তা দিতে চান এবং তিনি পৃথিবীর তৃষ্ণা দূর করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏حَدَّثَنَا ‏ ‏مَاعِزٌ التَّمِيمِيُّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَرْشُ إِبْلِيسَ عَلَى الْبَحْرِ يَبْعَثُ سَرَايَاهُ فِي كُلِّ يَوْمٍ يَفْتِنُونَ النَّاسَ فَأَعْظَمُهُمْ عِنْدَهُ مَنْزِلَةً أَعْظَمُهُمْ فِتْنَةً لِلنَّاسِ ‏","","",""],[14287,14287,"","আমরা আমাদের যে সুবিধাগুলো আছে তা বিচার করার চেষ্টা করেছি, কিন্তু এটা জয়ের ব্যাপার। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং আমি তার জন্য প্রার্থনা করছি এবং আমরা যে সমস্ত খাবার খাই, আমরা পান করব এবং পরাজিত হব না। যখন তুমি তরুণ হও এবং উন্নতি কর... ...আর রাজার আত্মার ফল বুঝতে পারো।","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏مَاعِزٍ التَّمِيمِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيَأْكُلُ أَهْلُ الْجَنَّةِ قَالَ نَعَمْ وَيَشْرَبُونَ وَلَا يَبُولُونَ فِيهَا وَلَا ‏ ‏يَتَغَوَّطُونَ ‏ ‏وَلَا ‏ ‏يَتَنَخَّمُونَ ‏ ‏إِنَّمَا يَكُونُ ذَلِكَ ‏ ‏جُشَاءً ‏ ‏وَرَشْحًا ‏ ‏كَرَشْحِ ‏ ‏الْمِسْكِ ‏ ‏وَيُلْهَمُونَ التَّسْبِيحَ وَالتَّحْمِيدَ كَمَا تُلْهَمُونَ النَّفَسَ ‏","","",""],[14288,14288,"","আমরা সঠিক বাবার কথা বলেছিলাম যে ঈশ্বর আমাকে সাহায্য করেছেন, সে বলত, শহরের হয়তো তাদের উপাসনা করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏عَنْ ‏ ‏مَاعِزٍ التَّمِيمِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ الشَّيْطَانَ قَدْ يَئِسَ أَنْ يَعْبُدَهُ الْمُصَلُّونَ وَلَكِنْ فِي ‏ ‏التَّحْرِيشِ ‏ ‏بَيْنَهُمْ ‏","","",""],[14289,14289,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাকে বলেন যে, তিনি কার কাছে প্রার্থনা করেছেন । আগ্রহ, সবচেয়ে ভালো আর সেরাটা হবে... ...তুমি তার প্রতিশ্রুতির জন্য যা করেছিলে তার সাথে তার আবেগ থাকবে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ حِينَ يَسْمَعُ النِّدَاءَ اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ آتِ ‏ ‏مُحَمَّدًا ‏ ‏الْوَسِيلَةَ وَالْفَضِيلَةَ وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي أَنْتَ وَعَدْتَهُ إِلَّا حَلَّتْ لَهُ الشَّفَاعَةُ يَوْمَ الْقِيَامَةِ ‏","","",""],[14290,14290,"","আমরা একটা বাসা নিয়ে কথা বলেছি, কিন্তু আমরা একটা ছেলে নিয়ে দ্বিধায় আছি যে আমি জন্ম দেব। আমি ড্রাগনকে বলে দিচ্ছি, শহরে আসতে আর এটা হয়তো কবর পর্যন্ত চলে গেছে। কাপুরুষ যে মারা যেতে পারত, সে ঈশ্বরকে তার নাম বলতে ভয় পেতে বলেছিল আর তাকে বলতে হবে যে তার ছেলে নাকি ঈশ্বরের নামে শপথ করে বলতে হবে, আল্লাহ্ আত্মসমর্পণ করেছেন এবং মারা যেতে পারেন আমি শুনেছি ভগবানের পতাকায় এসে তার প্রভুর কাছে এসে পড়েছে, সে বলবে কে দেবতাদের ভয় পায়, আমি মুরগীর কাছে যাচ্ছি না।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ أَمِيرًا مِنْ أُمَرَاءِ الْفِتْنَةِ قَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَكَانَ قَدْ ذَهَبَ بَصَرُ ‏ ‏جَابِرٍ ‏ ‏فَقِيلَ ‏ ‏لِجَابِرٍ ‏ ‏لَوْ تَنَحَّيْتَ عَنْهُ فَخَرَجَ يَمْشِي بَيْنَ ابْنَيْهِ فَنُكِّبَ فَقَالَ تَعِسَ مَنْ أَخَافَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ابْنَاهُ ‏ ‏أَوْ أَحَدُهُمَا ‏ ‏يَا ‏ ‏أَبَتِ وَكَيْفَ أَخَافَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ مَاتَ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَخَافَ أَهْلَ ‏ ‏الْمَدِينَةِ ‏ ‏فَقَدْ أَخَافَ مَا بَيْنَ جَنْبَيَّ ‏","","",""],[14291,14291,"","আমরা একটা বাসা সম্বন্ধে কথা বলেছিলাম, যেখানে আমরা বিয়ের জন্য চেষ্টা করার চেষ্টা করেছিলাম । আমি তাকে বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তাকে তার কাছে সমর্পণ করবেন... ...যে মানুষ তোমাকে এবং তোমার দাসের কাছে বলবে, ঈশ্বর আমাকে এটা করতে দিয়েছেন! সে নিজের মত জিতে যায়, ধূসরের স্টকটা তো চলছেই।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏بَصَرَ عَيْنِي وَسَمِعَ أُذُنِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْجِعْرَانَةِ ‏ ‏وَفِي ثَوْبِ ‏ ‏بِلَالٍ ‏ ‏فِضَّةٌ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْبِضُهَا لِلنَّاسِ ‏ ‏يُعْطِيهِمْ فَقَالَ ‏ ‏رَجُلٌ ‏ ‏اعْدِلْ قَالَ وَيْلَكَ ‏ ‏وَمَنْ يَعْدِلُ إِذَا لَمْ أَكُنْ أَعْدِلُ قَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏يَا رَسُولَ اللَّهِ دَعْنِي أَقْتُلْ هَذَا الْمُنَافِقَ الْخَبِيثَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَاذَ اللَّهِ أَنْ يَتَحَدَّثَ النَّاسُ أَنِّي أَقْتُلُ أَصْحَابِي إِنَّ هَذَا وَأَصْحَابَهُ يَقْرَءُونَ الْقُرْآنَ لَا ‏ ‏يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏","","",""],[14292,14292,"","আমরা যে পরিবর্তনের কথা বলেছি, আমরা তার কথা বলেছি, এমনকি প্রভু তার জন্য প্রার্থনা করেছেন এবং আমার বিশ্বাসের লোকদের কাছে তার গান পৌঁছে দিয়েছেন। আমি আপনাকে এবং যারা তাকে হত্যা করব। আমি কথা দিচ্ছি না, আমি এই ভণ্ডকে মেরে ফেলব, মা'কে মেরে ফেলার কথা। আমি ছেড়ে দেব। লর্ডের বাবার সাথে কথা বলেছে। কিন্তু আমি ভেবেছিলাম, সেদিনই আমাকে অতিথিদের সাথে কথা বলতে হবে। ম্যান।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَنَائِمَ ‏ ‏هَوَازِنَ ‏ ‏بَيْنَ النَّاسِ ‏ ‏بِالْجِعْرَانَةِ ‏ ‏قَامَ رَجُلٌ مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏فَقَالَ اعْدِلْ يَا ‏ ‏مُحَمَّدُ ‏ ‏فَقَالَ وَيْلَكَ ‏ ‏وَمَنْ يَعْدِلُ إِذَا لَمْ أَعْدِلْ لَقَدْ خِبْتُ وَخَسِرْتُ إِنْ لَمْ أَعْدِلْ قَالَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ أَلَا أَقُومُ فَأَقْتُلَ هَذَا الْمُنَافِقَ قَالَ مَعَاذَ اللَّهِ أَنْ تَتَسَامَعَ الْأُمَمُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏يَقْتُلُ أَصْحَابَهُ ثُمَّ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذَا وَأَصْحَابًا لَهُ يَقْرَءُونَ الْقُرْآنَ لَا ‏ ‏يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏الْمِرْمَاةُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏قَالَ ‏ ‏مُعَاذٌ ‏ ‏فَقَالَ ‏ ‏لِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏فَعَرَضْتُ هَذَا الْحَدِيثَ عَلَى ‏ ‏الزُّهْرِيِّ ‏ ‏فَمَا خَالَفَنِي إِلَّا أَنَّهُ قَالَ ‏ ‏النَّضِيَّ قُلْتُ الْقِدْحَ فَقَالَ أَلَسْتَ بِرَجُلٍ عَرَبِيٍّ ‏","","",""],[14293,14293,"","আমরা ঈশ্বরের চেয়ে ভালো কিছু পাওয়ার চেষ্টা করেছি যা আমার সাথে ঘটেছে। ঈশ্বর তাকে আদেশ দিয়েছেন এবং তিনি তাকে উদ্ধার করেছেন । আমরা সবাই যে ভগবানকে রক্ষা করেছি, সে হয় ঈশ্বরের কাছে প্রার্থনা করে...","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنِي ‏ ‏الزُّبَيْدِيُّ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبَانَ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُرِيَ اللَّيْلَةَ رَجُلٌ صَالِحٌ أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏نِيطَ ‏ ‏بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنِيطَ ‏ ‏عُمَرُ ‏ ‏بِأَبِي بَكْرٍ ‏ ‏وَنِيطَ ‏ ‏عُثْمَانُ ‏ ‏بِعُمَرَ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏فَلَمَّا قُمْنَا مِنْ عِنْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْنَا أَمَّا الرَّجُلُ الصَّالِحُ فَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَمَّا ذِكْرُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏نَوْطِ ‏ ‏بَعْضِهِمْ لِبَعْضٍ فَهُمْ وُلَاةُ هَذَا الْأَمْرِ الَّذِي بَعَثَ اللَّهُ بِهِ نَبِيَّهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[14294,14294,"","বাবাকে সাহায্য করার চেষ্টা আমরা যেভাবে চেষ্টা করেছিলাম, সেই বিষয়ে আমরা কথা বলেছিলাম । সক্রিয় করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏سَيَّارٌ أَبُو الْحَكَمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ أَحَدُكُمْ لَيْلًا فَلَا يَأْتِ أَهْلَهُ ‏ ‏طُرُوقًا ‏ ‏كَيْ ‏ ‏تَسْتَحِدَّ ‏ ‏الْمُغِيبَةُ ‏ ‏وَتَمْتَشِطَ ‏ ‏الشَّعِثَةُ ‏","","",""],[14295,14295,"","আমি তাকে জীবিত রাখার জন্য আমার ছেলের অনেক কষ্ট করে কথা বলেছি, আমি এটা করার জন্য ১০০ বছর চেষ্টা করছি আর আমি আমার হাত তুলে নিচ্ছি তুমি আমার হাতে ব্যবসা করেছ আর এটা বলা ভালো নাম!","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏وَحُجَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كُنَّا يَوْمَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏أَلْفًا وَأَرْبَعَ مِائَةٍ فَبَايَعْنَاهُ ‏ ‏وَعُمَرُ ‏ ‏آخِذٌ بِيَدِهِ تَحْتَ الشَّجَرَةِ وَهِيَ سَمُرَةٌ وَقَالَ ‏ ‏بَايَعْنَاهُ عَلَى أَنْ لَا نَفِرَّ وَلَمْ نُبَايِعْهُ عَلَى الْمَوْتِ ‏","","",""],[14296,14296,"","আমরা একটা মইর ব্যাপারে কথা বলেছি ধূসর অধ্যাপনা সহ, আমি ঈশ্বরের কাছে প্রার্থনা করব, সে এটা পেয়ে যাবে আর সে আমাকে একটা স্বপ্ন দেবে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ مُسْلِمِ بْنِ رُومَانَ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ مُحَمَّدُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ أَنَّ رَجُلًا أَعْطَى امْرَأَةً صَدَاقًا مِلْءَ يَدَيْهِ طَعَامًا كَانَتْ لَهُ حَلَالًا ‏","","",""],[14297,14297,"","আমরা নাবিক অথবা সমুদ্রের প্রতি আমার ভালোবাসা নিয়ে সাহায্য করার বিষয়ে কথা বলেছিলাম । একটা শিল্পায় আমরা ঈশ্বরকে কখনও থাকতে বলিনি ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحَارِثِ ‏ ‏أَوْ ‏ ‏ابْنِ أَبِي الْحَارِثِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَجُلٌ مِنْ أَصْحَابِهِ عَلَى رَجُلٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فِي ‏ ‏حَائِطٍ ‏ ‏وَهُوَ ‏ ‏يُحَوِّلُ ‏ ‏الْمَاءَ فَقَالَ هَلْ عِنْدَكَ مَاءٌ بَاتَ هَذِهِ اللَّيْلَةَ فِي ‏ ‏شَنٍّ ‏ ‏وَإِلَّا ‏ ‏كَرَعْنَا ‏ ‏قَالَ نَعَمْ يَا رَسُولَ اللَّهِ فَانْطَلَقَ بِهِ إِلَى ‏ ‏الْعَرِيشِ ‏ ‏فَحَلَبَ لَهُ شَاةً ثُمَّ صَبَّ عَلَيْهِ مَاءً بَاتَ فِي ‏ ‏شَنٍّ ‏ ‏فَشَرِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَقَى صَاحِبَهُ ‏","","",""],[14298,14298,"","আমরা কথা বলেছি, আমরা যা বলছি, তার বাবা-মা ঘোড়া নিয়ে আসছে, সে জেনের হাতে তাকে মৃত্যুর হাত থেকে মুক্তি দিতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَيْثُ ‏ ‏أَفَاضَ ‏ ‏مِنْ ‏ ‏عَرَفَةَ ‏ ‏جَعَلَ يَقُولُ بِيَدِهِ ‏ ‏السَّكِينَةَ ‏ ‏عِبَادَ اللَّهِ ‏ ‏السَّكِينَةَ ‏ ‏عِبَادَ اللَّهِ ‏","","",""],[14299,14299,"","আমার বাবার ভালো লোকদের ব্যাপারে আমরা কথা বলেছি, তিনি আমার প্রার্থনা রক্ষা করেছেন এবং আমাদের উত্তরসূরী দুই সামারের কথা বর্ণনা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى ‏ ‏النَّجَاشِيِّ ‏ ‏وَصَفَفْنَا خَلْفَهُ صَفَّيْنِ ‏","","",""],[14300,14300,"","আমরা বাবা বা মা'র সাথে কথা বলেছি, আমি আমার বন্ধুদের রক্ষা করতে পারবো, আমরা তার চেয়ে ভালো কাজ করেছি। সে তার কাছে প্রার্থনা করেছিল, আর সে আত্মসমর্পণ করতো যখন তারা আগুন থেকে বের হয়ে এসেছিল। অপরাধী.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسُ بْنُ سُلَيْمٍ الْعَنْبَرِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ الْفَقِيرُ ‏ ‏حَدَّثَنَا ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ قَوْمًا يَخْرُجُونَ مِنْ النَّارِ يَحْتَرِقُونَ فِيهَا إِلَّا ‏ ‏دَارَاتِ ‏ ‏وُجُوهِهِمْ حَتَّى يَدْخُلُوا الْجَنَّةَ ‏","","",""],[14301,14301,"","আমরা যাজকের ছেলের থেকে ভাল কথা বলেছি যে আপনাকে রাজার হৃদয়ে নিয়ে আসতে সাহায্য করেছে, আমি শুনেছি ভালোর জন্য আমি আমার সবচেয়ে ভালো স্বার্থের কথা। বছরের জেদের সাথে মাথা নত করে, আর এই বাবা-মায়ের কাছে মাথা নত করে না।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ الْهَادِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عَبْدِ اللَّهِ بْنِ الْحَكَمِ ‏ ‏عَنْ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏غَطُّوا الْإِنَاءَ ‏ ‏وَأَوْكِئُوا ‏ ‏السِّقَاءَ ‏ ‏فَإِنَّ فِي السَّنَةِ لَيْلَةً يَنْزِلُ فِيهَا وَبَاءٌ لَا يَمُرُّ بِإِنَاءٍ لَمْ يُغَطَّ وَلَا ‏ ‏سِقَاءٍ ‏ ‏لَمْ ‏ ‏يُوكَ ‏ ‏إِلَّا وَقَعَ فِيهِ مِنْ ذَلِكَ الْوَبَاءِ ‏","","",""],[14302,14302,"","আমরা কুকুর অথবা কুকুরকে হারিয়ে দিয়েছি । তারা ঈশ্বরের কাছ থেকে এসেছে, আর তারপর সে বলেছে সে কিছু বলছে, এটা একটা প্রতারণার মত। হে ঈশ্বর।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ الْهَادِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَلِيِّ بْنِ الْحُسَيْنِ ‏ ‏أَنَّهُ قَالَ ‏ ‏بَلَغَنِي أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَقِلُّوا الْخُرُوجَ ‏ ‏بَعْدَ ‏ ‏هَدْأَةٍ فَإِنَّ لِلَّهِ عَزَّ وَجَلَّ خَلْقًا يَبُثُّهُمْ فَإِذَا سَمِعْتُمْ نُبَاحَ الْكَلْبِ أَوْ ‏ ‏نُهَاقَ الْحُمُرِ فَاسْتَعِيذُوا بِاللَّهِ مِنْ الشَّيْطَانِ ‏ ‏و قَالَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ قَالَ ‏ ‏يَزِيدُ ‏ ‏وَحَدَّثَنِي ‏ ‏هَذَا الْحَدِيثَ ‏ ‏شُرَحْبِيلُ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ إِنَّهُ سَمِعَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[14303,14303,"","আমরা দুজন অপূর্ব পিতার উপর দুটো অবৈধ সন্তানের জন্ম দিয়েছি, যার মানে আমাদের বাবার ছেলের কাছে একটা পিপপির কথা বলা. ঈশ্বরের প্রার্থনা তাকে তার কাছে প্রার্থনা করবে এবং আমরা যে পাপ তৈরি করেছি তার মত আত্মসমর্পণ করব একটি প্রান্তরে ছেলে, পাইলট বলেছিল আমি জানতাম না কিভাবে ভবিষ্যদ্বাণী করতে হয়.","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَيَّانَ أَبُو خَالِدٍ يَعْنِي الْأَحْمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏رَمَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِ حَصَى ‏ ‏الْخَذْفِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَيَّانَ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏لَا أَدْرِي بِكَمْ رَمَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[14304,14304,"","আমরা ঈশ্বরের বার্তাবাহকের কাছে গিয়ে তার জন্য প্রার্থনা করে আপনার ছেলেকে বলতে চাই যে হঠাৎ আমাদের যেতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يَقُولُ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ نَقُولُ لَبَّيْكَ بِالْحَجِّ ‏ ‏فَأَمَرَنَا فَجَعَلْنَاهَا عُمْرَةً ‏","","",""],[14305,14305,"","আমরা একটা প্লাজমা-ডুল পরা কুত্তার বাচ্চা সম্পর্কে কথা বলেছিলাম... ...যে আমার সাথে ভালো একটা মুণ্ডু পরে আছে, ঈশ্বর বলেছেন আমরা ঈশ্বরের প্রতিজ্ঞা উপভোগ করেছি এবং সৃষ্টিকর্তাকে শেখানো হয়েছে। শেষ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏وَعَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏تَمَتَّعْنَا مُتْعَتَيْنِ عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَجَّ وَالنِّسَاءَ ‏ ‏فَنَهَانَا ‏ ‏عُمَرُ ‏ ‏عَنْهُمَا فَانْتَهَيْنَا ‏","","",""],[14306,14306,"","আমরা আমার বাবা গেম খেলছিলাম যখন আমরা ঈশ্বরকে বাঁচাতে চেষ্টা করছিলাম। ঈশ্বর বলেছিলেন, আমরা যখন প্রথম যে সংবাদ পেয়েছি তা ঈশ্বরের দোহাই। একটি ভালো আলো যা তিনি একটা ট্রাঙ্কে স্থাপন করেছেন। আমাদের সময় ছেড়ে পালিয়ে যাওয়ার থেকে বিরত করা হয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمَلِيحِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏إِنَّ أَوَّلَ خَبَرٍ قَدِمَ عَلَيْنَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ امْرَأَةً كَانَ لَهَا ‏ ‏تَابِعٌ ‏ ‏قَالَ فَأَتَاهَا فِي صُورَةِ طَيْرٍ فَوَقَعَ عَلَى جِذْعٍ لَهُمْ قَالَ فَقَالَتْ أَلَا تَنْزِلُ فَنُخْبِرَكَ وَتُخْبِرَنَا قَالَ إِنَّهُ قَدْ خَرَجَ رَجُلٌ ‏ ‏بِمَكَّةَ ‏ ‏حَرَّمَ عَلَيْنَا الزِّنَا وَمَنَعَ مِنْ ‏ ‏الْفِرَارِ ‏","","",""],[14307,14307,"","আমরা আমার বাবা খেলার কথা বলেছিলাম যখন আমরা টুইডো জিততে চেষ্টা করলাম। ভালো, ঈশ্বর প্রার্থনা করলেন যেন তিনি ব্যর্থ হন। কেউ না হয়, কিন্তু কেউ দৌড় দিয়ে দৌড়ে যেতে না পারে। একটা ড্রেস পরা মহিলা।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏يُبَاشِرْ ‏ ‏الرَّجُلُ الرَّجُلَ فِي الثَّوْبِ الْوَاحِدِ وَلَا ‏ ‏تُبَاشِرْ ‏ ‏الْمَرْأَةُ الْمَرْأَةَ فِي الثَّوْبِ الْوَاحِدِ ‏","","",""],[14308,14308,"","আমি আমার বাবা গেম খেলছিলাম আর আমরা আমার ছেলেকে পছন্দ করতাম। যে প্রভুর প্রভুর কাছে পাপ করেছে সে তার কাছে প্রার্থনা করেছে। আমি নিশ্চিত সে আর এটা হতে পারবে না। ভয় পেয়ে গেল যে সে ঈশ্বরের নাম বলবে আর খোদা আমার সাথে এমন করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏أَخْبَرَنِي ‏ ‏مَوْلَايَ ‏ ‏الْمُطَّلِبُ بْنُ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ ‏ ‏أَنَّ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِيدَ الْأَضْحَى فَلَمَّا انْصَرَفَ أَتَى بِكَبْشٍ فَذَبَحَهُ فَقَالَ ‏ ‏بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ اللَّهُمَّ إِنَّ هَذَا عَنِّي وَعَمَّنْ لَمْ يُضَحِّ مِنْ أُمَّتِي ‏","","",""],[14309,14309,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন, তাঁর কাছে প্রার্থনা করেছিলেন এবং তিনি আপনাকে এই দেয়াল থেকে বের করে আনতে সক্ষম হবেন । তিনি আপনাকে বলেছিলেন যে, তিনি এটা করেছেন, যিনি এটা করেছেন । এই লোকদের অপেক্ষা বরং সে আমার পরিতৃপ্তি এনে দিয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمَلِيحِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَطْلُعُ عَلَيْكُمْ مِنْ تَحْتِ هَذَا السُّورِ رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ قَالَ فَطَلَعَ عَلَيْهِمْ ‏ ‏أَبُو بَكْرٍ ‏ ‏رِضْوَانُ اللَّهِ عَلَيْهِ فَهَنَّأْنَاهُ بِمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ لَبِثَ ‏ ‏هُنَيْهَةً ‏ ‏ثُمَّ قَالَ يَطْلُعُ عَلَيْكُمْ مِنْ تَحْتِ هَذَا السُّورِ رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ قَالَ فَطَلَعَ ‏ ‏عُمَرُ ‏ ‏قَالَ فَهَنَّأْنَاهُ بِمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ثُمَّ قَالَ يَطْلُعُ عَلَيْكُمْ مِنْ تَحْتِ هَذَا السُّورِ رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ اللَّهُمَّ إِنْ شِئْتَ جَعَلْتَهُ ‏ ‏عَلِيًّا ‏ ‏ثَلَاثَ مَرَّاتٍ فَطَلَعَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[14310,14310,"","আমার ছেলের ব্যাপারে আমরা এতই ভালো ছিলাম যে আমার বাবার সাথে কথা বলেছি, ঈশ্বর বলতে হবে, আমি কার সাথে থাকতে পারি বা কি খাই। আমার বাবার ছেলে অনেক লোক যারা বাস করে তাদের মধ্যে অনেক। মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَيَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَحْيَا أَرْضًا مَيْتَةً فَلَهُ فِيهَا أَجْرٌ وَمَا أَكَلَتْ ‏ ‏الْعَافِيَةُ ‏ ‏مِنْهَا فَهُوَ لَهُ ‏ ‏صَدَقَةٌ ‏ ‏وَقَالَ ‏ ‏ابْنُ أَبِي بُكَيْرٍ ‏ ‏مَنْ أَحْيَا أَرْضًا مَيْتَةً فَهِيَ لَهُ ‏","","",""],[14311,14311,"","আমরা ভালো কিছু করার কথা বলেছিলাম আর তারা বললো, \"আমরা তার মুখে ভাল কথা বলেছি।\" আমরা ঘোড়ার ভালোর জন্য গিয়েছিলাম এবং প্রভুর শোকের জন্য বলা হয়েছে আমরা কল্পনার ব্যাপারে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَحَسَنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالُوا ثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي ‏ ‏حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏ذَبَحْنَا يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏الْخَيْلَ وَالْبِغَالَ وَالْحَمِيرَ فَنَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْبِغَالِ وَالْحَمِيرِ وَلَمْ يَنْهَنَا عَنْ الْخَيْلِ ‏","","",""],[14312,14312,"","আমরা আমার মৃত বাবা ছেলেটির ব্যাপারে জানতে চেয়েছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏الْمُزَابَنَةِ ‏ ‏وَالْمُحَاقَلَةِ ‏ ‏وَالْمُخَابَرَةِ ‏ ‏وَالثُّنْيَا ‏ ‏وَالْمُعَاوَمَةِ ‏","","",""],[14313,14313,"","আমরা সেই ভালো সময় কথা বলেছি, যখন আমি তার জন্য প্রার্থনা করলাম এবং আমি পানি ছেড়ে দেব।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏فِيمَا أَحْسِبُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ الْمَاءِ ‏","","",""],[14314,14314,"","আমরা আমার মৃত বাবার কথা বলেছিলাম আর তার স্বপ্ন কখনোই শোনা যায়নি, ডাক্তার, নকল, ধনী।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالنَّقِيرِ ‏","","",""],[14315,14315,"","তিনি বলেছিলেন যে, তিনি হয়তো শপথ করে শপথ নিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ ‏ ‏مُتَوَشِّحًا ‏ ‏بِهِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏قَدْ خَالَفَ بَيْنَ طَرَفَيْهِ ‏","","",""],[14316,14316,"","ঈশ্বর তাকে প্রার্থনা করেছিলেন এবং ঈশ্বর তাকে আত্মসমর্পণ করবেন, যখন ঈশ্বর তাকে আদেশ দিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرُ بْنُ سُلَيْمَانَ الرَّقِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏الْعُمْرَةُ أَوَاجِبَةٌ هِيَ قَالَ لَا ‏","","",""],[14317,14317,"","আমরা আমার বাবাকে উত্তম বন্ধু হওয়ার ব্যাপারে বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْقُدُّوسِ بْنُ بَكْرِ بْنِ خُنَيْسٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏جَابِرٌ ‏ ‏عَمَّا يُدْعَى لِلْمَيِّتِ فَقَالَ مَا أَبَاحَ لَنَا فِيهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا ‏ ‏أَبُو بَكْرٍ ‏ ‏وَلَا ‏ ‏عُمَرُ ‏","","",""],[14318,14318,"","আমরা আমার বাবার সাথে হাত মিলিয়েছি, দুই বছর, আমি বলতে চাচ্ছি, দুই বছর বয়স, আর আমি মরার চেয়ে মরে যাব।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حُمَيْدٍ أَبُو سُفْيَانَ يَعْنِي الْمَعْمَرِيَّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَأَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْكَافِرَ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ وَالْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ ‏","","",""],[14319,14319,"","আমরা বাবার অকালমৃত্যুর উত্তর নিয়ে কথা বলেছি, ঈশ্বর... ...তার দক্ষতার বেগুনি দ্বারা পরাজিত হয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْ رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ قَدْ خَالَفَ بَيْنَ طَرَفَيْهِ ‏","","",""],[14320,14320,"","ঈশ্বর যে - জলগুলো নির্ধারণ করেছেন, সেগুলো তিনি যে - জল পান করেছেন, সেগুলোর বিষয়ে আমরা আলোচনা করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ ثَابِتٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُؤَمَّلِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَاءُ ‏ ‏زَمْزَمَ ‏ ‏لِمَا شُرِبَ لَهُ ‏","","",""],[14321,14321,"","আমরা এত ভালো হওয়ার কথা বলেছি যে, আমাদের অবস্থা আগের চেয়ে ভালো থাকার কারনে। আমি ঈশ্বরের কাছে প্রার্থনা করছি তার জন্য এবং তিনি যখন কাজ করেছেন, তখন আমাদের বাড়িতে একজন অতিথিকে পাঠিয়ে দিয়েছেন। একজন ব্যক্তি, যে তার জীবন হারিয়েছে, সে তাকে হত্যা করতে অথবা তাকে খুঁজে পেতে এক যুবক ও নোংরা কাজ করতে দেখেছে ।","‏ ‏حَدَّثَنَا ‏ ‏مِسْكِينُ بْنُ بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَائِرًا فِي مَنْزِلِنَا فَرَأَى رَجُلًا ‏ ‏شَعِثًا ‏ ‏فَقَالَ ‏ ‏أَمَا كَانَ يَجِدُ هَذَا مَا يُسَكِّنُ بِهِ رَأْسَهُ وَرَأَى رَجُلًا عَلَيْهِ ثِيَابٌ وَسِخَةٌ فَقَالَ أَمَا كَانَ يَجِدُ هَذَا مَا يَغْسِلُ بِهِ ثِيَابَهُ ‏","","",""],[14322,14322,"","আমরা তোমার বাবার অফিসের পর কিছু কথা বলেছিলাম, সে বই আর নকল দিয়ে কিছু উপহার পেয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[14323,14323,"","আমরা একটা হাত নিয়ে কথা বলেছিলাম যখন তুমি তোমার বাবা বা আমার স্বামীর সাথে জন্ম নিয়েছ. ঈশ্বর তাঁর জন্য প্রার্থনা করেছিলেন এবং তিনি একদিন তাঁর প্রতি আমার অনুগ্রহ ঘোষণা করবেন এবং আপনার আত্মার উত্তর দেবেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏و حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏أَنْبَأَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَفَّنَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَمْزَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فِي ثَوْبٍ وَاحِدٍ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏ذَلِكَ الثَّوْبُ ‏ ‏نَمِرَةٌ ‏","","",""],[14324,14324,"","আমরা এমন এক পুত্র সম্পর্কে কথা বলেছি যে ঈশ্বরকে জিজ্ঞাসা করেছে, যেন তার মুখের উপর থেকে দূরের নদীর কাছে প্রার্থনা করা হয়।","‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مَثَلَ هَذِهِ الصَّلَوَاتِ الْخَمْسِ مَثَلُ نَهَرٍ جَارٍ عَلَى بَابِ أَحَدِكُمْ يَغْتَسِلُ فِيهِ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ فَمَا يُبْقِي ذَلِكَ مِنْ ‏ ‏الدَّنَسِ ‏","","",""],[14325,14325,"","আমরা ঈশ্বরের ইচ্ছার বিরুদ্ধে যুদ্ধ করতে পেরে খুশির সাথে এগিয়ে যাচ্ছি... ...সে প্রার্থনা করবে যে... ...তার কাছে তোমার ক্রেতা আছে একটা দেয়ালে এটা.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْيَشْكُرِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ كَانَ لَهُ شَرِيكٌ فِي ‏ ‏حَائِطٍ ‏ ‏فَلَا يَبِعْهُ حَتَّى يَعْرِضَهُ عَلَيْهِ ‏","","",""],[14326,14326,"","আমরা চলে যাওয়ার কথা বলেছি, একটা কুত্তার বাচ্চা আমাদের বলেছে আমরা ঈশ্বরের একজন ভালো প্রভু, ঈশ্বর তার কাছে প্রার্থনা করতে বলেছেন এবং লর্ড লর্ডের কাছে প্রার্থনা করতে বলেছেন। তারা তাদের কাজের আগে ঈশ্বরের সমবেদনা জানাতে যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ يَعْنِي ابْنَ عَطَاءٍ ‏ ‏أَنْبَأَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ اللَّيْثِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَسْجِدَ فَإِذَا فِيهِ قَوْمٌ يَقْرَءُونَ الْقُرْآنَ قَالَ ‏ ‏اقْرَءُوا الْقُرْآنَ وَابْتَغُوا بِهِ اللَّهَ عَزَّ وَجَلَّ مِنْ قَبْلِ أَنْ يَأْتِيَ قَوْمٌ يُقِيمُونَهُ إِقَامَةَ ‏ ‏الْقِدْحِ ‏ ‏يَتَعَجَّلُونَهُ وَلَا يَتَأَجَّلُونَهُ ‏","","",""],[14327,14327,"","ঈশ্বর আদেশ দিয়েছেন যেন তিনি বধিরদের একের পর এক না পরতে এবং আপনার এক আত্মার মধ্যে কাউকে না খেতে পারেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَرْتَدُوا ‏ ‏الصَّمَّاءَ ‏ ‏فِي ثَوْبٍ وَاحِدٍ وَلَا يَأْكُلْ أَحَدُكُمْ بِشِمَالِهِ وَلَا يَمْشِ فِي نَعْلٍ وَاحِدَةٍ وَلَا ‏ ‏يَحْتَبِ ‏ ‏فِي ثَوْبٍ وَاحِدٍ ‏","","",""],[14328,14328,"","আমার বাবা একজন ভালো ছেলে হয়ে থাকলে আমরা প্রায়ই কথা বলতাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏احْتَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ مِنْ أَلَمٍ كَانَ بِظَهْرِهِ ‏ ‏أَوْ بِوَرِكِهِ شَكَّ ‏ ‏هِشَامٌ ‏","","",""],[14329,14329,"","আমরা প্রভুর ইচ্ছা নিয়ে কথা বলেছি, যতক্ষণ না সে শেষ পর্যন্ত ভিতরে বিক্রি করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ النَّخْلِ حَتَّى يُطْعَمَ ‏","","",""],[14330,14330,"","আমরা একজন দাসের কথা বলেছি যার বাবার প্রশংসা আমাকে বাবার দয়া সহ্য করতে সাহায্য করেছে। তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন, যেন তিনি তাঁকে চিনতে পারেন এবং তিনি এই কাজে জয় লাভ করেন। যোদ্ধা আর লেবেলগুলো ভুলে যাওয়া যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التَّسْبِيحُ فِي الصَّلَاةِ لِلرِّجَالِ وَالتَّصْفِيقُ لِلنِّسَاءِ ‏","","",""],[14331,14331,"","আমরা আমার সবচেয়ে ভালো ছেলের কথা বলেছি, কিন্তু তিনি আমার সর্বোচ্চ উত্তর ভুলে গেছেন। ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তিনি প্রার্থনা করলেন, তিনি ঈশ্বরের কাছে প্রার্থনা করলেন, ঈশ্বর তাকে রক্ষা করেছেন। সে হঠাৎ একটা উভয় সমস্যার মধ্যে একজন মানুষকে দাঁড় করিয়ে দিল যে ঈশ্বরের কাছে অনুরোধ করার মত অবস্থায় আছে। আমি তাদের বলতে চাই ঈশ্বর মুক্তি দিয়েছেন এবং তারা থাকবে। ঈশ্বর তাঁর কাছে প্রার্থনা করবেন এবং তিনি পানি পান তীর্থশালায় মাথা নত করেন তিনি বললেন তিনি কাদার আনন্দ কামনা করেন. ঈশ্বরের দিকে যাচ্ছেন এবং আমার দৃষ্টি দেখে বললেন যে, ঈশ্বর আমার দৃষ্টি দেখতে পাবেন ঈশ্বর সেটা উদ্ধার করতে পারেন আর আলো না তোলা পর্যন্ত তিনি হাত তুলে নেবেন না।","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ ‏ ‏حَدَّثَنِي ‏ ‏الْأَسْوَدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ الْعَنَزِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَافَرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَحَضَرَتْ الصَّلَاةُ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ فِي الْقَوْمِ مِنْ طَهُورٍ قَالَ فَجَاءَ رَجُلٌ بِفَضْلَةٍ فِي ‏ ‏إِدَاوَةٍ ‏ ‏قَالَ فَصَبَّهُ فِي ‏ ‏قَدَحٍ ‏ ‏قَالَ فَتَوَضَّأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ إِنَّ الْقَوْمَ أَتَوْا بَقِيَّةَ الطَّهُورِ فَقَالُوا تَمَسَّحُوا تَمَسَّحُوا قَالَ فَسَمِعَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ عَلَى رِسْلِكُمْ قَالَ ‏ ‏فَضَرَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ فِي ‏ ‏الْقَدَحِ ‏ ‏فِي جَوْفِ الْمَاءِ قَالَ ثُمَّ قَالَ ‏ ‏أَسْبِغُوا ‏ ‏الْوُضُوءَ الطَّهُورَ قَالَ فَقَالَ ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏وَالَّذِي أَذْهَبَ بَصَرِي ‏ ‏قَالَ وَكَانَ قَدْ ذَهَبَ بَصَرُهُ ‏ ‏لَقَدْ رَأَيْتُ الْمَاءَ يَخْرُجُ مِنْ بَيْنِ أَصَابِعِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَرْفَعْ يَدَهُ حَتَّى تَوَضَّئُوا أَجْمَعُونَ ‏ ‏قَالَ ‏ ‏الْأَسْوَدُ ‏ ‏حَسِبْتُهُ قَالَ كُنَّا مِائَتَيْنِ أَوْ زِيَادَةً ‏","","",""],[14332,14332,"","আমি প্রভু থেকে আমার ভালো কিছুর কথা বলেছি যা আমাকে ঈশ্বরের অনুগ্রহে বলতে হয়েছে। ঈশ্বর আশ্বস্ত করেছেন, Jabberকে আত্মসমর্পণ করতে হবে। আমি বলেছিলাম যে আমি বলেছিলাম, আমি এটা প্রমাণ করতে পারি নি যে আমি তেমন কিছু করিনি। গর্বিত বলে যে আমি করিনি। আর সে আমাকে বলল যে সে তার সাথে বিবাহিত, আর সে বলেছে সে আমার বাবাকে তোমার সাথে খুন করেছে। ঈশ্বর তাঁর কাছে প্রার্থনা করেছিলেন এবং তিনি জানতেন যে, তিনি কী দেখেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ ‏ ‏حَدَّثَنِي ‏ ‏الْأَسْوَدُ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ الْعَنَزِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏جَابِرُ ‏ ‏أَلَكَ امْرَأَةٌ قَالَ قُلْتُ نَعَمْ قَالَ ‏ ‏أَثَيِّبًا ‏ ‏نَكَحْتَ أَمْ ‏ ‏بِكْرًا ‏ ‏قَالَ قُلْتُ لَهُ تَزَوَّجْتُهَا وَهِيَ ‏ ‏ثَيِّبٌ ‏ ‏قَالَ فَقَالَ لِي فَهَلَّا تَزَوَّجْتَهَا ‏ ‏جُوَيْرِيَةً ‏ ‏قَالَ قُلْتُ لَهُ قُتِلَ أَبِي مَعَكَ يَوْمَ كَذَا وَكَذَا وَتَرَكَ ‏ ‏جَوَارِيَ ‏ ‏فَكَرِهْتُ أَنْ أَضُمَّ إِلَيْهِنَّ ‏ ‏جَارِيَةً ‏ ‏كَإِحْدَاهُنَّ فَتَزَوَّجْتُ ‏ ‏ثَيِّبًا ‏ ‏تَقْصَعُ ‏ ‏قَمْلَةَ إِحْدَاهُنَّ وَتَخِيطُ ‏ ‏دِرْعَ ‏ ‏إِحْدَاهُنَّ إِذَا تَخَرَّقَ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنَّكَ نِعْمَ مَا رَأَيْتَ ‏","","",""],[14333,14333,"","আমরা একজন যাজকের কাছে কথা বলেছি... ...ঈশ্বরের উত্তরে আমার আনন্দব্যঞ্জক জেদের জন্য, ঈশ্বরের কাছে প্রার্থনা করতে হবে, আর সে আমাদের একজন পলাতকের কাছ থেকে চলে আসবে খুন হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ الْعَنَزِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى أَحَدَنَا إِذَا جَاءَ مِنْ سَفَرٍ أَنْ يَطْرُقَ أَهْلَهُ قَالَ فَطَرَقْنَاهُنَّ بَعْدُ ‏","","",""],[14334,14334,"","আমরা সেই সময়ের কথা বলেছি, যখন আমরা কাপুরুষের জন্য একজন যাজককে পেয়েছি, তার জন্য প্রার্থনা করেছে এবং সে আত্মসমর্পণ করেছে যে সে জিতবে বা যুদ্ধ করতে চায়, তাদের কোন অর্থ নেই, দশ এরও বেশি না, সে বলল আমি দুই-তিন গুণ করে দেবো আর কখনো তাদের কাউকে শাস্তি দেবো না।","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ الْعَنَزِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏حَدَّثَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ أَرَادَ الْغَزْوَ فَقَالَ يَا مَعْشَرَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَالْأَنْصَارِ ‏ ‏إِنَّ مِنْ إِخْوَانِكُمْ قَوْمًا لَيْسَ لَهُمْ مَالٌ وَلَا عَشِيرَةٌ فَلْيَضُمَّ أَحَدُكُمْ إِلَيْهِ الرَّجُلَيْنِ أَوْ الثَّلَاثَةَ فَمَا لِأَحَدِنَا مِنْ ظَهْرِ جَمَلِهِ إِلَّا عُقْبَةٌ كَعُقْبَةِ أَحَدِهِمْ قَالَ فَضَمَمْتُ اثْنَيْنِ أَوْ ثَلَاثَةً إِلَيَّ وَمَا لِي إِلَّا عُقْبَةٌ كَعُقْبَةِ أَحَدِهِمْ مِنْ جَمَلِي ‏","","",""],[14335,14335,"","আমরা প্রভু এর কথা বলেছি কিন্তু পবিত্র পিতার কথা বলছি, যিনি তার জীবন হারিয়েছেন, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করবেন এবং আপনি যা বলেন, আমাকে হত্যা করতে ব্যর্থ হবেন। আমার সৌন্দর্য হারিয়ে গেল। আমি বলেছিলাম, ঈশ্বর আমি যা পেয়েছি, তা আমি তাকে পেয়েছি, যাতে আপনি তাকে নিয়ে যান যাতে তিনি তাকে যেতে পারেন সেই ব্যক্তি তাকে টাকা দিয়ে বলেছিলেন যে, লোকেরা যখন চলে যাবে, তখন হয়তো আমার বাবা ও মা, ঈশ্বর আমাকে মেরে ফেলবে । আমি বলেছিলাম, “আমার মা শপথ করে ঈশ্বরের কাছে শপথ করে শপথ নিতে রাজি হননি, ঈশ্বর অবিকার্য করেছেন । ঈশ্বর, ঈশ্বর, আমাকে প্রভুর নিকট যেতে হবে। হয় আমি তাকে ছেড়ে দেব অথবা তাকে তাড়াতাড়ি করতে দেব। \"আমি জানি সে কিভাবে বলেছিল\" সময় থেকে একজন সুস্থ মানুষ বলেছে, বাবা, ঈশ্বর কখনো তাকে ভালো কিছু বলেননি। ঈশ্বর তাকে আত্মসমর্পণ করতে বলেছেন। আমি হয়ত তাকে বলেছি, সে আমাকে হতাশ করেছে। আমি জানি, আমি জানি, সে কি ভাবে এটা একটা প্রশ্ন করে, কিন্তু আমি জানি, আমি কি করে যাচ্ছি। এবং আমি জানি, আমি কি ভাবে এটা করতে পারি, ঈশ্বর আসলে, আমি জানি না, আমি কি করে, ঈশ্বর তাকে কি বলেছিলাম। এবং আমি যদি বলি, আমি তোমার কাছে ক্ষমা করে নেই। এবং আমার মনের কথা বলি, আমি যদি আমার বাবা আমাকে ছেড়ে দেয়, আমি সত্যিই অনেক কিছু বলে ফেলি, আমি তাকে ছেড়ে দিয়েছি, তোমার লোকেরা আমাকে বলে আমি কি করছি, কিন্তু তুমি যা বলেছ তা শুধু এটাই যে আমরা তাকে দিয়ে যাচ্ছি। আমি তাকে উপরে তুলেছি না যতক্ষণ না পর্যন্ত না পর্যন্ত আমি শহরে যাই। আমি আমার উপর দোষ চাপিয়ে দেই। আমি তাকে টেনে নিয়ে গিয়ে তার পরিকল্পনা নিয়ে তাকে তার কাছে গিয়ে ঈশ্বরকে পাঠান এবং ঈশ্বর তাকে উদ্ধার করেন । সে তার সাথে কথা বলছে যে আমি তার সাথে কথা বলেছি, আমি বলেছি, ঈশ্বর তোমার ঋণ ক্ষমা করুন, সে ভুল বলেছে। আত্মসমর্পণ কর এবং এমন এক সম্পদ যে ঐ লোকদের সাথে কথা বলে যে সে হয়ত আমার দ্বারা পরাজিত হয়েছে। আমি আমার বাসায় গেলাম এবং আমি মনে করতাম যে জাবের কোথায় যাবে। ঈশ্বর আপনাকে তার কাছে অনুরোধ করেছেন আর তিনি তাকে আদেশ দিয়েছেন, তিনি তাকে হত্যা করেছেন বলে। তোমার চাচা, আমরা তাকে চলে যেতে বলেছিলাম... ...আমাকে বলতে যে আমি আমার সাথে সেরাটা করেছি... ...আর সে আমাকে একটা কনডম দিতে হবে আর তার পুরো ক্লাস আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏فَقَدْتُ جَمَلِي لَيْلَةً فَمَرَرْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَشُدُّ ‏ ‏لِعَائِشَةَ ‏ ‏قَالَ فَقَالَ لِي مَا لَكَ يَا ‏ ‏جَابِرُ ‏ ‏قَالَ قُلْتُ فَقَدْتُ جَمَلِي ‏ ‏أَوْ ذَهَبَ جَمَلِي ‏ ‏فِي لَيْلَةٍ ظَلْمَاءَ قَالَ فَقَالَ لِي هَذَا جَمَلُكَ اذْهَبْ فَخُذْهُ قَالَ فَذَهَبْتُ نَحْوًا مِمَّا قَالَ لِي فَلَمْ أَجِدْهُ قَالَ فَرَجَعْتُ إِلَيْهِ فَقُلْتُ يَا نَبِيَّ اللَّهِ مَا وَجَدْتُهُ قَالَ فَقَالَ لِي هَذَا جَمَلُكَ اذْهَبْ فَخُذْهُ قَالَ فَذَهَبْتُ نَحْوًا مِمَّا قَالَ لِي فَلَمْ أَجِدْهُ قَالَ فَرَجَعْتُ إِلَيْهِ فَقُلْتُ بِأَبِي وَأُمِّي يَا نَبِيَّ اللَّهِ لَا وَاللَّهِ مَا وَجَدْتُهُ قَالَ فَقَالَ لِي عَلَى رِسْلِكَ حَتَّى إِذَا فَرَغَ أَخَذَ بِيَدِي فَانْطَلَقَ بِي حَتَّى أَتَيْنَا الْجَمَلَ فَدَفَعَهُ إِلَيَّ قَالَ هَذَا جَمَلُكَ قَالَ وَقَدْ سَارَ النَّاسُ قَالَ فَبَيْنَمَا أَنَا أَسِيرُ عَلَى جَمَلِي فِي عُقْبَتِي قَالَ وَكَانَ جَمَلًا فِيهِ ‏ ‏قِطَافٌ ‏ ‏قَالَ قُلْتُ يَا لَهْفَ أُمِّي أَنْ يَكُونَ لِي إِلَّا جَمَلٌ ‏ ‏قَطُوفٌ ‏ ‏قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدِي يَسِيرُ قَالَ فَسَمِعَ مَا قُلْتُ قَالَ فَلَحِقَ بِي فَقَالَ مَا قُلْتَ يَا ‏ ‏جَابِرُ ‏ ‏قَبْلُ قَالَ فَنَسِيتُ مَا قُلْتُ قَالَ قُلْتُ مَا قُلْتُ شَيْئًا يَا نَبِيَّ اللَّهِ قَالَ فَذَكَرْتُ مَا قُلْتُ قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ يَا لَهْفَاهُ أَنْ يَكُونَ لِي إِلَّا جَمَلٌ ‏ ‏قَطُوفٌ ‏ ‏قَالَ فَضَرَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَجُزَ ‏ ‏الْجَمَلِ بِسَوْطٍ ‏ ‏أَوْ بِسَوْطِي ‏ ‏قَالَ فَانْطَلَقَ أَوْضَعَ ‏ ‏أَوْ أَسْرَعَ ‏ ‏جَمَلٍ رَكِبْتُهُ قَطُّ وَهُوَ يُنَازِعُنِي ‏ ‏خِطَامَهُ ‏ ‏قَالَ فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْتَ بَائِعِي جَمَلَكَ هَذَا قَالَ قُلْتُ نَعَمْ قَالَ بِكَمْ قَالَ قُلْتُ ‏ ‏بِوُقِيَّةٍ ‏ ‏قَالَ قَالَ لِي ‏ ‏بَخٍ ‏ ‏بَخٍ ‏ ‏كَمْ فِي ‏ ‏أُوقِيَّةٍ ‏ ‏مِنْ ‏ ‏نَاضِحٍ ‏ ‏وَنَاضِحٍ ‏ ‏قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ مَا ‏ ‏بِالْمَدِينَةِ ‏ ‏نَاضِحٌ ‏ ‏أُحِبُّ أَنَّهُ لَنَا مَكَانَهُ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ أَخَذْتُهُ ‏ ‏بِوُقِيَّةٍ ‏ ‏قَالَ فَنَزَلْتُ عَنْ ‏ ‏الرَّحْلِ ‏ ‏إِلَى الْأَرْضِ قَالَ مَا شَأْنُكَ قَالَ قُلْتُ جَمَلُكَ قَالَ قَالَ لِي ارْكَبْ جَمَلَكَ قَالَ قُلْتُ مَا هُوَ بِجَمَلِي وَلَكِنَّهُ جَمَلُكَ قَالَ كُنَّا نُرَاجِعُهُ مَرَّتَيْنِ فِي الْأَمْرِ إِذَا أَمَرَنَا بِهِ فَإِذَا أَمَرَنَا الثَّالِثَةَ ‏ ‏لَمْ نُرَاجِعْهُ قَالَ فَرَكِبْتُ الْجَمَلَ حَتَّى أَتَيْتُ عَمَّتِي ‏ ‏بِالْمَدِينَةِ ‏ ‏قَالَ وَقُلْتُ لَهَا أَلَمْ تَرَيْ أَنِّي بِعْتُ ‏ ‏نَاضِحَنَا ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأُوقِيَّةٍ ‏ ‏قَالَ فَمَا رَأَيْتُهَا أَعْجَبَهَا ذَلِكَ قَالَ وَكَانَ ‏ ‏نَاضِحًا ‏ ‏فَارِهًا قَالَ ثُمَّ أَخَذْتُ شَيْئًا مِنْ ‏ ‏خَبَطٍ ‏ ‏أَوْجَرْتُهُ ‏ ‏إِيَّاهُ ثُمَّ أَخَذْتُ ‏ ‏بِخِطَامِهِ ‏ ‏فَقُدْتُهُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُقَاوِمًا رَجُلًا يُكَلِّمُهُ قَالَ قُلْتُ دُونَكَ يَا نَبِيَّ اللَّهِ جَمَلَكَ قَالَ فَأَخَذَ ‏ ‏بِخِطَامِهِ ‏ ‏ثُمَّ نَادَى ‏ ‏بِلَالًا ‏ ‏فَقَالَ زِنْ ‏ ‏لِجَابِرٍ ‏ ‏أُوقِيَّةً ‏ ‏وَأَوْفِهِ فَانْطَلَقْتُ مَعَ ‏ ‏بِلَالٍ ‏ ‏فَوَزَنَ لِي ‏ ‏أُوقِيَّةً ‏ ‏وَأَوْفَى مِنْ الْوَزْنِ قَالَ فَرَجَعْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ قَائِمٌ يُحَدِّثُ ذَلِكَ الرَّجُلَ قَالَ قُلْتُ لَهُ قَدْ وَزَنَ لِي ‏ ‏أُوقِيَّةً ‏ ‏وَأَوْفَانِي قَالَ فَبَيْنَمَا هُوَ كَذَلِكَ إِذْ ذَهَبْتُ إِلَى بَيْتِي وَلَا أَشْعُرُ قَالَ فَنَادَى أَيْنَ ‏ ‏جَابِرٌ ‏ ‏قَالُوا ذَهَبَ إِلَى أَهْلِهِ قَالَ أَدْرِكْ ائْتِنِي بِهِ قَالَ فَأَتَانِي رَسُولُهُ ‏ ‏يَسْعَى قَالَ يَا ‏ ‏جَابِرُ ‏ ‏يَدْعُوكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَتَيْتُهُ فَقَالَ فَخُذْ جَمَلَكَ قُلْتُ مَا هُوَ جَمَلِي وَإِنَّمَا هُوَ جَمَلُكَ يَا رَسُولَ اللَّهِ قَالَ خُذْ جَمَلَكَ قُلْتُ مَا هُوَ جَمَلِي إِنَّمَا هُوَ جَمَلُكَ يَا رَسُولَ اللَّهِ قَالَ خُذْ جَمَلَكَ قَالَ فَأَخَذْتُهُ قَالَ فَقَالَ ‏ ‏لَعَمْرِي مَا نَفَعْنَاكَ لِنُنْزِلَكَ عَنْهُ قَالَ فَجِئْتُ إِلَى عَمَّتِي ‏ ‏بِالنَّاضِحِ ‏ ‏مَعِي ‏ ‏وَبِالْوَقِيَّةِ ‏ ‏قَالَ فَقُلْتُ لَهَا مَا تَرَيْنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْطَانِي ‏ ‏أُوقِيَّةً ‏ ‏وَرَدَّ عَلَيَّ جَمَلِي ‏","","",""],[14336,14336,"","আমরা আমার বাবার কথা বলেছিলাম একটি ভালো ছেলে খুঁজে পাওয়ার চেষ্টা করতে। ঈশ্বর হয়তো আমার অতিথি হতে পারেন, ঈশ্বরের দোহাই জিততে চেষ্টা করছেন। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তিনি আমাদের সাথে আমার শেষ গৌরব সমর্পণ করবেন। লর্ড লর্ডের দয়া, এক শয়তান সূর্যের আরেক ধাপে চলে গেছে, ঈশ্বরের কাছে প্রার্থনা করছে, যেন সে একজন মানুষকে আত্মসমর্পণ করে এবং হঠাৎ করে মনে পড়ে যায়। ( গীতসংহিতা ৩৪: ৮) ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি সবসময় বলেছিলেন যে, যখন ঈশ্বর ঈশ্বরের কাছে প্রার্থনা করেছিলেন, তখন তিনি ভাল কিছু লাভ করেছিলেন । আমি আপনাকে খেতে শুনেছি, স্যার। তার শেষ কথা বলে চলে গিয়ে প্রার্থনা করো। মহিলাটা বলল, সে নাকি চলে গেছে। সে হয়তো জানতে পেরেছে যে সে তার ক্ষমতার সেরা। সে পড়ে আছে। ব্রেসলেটটা সে ভিতরে আছে আর সে তার বল কেটে ফেলতে যাচ্ছে। সে এটা রেখে যাচ্ছে আর সে এটা উপরে আসছে আর সে তার বলটা নিয়ে আসবে না। সে এটা হতে পারে, সে ভেঙ্গে ফেলা হয়েছে এবং সে শেষ হয়ে গেছে। তিনি জানতেন যে, তার মনে থাকবে যে, আমার বিজয় বাতাসের ভয়াবহতার হাত থেকে মুক্ত হবে । আমি যখন ঘরে ছিলাম, তখন আমি বলতে পেরেছিলাম যে, আমি হয়তো একটা দেয়ালে ছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏صَدَقَةُ بْنُ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَقِيلِ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏فِيمَا يَذْكُرُ مِنْ اجْتِهَادِ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْعِبَادَةِ قَالَ خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفِي مَوْضِعٍ آخَرَ خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةٍ مِنْ ‏ ‏نَجْدٍ ‏ ‏فَأَصَابَ امْرَأَةَ رَجُلٍ مِنْ الْمُشْرِكِينَ ‏ ‏إِلَى ‏ ‏نَجْدٍ ‏ ‏فَغَشِينَا دَارًا مِنْ دُورِ الْمُشْرِكِينَ قَالَ فَأَصَبْنَا امْرَأَةَ رَجُلٍ مِنْهُمْ قَالَ ثُمَّ انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَاجِعًا وَجَاءَ صَاحِبُهَا وَكَانَ غَائِبًا فَذُكِرَ لَهُ مُصَابُهَا فَحَلَفَ لَا يَرْجِعُ حَتَّى ‏ ‏يُهْرِيقَ ‏ ‏فِي ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَمًا قَالَ فَلَمَّا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِبَعْضِ الطَّرِيقِ نَزَلَ فِي ‏ ‏شِعْبٍ ‏ ‏مِنْ ‏ ‏الشِّعَابِ ‏ ‏وَقَالَ ‏ ‏مَنْ رَجُلَانِ ‏ ‏يَكْلَآَنَا ‏ ‏فِي لَيْلَتِنَا هَذِهِ مِنْ عَدُوِّنَا قَالَ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَرَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏نَحْنُ ‏ ‏نَكْلَؤُكَ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ فَخَرَجَا إِلَى ‏ ‏فَمِ ‏ ‏الشِّعْبِ ‏ ‏دُونَ الْعَسْكَرِ ثُمَّ قَالَ الْأَنْصَارِيُّ ‏ ‏لِلْمُهَاجِرِيِّ ‏ ‏أَتَكْفِينِي ‏ ‏أَوَّلَ اللَّيْلِ ‏ ‏وَأَكْفِيكَ ‏ ‏آخِرَهُ أَمْ ‏ ‏تَكْفِينِي ‏ ‏آخِرَهُ ‏ ‏وَأَكْفِيكَ ‏ ‏أَوَّلَهُ قَالَ فَقَالَ ‏ ‏الْمُهَاجِرِيُّ بَلْ ‏ ‏اكْفِنِي ‏ ‏أَوَّلَهُ ‏ ‏وَأَكْفِيكَ ‏ ‏آخِرَهُ فَنَامَ ‏ ‏الْمُهَاجِرِيُّ وَقَامَ الْأَنْصَارِيُّ ‏ ‏يُصَلِّي قَالَ فَافْتَتَحَ سُورَةً مِنْ الْقُرْآنِ فَبَيْنَا هُوَ فِيهَا يَقْرَأُ إِذْ جَاءَ زَوْجُ الْمَرْأَةِ قَالَ فَلَمَّا رَأَى الرَّجُلَ قَائِمًا عَرَفَ أَنَّهُ ‏ ‏رَبِيئَةُ ‏ ‏الْقَوْمِ فَيَنْتَزِعُ لَهُ بِسَهْمٍ فَيَضَعُهُ فِيهِ قَالَ فَيَنْزِعُهُ فَيَضَعُهُ وَهُوَ قَائِمٌ يَقْرَأُ فِي السُّورَةِ الَّتِي هُوَ فِيهَا وَلَمْ يَتَحَرَّكْ كَرَاهِيَةَ أَنْ يَقْطَعَهَا قَالَ ثُمَّ عَادَ لَهُ زَوْجُ الْمَرْأَةِ بِسَهْمٍ آخَرَ فَوَضَعَهُ فِيهِ فَانْتَزَعَهُ فَوَضَعَهُ وَهُوَ قَائِمٌ ‏ ‏يُصَلِّي وَلَمْ يَتَحَرَّكْ كَرَاهِيَةَ أَنْ يَقْطَعَهَا قَالَ ثُمَّ عَادَ لَهُ زَوْجُ الْمَرْأَةِ الثَّالِثَةَ بِسَهْمٍ فَوَضَعَهُ فِيهِ فَانْتَزَعَهُ فَوَضَعَهُ ثُمَّ رَكَعَ فَسَجَدَ ثُمَّ قَالَ لِصَاحِبِهِ اقْعُدْ فَقَدْ أُوتِيتُ قَالَ فَجَلَسَ ‏ ‏الْمُهَاجِرِيُّ فَلَمَّا رَآهُمَا صَاحِبُ الْمَرْأَةِ هَرَبَ وَعَرَفَ أَنَّهُ قَدْ ‏ ‏نُذِرَ ‏ ‏بِهِ قَالَ وَإِذَا الْأَنْصَارِيُّ يَمُوجُ دَمًا مِنْ رَمْيَاتِ صَاحِبِ الْمَرْأَةِ قَالَ فَقَالَ لَهُ أَخُوهُ ‏ ‏الْمُهَاجِرِيُّ يَغْفِرُ اللَّهُ لَكَ أَلَا كُنْتَ ‏ ‏آذَنْتَنِي ‏ ‏أَوَّلَ مَا رَمَاكَ قَالَ فَقَالَ كُنْتُ فِي سُورَةٍ مِنْ الْقُرْآنِ قَدْ افْتَتَحْتُهَا أُصَلِّي بِهَا فَكَرِهْتُ أَنْ أَقْطَعَهَا وَايْمُ اللَّهِ لَوْلَا أَنْ أُضَيِّعَ ‏ ‏ثَغْرًا ‏ ‏أَمَرَنِي بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحِفْظِهِ لَقَطَعَ نَفْسِي قَبْلَ أَنْ أَقْطَعَهَا ‏","","",""],[14337,14337,"","ঈশ্বরের দোহাই, আমি প্রার্থনা করি ঈশ্বর যেন শান্তি বজায় রাখেন এবং তাঁর সকল জীবন থেকে আপনি আদেশ দেবেন.","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَاسِعِ بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِذَلِكَ مِنْ كُلِّ ‏ ‏جَادٍّ ‏ ‏عَشَرَةُ ‏ ‏أَوْسُقٍ ‏ ‏مِنْ التَّمْرِ ‏","","",""],[14338,14338,"","আমরা রাজার পর্দা রক্ষা করার চেষ্টা করেছি, যা আমরা হাত দিয়ে রক্ষা পাওয়ার স্বপ্ন নিয়ে করেছি। তার চাচা ছিল এক কাপুরুষের ছেলে, যে কিনা হয়তো ঈশ্বরের দ্বারা উদ্ধার করা হয়েছে। ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَاسِعِ بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَمْرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ كُلِّ ‏ ‏جَادٍّ ‏ ‏بِعَشَرَةِ ‏ ‏أَوْسُقٍ ‏ ‏مِنْ تَمْرٍ ‏ ‏بِقِنْوٍ ‏ ‏يُعَلَّقُ فِي الْمَسْجِدِ لِلْمَسَاكِينِ ‏","","",""],[14339,14339,"","ঈশ্বরের দোহাই, আমার ইগোর কথা শুনেছি, আমি ঈশ্বরের কাছে প্রার্থনা করেছি আর প্রার্থনা করতে শুনেছি, আর তার কাছে প্রার্থনা করতে বলেছি। তৃতীয় এবং পরেরটা.","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَاسِعِ بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَذِنَ لِأَصْحَابِ ‏ ‏الْعَرَايَا ‏ ‏أَنْ يَبِيعُوهَا ‏ ‏بِخَرْصِهَا ‏ ‏يَقُولُ ‏ ‏الْوَسْقَ ‏ ‏وَالْوَسْقَيْنِ ‏ ‏وَالثَّلَاثَةَ وَالْأَرْبَعَةَ ‏","","",""],[14340,14340,"","আমি যা করতে চাই, তা না হলে ঈশ্বরের সঙ্গে আপনার দেখা করার ইচ্ছা থাকলে, তা শোনার জন্য আপনাদের কারও কারও সঙ্গে যোগাযোগ করার পরিকল্পনা করা উচিত,","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏دَاوُدُ بْنُ الْحُصَيْنِ ‏ ‏مَوْلَى ‏ ‏عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏وَاقِدِ بْنِ عَمْرِو بْنِ سَعْدِ بْنِ مُعَاذٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا خَطَبَ أَحَدُكُمْ الْمَرْأَةَ فَقَدِرَ أَنْ يَرَى مِنْهَا بَعْضَ مَا يَدْعُوهُ إِلَيْهَا فَلْيَفْعَلْ ‏","","",""],[14341,14341,"","আমরা কিছু বাবা-মাদের প্রতি প্রেম নিয়ে কথা বলেছি যারা হয়ত বলেছে যে ঈশ্বর তার জন্য প্রার্থনা করেছেন আর সংগ্রাম সম্পর্কে ভয় পেয়ে তিনি নিজেকে আত্মসমর্পণ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏بَعْضِ أَهْلِهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏طَلْقِ بْنِ حَبِيبٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّقُوا فَوْرَةَ الْعِشَاءِ كَأَنَّهُ لِمَا يُخَافُ مِنْ ‏ ‏الِاحْتِضَارِ ‏","","",""],[14342,14342,"","আমরা আমার ভাইয়ের ছেলের কথা বলেছিলাম, তার চাচার কাছে সাক্ষ্য দিয়ে, সে হয়তো আমাকে বলেছিল, ঈশ্বর তাকে বলেছেন যে তিনি তার কাছে প্রার্থনা করেছেন যে তিনি তাকে আত্মসমর্পণ করেছেন। সে হয়তো তার সকাল থেকে চলে গেছে, যে কিনা আমি কখনো ঈশ্বর এবং ঈশ্বরের পালক থেকে স্বাক্ষর করিনি।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَقَدْ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏أخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى أَنَّهُ ‏ ‏مَنْ أَعْمَرَ رَجُلًا عُمْرَى لَهُ وَلِعَقِبِهِ فَإِنَّهَا لِلَّذِي يُعْمَرُهَا قَدْ بَتَّهَا مِنْ صَاحِبِهَا الَّذِي أَعْمَرَهَا مَا وَقَعَ مِنْ مَوَارِيثِ اللَّهِ وَحَقِّهِ ‏","","",""],[14343,14343,"","আমি আমার বাবার সাথে কথা বলেছি যে কাপুরুষের সাথে আমার দেখা হওয়া উচিৎ। আমার জয় বলেছিল লর্ডের প্রার্থনা তার কাছে আর আত্মসমর্পণের জন্য ভুলে যাওয়া উচিত আমরা পানি নষ্ট করতে জন্মগ্রহণ করি। এরপর সে বলেছিল, এক বছর আগে তার মৃত্যুর আগে তাকে দেখেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏أَبَانُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدِ بْنِ جَبْرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏نَهَانَا عَنْ أَنْ نَسْتَدْبِرَ الْقِبْلَةَ أَوْ نَسْتَقْبِلَهَا بِفُرُوجِنَا إِذَا ‏ ‏أَهْرَقْنَا ‏ ‏الْمَاءَ قَالَ ثُمَّ رَأَيْتُهُ قَبْلَ مَوْتِهِ بِعَامٍ يَبُولُ مُسْتَقْبِلَ الْقِبْلَةِ ‏","","",""],[14344,14344,"","আমরা বাবার ছেলের কথা বলেছিলাম আমার ঘোড়ায় আমাকে জিততে চাইলে, আমার ছেলের দয়া যেন ঈশ্বরের প্রভু আছে, সে শুধু একটা ছেলের সাথে আমার ছেলের মত হয়ে যাবে। শিক্ষক হয়তো বলতে পারতেন যে সে ঈশ্বরের অনুগ্রহ কামনা করত, তার ল্যাডারে যেতে হবে আর সে আমাদের দীর্ঘ সময় সাঁতার কাটতে দিবে আর তারপর সে আমাদের ঘুষি মারতে পারবে। এরপর তুমি বড় হয়ে বলতে শুরু করলে যে ঈশ্বর যে জয়ী হয়েছেন তাতে তোমার ভুল হবে এবং যুক্তি করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُعَاذُ بْنُ رِفَاعَةَ الْأَنْصَارِيُّ ثُمَّ الزُّرَقِيُّ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَمْرِو بْنِ الْجَمُوحِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا إِلَى ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏حِينَ تُوُفِّيَ قَالَ فَلَمَّا صَلَّى عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَوُضِعَ فِي قَبْرِهِ وَسُوِّيَ عَلَيْهِ ‏ ‏سَبَّحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَبَّحْنَا طَوِيلًا ثُمَّ كَبَّرَ فَكَبَّرْنَا فَقِيلَ يَا رَسُولَ اللَّهِ لِمَ سَبَّحْتَ ثُمَّ كَبَّرْتَ قَالَ لَقَدْ تَضَايَقَ عَلَى هَذَا الْعَبْدِ الصَّالِحِ قَبْرُهُ حَتَّى فَرَّجَهُ اللَّهُ عَزَّ وَجَلَّ عَنْهُ ‏","","",""],[14345,14345,"","আমরা একটা ছেলের কথা বলেছি যে আমার প্রিয় বাবাকে ঈশ্বরের জন্য পরিচিত, সে এটা করার চেয়ে বরং আরো বেশি কিছু করতে বলেছিল যখন মানুষ আর যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اسْتَكْثِرُوا مِنْ النِّعَالِ فَإِنَّ الرَّجُلَ لَا يَزَالُ رَاكِبًا مَا انْتَعَلَ ‏","","",""],[14346,14346,"","আমরা একটা ছেলের সাথে বড় হওয়ার চেষ্টা করেছি, যার আছে সন্তান। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং গ্রীষ্মের এক মরুভূমি থেকে বাঁচার জন্য প্রার্থনা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ جَابِرٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْفَارُّ مِنْ الطَّاعُونِ كَالْفَارِّ مِنْ الزَّحْفِ وَالصَّابِرُ فِيهِ لَهُ أَجْرُ شَهِيدٍ ‏","","",""],[14347,14347,"","আমরা চেষ্টা করেছি একটা ছোট ছেলেকে মারার জন্য, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং যুদ্ধের জন্য আত্মসমর্পণ করবেন এবং মূল্যবান প্রেম এবং এই উপহারটি ফিরিয়ে আনবে।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْمُفَضَّلُ بْنُ فَضَالَةَ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَأَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُخَابَرَةِ ‏ ‏وَالْمُزَابَنَةِ ‏ ‏وَالْمُحَاقَلَةِ ‏ ‏وَبَيْعِ الثَّمَرِ حَتَّى ‏ ‏يُطْعَمَ ‏ ‏إِلَّا ‏ ‏الْعَرَايَا ‏","","",""],[14348,14348,"","আমরা একটা সুখী হাত লিখতে চেষ্টা করেছি, অমর হয়ে বাপ্তিস্ম দিয়ে। সে তার জন্য প্রার্থনা করতো এবং সে তার সকল জ্ঞানই দিত, সে জানতো যে সে জানতো এবং তোমাকে বলেছে যে সে বলেছে তুমি তোমার ভাইয়ের ঘুম থেকে বের হয়েছ.","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُنْكَدِرُ بْنُ مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مَعْرُوفٍ ‏ ‏صَدَقَةٌ ‏ ‏وَإِنَّ مِنْ الْمَعْرُوفِ أَنْ ‏ ‏تَلْقَى أَخَاكَ بِوَجْهٍ ‏ ‏طَلْقٍ ‏ ‏وَأَنْ تُفْرِغَ مِنْ دَلْوِكَ فِي إِنَاءِ أَخِيكَ ‏","","",""],[14349,14349,"","আমরা একটি ছেলে কথা বলেছি যে তার কথা শুনে আমার বাবার কাছে ভালো পিতা আছেন। সে বলবে তার গলায় পাখির ডাকের মানে আছে।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏طَائِرُ كُلِّ إِنْسَانٍ فِي عُنُقِهِ ‏ ‏قَالَ ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏يَعْنِي الطِّيَرَةَ ‏","","",""],[14350,14350,"","আমরা একটি সুখী ছেলেকে লিখতে চেষ্টা করেছি। আমরা আমার শ্বশুর আব্বার সাথে কথা বলেছি। সে উত্তরটি শুনেছে। আমি বলবো ঈশ্বরের দোহাই, নাকি আমি তাকে এ ধরনের মন্দতার জন্য অনুরোধ করবো না। নমস্কার।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا أَحَدٌ يَدْعُو بِدُعَاءٍ إِلَّا آتَاهُ اللَّهُ مَا سَأَلَ أَوْ كَفَّ عَنْهُ مِنْ السُّوءِ مِثْلَهُ مَا لَمْ يَدْعُ بِإِثْمٍ أَوْ بِقَطِيعَةِ رَحِمٍ ‏","","",""],[14351,14351,"","আমরা চেষ্টা করেছি আমার প্রিয় ছেলের চেয়ে ভালো ছেলেকে খুঁজে পাওয়ার জন্য। ( আদিপুস্তক ১: ২৭) ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং ঈশ্বরের সমস্ত ইচ্ছা পূর্ণ করেছেন । যারা লর্ডকে সম্মান করবে, যুদ্ধ চলে গেছে, প্রভু, আর আল্লাহ্‌ বলেছেন অগ্নি নির্বাপকারকে গুলি করা হবে না অথবা গুলি করা হবে।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏قَدِمَ مِنْ ‏ ‏جَيْشَانَ ‏ ‏وَجَيْشَانُ ‏ ‏مِنْ ‏ ‏الْيَمَنِ ‏ ‏فَسَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ شَرَابٍ يَشْرَبُونَهُ بِأَرْضِهِمْ مِنْ الذُّرَةِ يُقَالُ لَهُ ‏ ‏الْمِزْرُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمُسْكِرٌ هُوَ قَالَ نَعَمْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مُسْكِرٍ حَرَامٌ وَإِنَّ عَلَى اللَّهِ عَزَّ وَجَلَّ عَهْدًا لِمَنْ يَشْرَبُ الْمُسْكِرَ أَنْ يَسْقِيَهُ مِنْ ‏ ‏طِينَةِ الْخَبَالِ ‏ ‏فَقَالُوا يَا رَسُولَ اللَّهِ وَمَا ‏ ‏طِينَةُ الْخَبَالِ ‏ ‏قَالَ عَرَقُ أَهْلِ النَّارِ ‏ ‏أَوْ عُصَارَةُ أَهْلِ النَّارِ ‏","","",""],[14352,14352,"","আমরা ঈশ্বরের ঋণের কথা বলেছিলাম... ...আমাদের প্রভুদের কাছে নিয়ে এসেছে, কিন্তু একটি নিষ্ঠুর ছেলে আমাকে বলেছে যে ঈশ্বর এটা দিয়েছেন আর ঈশ্বর তাকে উদ্ধার করেছেন। আমি চেষ্টা করছি হত্যা করতে। আবারও তারা ফিরে আসছে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ الْمَدِينِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَلِيِّ بْنِ رَبِيعَةَ السُّلَمِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏جَابِرُ ‏ ‏أَمَا عَلِمْتَ ‏ ‏أَنَّ اللَّهَ عَزَّ وَجَلَّ أَحْيَا أَبَاكَ فَقَالَ لَهُ تَمَنَّ عَلَيَّ فَقَالَ أُرَدُّ إِلَى الدُّنْيَا فَأُقْتَلُ مَرَّةً أُخْرَى فَقَالَ إِنِّي قَضَيْتُ الْحُكْمَ أَنَّهُمْ إِلَيْهَا لَا يُرْجَعُونَ ‏","","",""],[14353,14353,"","আমরা ঈশ্বরের সিংহাসনের গেরিলাদের দ্বারা কথা বলেছি, ঈশ্বরের দোহাই দিয়ে ঈশ্বরের পুত্র। সে তার কাছে প্রার্থনা করে, তার কাছে প্রার্থনা করে, তার কাছে একটা কলারে জীবন উৎসর্গ করে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْجَبَّارِ بْنُ مُحَمَّدٍ الْخَطَّابِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ يَعْنِي ابْنَ عَمْرٍو الرَّقِّيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُمْرَةٌ فِي رَمَضَانَ تَعْدِلُ حَجَّةً ‏","","",""],[14354,14354,"","আমরা দুজন জাহাজের কথা বলেছিলাম, ঈশ্বরের নাম জানার চেষ্টা করার ব্যাপারে। ঈশ্বরের কাছে আমাকে আত্মসমর্পণ করতে হবে যেন তারা এই অপরাধকে পরাজিত করে এবং রানীকে ধ্বংস করে দেয়। তার কাছে প্রার্থনা কর এবং তোমার রক্ত থেকে রুটি উদ্ধার কর।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْيَهُودِ ‏ ‏إِنِّي سَائِلُهُمْ عَنْ تُرْبَةِ الْجَنَّةِ وَهِيَ ‏ ‏دَرْمَكَةٌ ‏ ‏بَيْضَاءُ فَسَأَلَهُمْ فَقَالُوا هِيَ خُبْزَةٌ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخُبْزَةُ مِنْ ‏ ‏الدَّرْمَكِ ‏","","",""],[14355,14355,"","আমরা কথা বলেছিলাম, একটা ছেলেকে সাহায্য করার কথা, যার দরকার ছিল ঈশ্বরের কাছে প্রার্থনা করা, যতক্ষণ না সে মারা যায়, ততক্ষণ পর্যন্ত সে তার কাছে আসবে। তুমি একটা চরম পোঁটা এবং পানি খেয়ে ফেলবে। তুমি এটা থেকে খেয়ে খেয়ে ফেলবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مِينَاءَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الثَّمَرَةِ حَتَّى ‏ ‏تُشْقَحَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِسَعِيدٍ ‏ ‏مَا ‏ ‏تُشْقَحُ ‏ ‏قَالَ ‏ ‏تَحْمَارُّ ‏ ‏وَتَصْفَارُّ ‏ ‏وَيُؤْكَلُ مِنْهَا ‏","","",""],[14356,14356,"","আমরা আমার বাবার জন্য কথা বলেছি, ভালো বন্ধু, যার কাছে শান্তি এবং কারণ আছে। আমি ঈশ্বরের কাছে প্রার্থনা করব যেন তিনি তলোয়ার ব্যবহার করেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحُمَيْدٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ ‏ ‏يُتَعَاطَى السَّيْفُ ‏ ‏مَسْلُولًا ‏","","",""],[14357,14357,"","আমরা যখন কোনো মূল্য দিতে বলা হতো, তখন আমরা এক পার্থক্য সম্বন্ধে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏حَدَّثَنِي ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعُمْرَى ‏ ‏جَائِزَةٌ ‏","","",""],[14358,14358,"","আমরা আমাদের কথোপকথন এত ভাল যে ঈশ্বর ভুলে যেতে হবে যে আমি একটি মানুষকে ছেড়ে চলে যেতে চেষ্টা করা উচিত. তারা বলতে যাচ্ছে আমরা আপনার সাহস নিয়ে বলছি যে আমরা আপনার সাহস নিয়ে যাচ্ছি আগুন আর তুমি আমার হাতে খুন হয়ে যাচ্ছ.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ مِينَاءَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلِي وَمَثَلُ الْأَنْبِيَاءِ كَمَثَلِ رَجُلٍ أَوْقَدَ نَارًا فَجَعَلَ الْفَرَاشُ ‏ ‏وَالْجَنَادِبُ ‏ ‏يَقَعْنَ فِيهَا قَالَ وَهُوَ يَذُبُّهُنَّ عَنْهَا قَالَ وَأَنَا آخِذٌ بِحُجَزِكُمْ عَنْ النَّارِ وَأَنْتُمْ ‏ ‏تَفَلَّتُونَ مِنْ يَدِي ‏","","",""],[14359,14359,"","বেনকে সাহায্য করার ব্যাপারে কথা বলার সময় আমাদের কথোপকথনের কথা আমরা জীবিত থাকব। ''আর যেইজন পুরুষ হবে সে-ই তো একজন মানুষ যে নিজেকেই একজন মানুষ হিসেবে তৈরি করেছে, কাজেই সে একজন পুরুষ হয়ে যাবে, আর সে হবে একজন পুরুষ জাত। যে লোক পুরুষ হোক কিংবা নারী , সে ব ্ যতীত অন ্ য কোন লোক যে ব ্ যক ্ তি হয়ে যাবে , সে ব ্ যক ্ তি হয়ে আসবে এবং তার সমান হবে পুরুষ ও মানব । যে লোক পুরুষ হোক কিংবা নারী , সে ব ্ যতীত অন ্ য কোন লোক যে ব ্ যক ্ তি হয়ে যাবে , সে ব ্ যক ্ তি হয়ে আসবে এবং তার সমান হবে পুরুষ ও মানব । যে লোক পুরুষ হোক কিংবা নারী , সে ব ্ যতীত অন ্ য কোন লোক যে ব ্ যক ্ তি হয়ে যাবে , সে ব ্ যক ্ তি হয়ে আসবে এবং তার সমান হবে পুরুষ ও মানব । এমন একজন মানুষ যে হবে যে এমন একজন মানুষ যে হবে যে এমন একজন মানুষ যে হবে যে কিনা এমন একজন মানুষ যে হবে যে তাকে বলবে যে আমরা ঈশ্বরের অনুগ্রহের উপর ভবন সুড়সুড়ি দিয়ে দেব তার উপরে আর আমরা যেভাবে উদ্ধার করতে পারি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مِينَاءَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلِي وَمَثَلُ الْأَنْبِيَاءِ كَمَثَلِ رَجُلٍ ابْتَنَى دَارًا فَأَكْمَلَهَا وَأَحْسَنَهَا إِلَّا مَوْضِعَ لَبِنَةٍ فَجَعَلَ النَّاسُ يَدْخُلُونَهَا وَيَعْجَبُونَ وَيَقُولُونَ لَوْلَا مَوْضِعُ اللَّبِنَةِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنَا مَوْضِعُ اللَّبِنَةِ جِئْتُ فَخَتَمْتُ الْأَنْبِيَاءَ ‏","","",""],[14360,14360,"","আমরা আমাদের আলোচনা জীবন্ত হয়ে উঠবে যখন আমরা প্রভুর অনুগ্রহের সাথে বেনের সাহায্য নিয়ে কথা বলেছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مِينَاءَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى ‏ ‏أَصْحَمَةَ النَّجَاشِيِّ ‏ ‏فَكَبَّرَ عَلَيْهِ أَرْبَعًا ‏","","",""],[14361,14361,"","ঈশ্বর দাবি করেছেন যে, তিনি এই সময়ের মধ্যে দিয়ে চার জন ব্যক্তিকে নিয়ে আসবেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏عَنْ لُحُومِ الْحُمُرِ وَأَذِنَ فِي لُحُومِ الْخَيْلِ ‏","","",""],[14362,14362,"","আমরা যাজককে খুঁজে পেতে ভয় পাচ্ছি, জাবের বলেছিলেন যে তাকে ঈশ্বরের কাছে পাঠানো হয়েছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাকে গান গাইতে শেখানো হবে।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْثَرُ بْنُ الْقَاسِمِ أَبُو زُبَيْدٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَهْدَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْبَيْتِ ‏ ‏غَنَمًا ‏","","",""],[14363,14363,"","আমরা ঈশ্বরের প্রতি ভালবাসা থেকে আমার সবচেয়ে ভালো স্বপ্নের কথা বলেছি, ঈশ্বর হয়তো দুজন সাক্ষীকে আপনার প্রতি দয়া দেখিয়ে দিয়েছেন। আমি বলতে পারি, আমি আপনার টাকা ভুলে যাবো এবং আপনাকে এটা করতে বলব তিনি বললেন তিনি বললেন না যে আমি ঈশ্বরের কাছে প্রার্থনা করেছি তার জন্য প্রার্থনা করছি। আমি বলবো, প্রভু, আমি ভয় পাচ্ছি, আমরা আবার জীবিত হব। আমি লড়াই করেছি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏الْمُفَضَّلُ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبْدِ الرَّحْمَنِ بْنِ جَرْهَدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَجُلًا يَقُولُ ‏ ‏لِجَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏مَنْ بَقِيَ مَعَكَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ بَقِيَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏وَسَلَمَةُ بْنُ الْأَكْوَعِ ‏ ‏فَقَالَ رَجُلٌ أَمَّا ‏ ‏سَلَمَةُ ‏ ‏فَقَدْ ارْتَدَّ عَنْ هِجْرَتِهِ فَقَالَ ‏ ‏جَابِرٌ ‏ ‏لَا تَقُلْ ذَلِكَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لِأَسْلَمَ ‏ ‏ابْدُوا يَا ‏ ‏أَسْلَمُ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ وَإِنَّا ‏ ‏نَخَافُ أَنْ نَرْتَدَّ بَعْدَ هِجْرَتِنَا فَقَالَ إِنَّكُمْ أَنْتُمْ تُهَاجِرُونَ حَيْثُ كُنْتُمْ ‏","","",""],[14364,14364,"","আমরা আনন্দের সাথে আমার ছেলের অনুগ্রহে এটা করেছি। আল্লাহ জানেন আমি নিজের রক্ত দিয়ে নিজে নিজে দেখেছি। তিনি তাঁর হাত দিয়ে ঈশ্বরের নাম এবং অন্য পথও বলেন। আমার জন্য এটা করেছে, আর সে আমার মাকে ত্যাগ করেনি।","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ الْأَضْحَى مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمُصَلَّى فَلَمَّا قَضَى خُطْبَتَهُ أَتَى بِكَبْشٍ فَذَبَحَهُ بِيَدِهِ وَقَالَ ‏ ‏بِسْمِ اللَّهِ وَبِاللَّهِ اللَّهُمَّ إِنَّ هَذَا عَنِّي وَعَمَّنْ لَمْ يُضَحِّ مِنْ أُمَّتِي ‏","","",""],[14365,14365,"","আমরা আনন্দের সাথে এমন একটা ছেলেকে ফিরিয়ে দেব যে কিনা কিনা ঈশ্বরের বাক্য নিয়ে এসেছিল। একজন ভালো ছেলেকে প্রার্থনা করে ঈশ্বরকে বলে যে তার শান্তি দিয়েছে এবং আমাকে হত্যা করতে বলেছে। ( খ) কেন আমরা নিশ্চিত থাকতে পারি যে, যিহোবা তাঁর লোকেদের রক্ষা করবেন?","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏الْمُطَّلِبِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏قُتَيْبَةُ ‏ ‏فِي حَدِيثِهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صَيْدُ الْبَرِّ لَكُمْ حَلَالٌ ‏ ‏قَالَ ‏ ‏سَعِيدٌ ‏ ‏وَأَنْتُمْ حُرُمٌ مَا لَمْ تَصِيدُوهُ أَوْ يُصَدْ لَكُمْ ‏","","",""],[14366,14366,"","আমরা আমাদের আলোচনা করার চেষ্টা করেছি এবং চেষ্টা করার জন্য তাদেরকে শাস্তি দেওয়ার চেষ্টা করেছি। আর ঈশ্বর ও ঈশ্বরের নামে এই বিষয়ে আমি এই কথা বলি আর তিনি আমাকে আশ্বাস দেন যে আমি কে নই ।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏الْمُطَّلِبِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَضْحَى بِالْمُصَلَّى فَلَمَّا قَضَى خُطْبَتَهُ نَزَلَ مِنْ مِنْبَرِهِ وَأَتَى بِكَبْشٍ فَذَبَحَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ وَقَالَ ‏ ‏بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ هَذَا عَنِّي وَعَمَّنْ لَمْ يُضَحِّ مِنْ أُمَّتِي ‏","","",""],[14367,14367,"","আমরা আমার বাবার ব্যাপারে কথা বলেছি, কিন্তু তাকে বলা হয়েছে যে সে আমার প্রেমে পড়েছে। ঈশ্বরের কাছে প্রার্থনা করে এবং তার কাছে আত্মসমর্পণ করে। সে বলল যে আমি আমার কথা ভুলবো না। আর তারপর সে বললো, সে তোমার সাথে খেলতে ও অনেক বেশি সময় খেলতে পারে, তুমি তাদের সাথে রাতের বেলা উড়তে পারো।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزَاةٍ قَالَ فَاسْتَأْذَنْتُ أَتَعَجَّلُ قُلْتُ إِنِّي تَزَوَّجْتُ قَالَ ‏ ‏ثَيِّبًا ‏ ‏أَمْ ‏ ‏بِكْرًا ‏ ‏قَالَ قُلْتُ ‏ ‏ثَيِّبًا ‏ ‏قَالَ ‏ ‏فَأَلَّا كَانَتْ ‏ ‏بِكْرًا ‏ ‏تُلَاعِبُهَا وَتُلَاعِبُكَ قَالَ انْطَلِقْ وَاعْمَلْ عَمَلًا كَيِّسًا ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَعْنِي لَا ‏ ‏تَطْرُقْهُنَّ ‏ ‏لَيْلًا ‏","","",""],[14368,14368,"","আমরা যে - বাপ্তিস্ম সম্বন্ধে কথা বলেছিলাম, তা তাকে বলতে হয়েছিল যে, তাকে উত্তর দিতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَمْشِيَ أَحَدُنَا فِي النَّعْلِ الْوَاحِدَةِ ‏","","",""],[14369,14369,"","আমরা কঠিন সময় সম্বন্ধে শিখতে চেষ্টা করার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَبِيبٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏احْبِسُوا صِبْيَانَكُمْ حَتَّى تَذْهَبَ ‏ ‏فَوْرَةُ ‏ ‏الْعِشَاءِ فَإِنَّهَا سَاعَةٌ تَخْتَرِقُ فِيهَا الشَّيَاطِينُ ‏","","",""],[14370,14370,"","ক্যাপ্টেনের বাবাকে আমরা আমাদের বাপ্তিস্মের কথা বলেছিলাম... ...যারা আমাদের ঈশ্বরের কাছে প্রার্থনা করতে বলেছিল আমরা দরজা বন্ধ করে দেব আর ভুল করে ফেলব ডিনারটা হচ্ছে তার টাকা দিয়ে খেতে হবে আর একমাত্র উপায়ের সাথে হেঁটে যাওয়া আর দুনিয়ার সেরাটা বানানো।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نُغْلِقَ الْأَبْوَابَ وَأَنْ ‏ ‏نُوكِئَ ‏ ‏الْأَسْقِيَةَ ‏ ‏وَأَنْ نُطْفِئَ الْمَصَابِيحَ وَأَنْ نَكُفَّ ‏ ‏فَوَاشِيَنَا ‏ ‏حَتَّى تَذْهَبَ ‏ ‏فَحْمَةُ ‏ ‏الْعِشَاءِ وَنَهَانَا أَنْ يَأْكُلَ الرَّجُلُ بِشِمَالِهِ وَأَنْ يَمْشِيَ فِي النَّعْلِ الْوَاحِدَةِ وَعَنْ ‏ ‏الصَّمَّاءِ ‏ ‏وَالِاحْتِبَاءِ ‏ ‏فِي ثَوْبٍ وَاحِدٍ ‏","","",""],[14371,14371,"","আমরা বাপ্তিস্মের কথা বলেছিলাম আমরা যেন ঈশ্বরের কাছে উত্তর দিতে পেরে আনন্দিত হই। তার কাছে প্রার্থনা করো আর সে তার কাছে পৌঁছে দিল একবার যখন সে তাকে লর্ডকে দিয়ে দিল। কারণ হল, সিল্ক যখন ঘুমাচ্ছিল এবং তারা মারা যায়নি গ্রীষ্ম এবং এই চমক।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَيْسُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَرْبَعٍ ‏ ‏خَلَوْنَ ‏ ‏مِنْ ذِي الْحِجَّةِ فَلَمَّا طُفْنَا ‏ ‏بِالْبَيْتِ ‏ ‏وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْعَلُوهَا عُمْرَةً إِلَّا مَنْ كَانَ مَعَهُ ‏ ‏الْهَدْيُ ‏ ‏فَلَمَّا كَانَ ‏ ‏يَوْمُ التَّرْوِيَةِ ‏ ‏أَهَلُّوا ‏ ‏بِالْحَجِّ فَلَمَّا كَانَ ‏ ‏يَوْمُ النَّحْرِ ‏ ‏طَافُوا وَلَمْ يَطُوفُوا بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏","","",""],[14372,14372,"","আমার বাবা এমন একটা ছেলের উত্তর দেবেন, যে তার জন্য প্রার্থনা করেছে এবং তার জন্য প্রার্থনা করেছে । তুমি ভাল হবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏و عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَدِّدُوا وَقَارِبُوا وَلَنْ يُنْجِيَ أَحَدًا مِنْكُمْ عَمَلُهُ قُلْنَا وَلَا أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ مِنْهُ بِرَحْمَةٍ ‏","","",""],[14373,14373,"","ঘোড়া ও চাঁদ চলে গেছে, ঈশ্বর প্রভুকে উদ্ধার করেছেন এবং তিনি প্রভুকে উদ্ধার করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏ذَبَحْنَا يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏الْخَيْلَ وَالْبِغَالَ وَالْحَمِيرَ فَنَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْبِغَالِ وَالْحَمِيرِ وَلَمْ يَنْهَ عَنْ الْخَيْلِ ‏","","",""],[14374,14374,"","আমি আমার ছেলের কথা বলেছিলাম আমার বাবার ব্যাপারে বলতে, আমি ঈশ্বরের কাছে প্রার্থনা করব আর এর উত্তর দেব। আমি বললাম, আমার মন তার অসিদ্ধতার কারণে তার ক্ষমতা হারিয়ে ফেলেছে। আর লোকটি বলেছে যে সে যা করেছে তা সে এখনো করেছে। তারপর আমি এটা করেছি যে ঋণের পরিকল্পনা করা হয়েছে, আর সে আমাকে দিতে রাজি হয়েছে। আমাকে সুসংবাদ দাও.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ ‏ ‏بِجَابِرٍ ‏ ‏فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏قَالَ وَقَدْ أَعْيَا بَعِيرِي فَقَالَ مَا شَأْنُكَ يَا ‏ ‏جَابِرُ ‏ ‏فَقُلْتُ بَعِيرِي قَدْ ‏ ‏رَزَمَ ‏ ‏قَالَ فَأَتَاهُ مِنْ قِبَلِ ‏ ‏عَجُزِهِ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏وَعَجُزُهُ سَوَاءٌ ‏ ‏فَدَعَا ‏ ‏وَزَجَرَهُ ‏ ‏قَالَ فَلَمْ يَزَلْ يَقْدُمُ الْإِبِلَ قَالَ فَأَتَى عَلَيْهِ فَقَالَ مَا فَعَلَ الْبَعِيرُ قُلْتُ مَا زَالَ يَقْدُمُهَا قَالَ بِكَمْ أَخَذْتَهُ فَقُلْتُ بِثَلَاثَةَ عَشَرَ دِينَارًا قَالَ ‏ ‏فَبِعْنِي بِالثَّمَنِ وَلَكَ ظَهْرُهُ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏قُلْتُ نَعَمْ قَالَ فَلَمَّا قَدِمْتُ ‏ ‏الْمَدِينَةَ ‏ ‏خَطَمْتُهُ ‏ ‏ثُمَّ أَتَيْتُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَعْطَانِي الثَّمَنَ وَأَعْطَانِي الْبَعِيرَ ‏","","",""],[14375,14375,"","আমরা ব্যাপ্টিস্ট মসজিদের কথা বলেছিলাম যে বিগ ড্যাডি যে ছেলে হাত তুলে হাত তুলেছিল, সে সেই ছেলে যে কিনা হাত তুলেছিল আর হাত তুলেছিল, ট্রাম খুলে তাকে সেটা করতে হবে খারাপের জগতে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏وَعَلَيْهِ عِمَامَةٌ سَوْدَاءُ ‏","","",""],[14376,14376,"","আমরা জানতে পারলাম যে আমরা আমার বাবার ব্যাপারে উত্তেজিত, সে তার করুণার অধ্যাপকের সাথে ফিরে আসবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَوَى ‏ ‏سَعْدَ بْنَ مُعَاذٍ ‏ ‏مِنْ رَمْيَتِهِ ‏","","",""],[14377,14377,"","ঈশ্বর আত্মসমর্পণ করেছেন এবং তিনি এই কথা বলার জন্য পরিকল্পনা করছেন যে, তিনি কখনও বলেছিলেন না যে, তিনি যদি এই কথা বলতেন, তাহলে তিনি তা করতেন । তিনি বলেছিলেন যে, তিনি যদি বলতেন যে, তিনি বলতেন, তাহলে তিনি বলতেন, “যদি তিনি বলতেন, তবে তিনি বলতেন, ‘ যদি তিনি এই কথা বলতেন, তবে তিনি এ কথালেন । ’ তিনি যদি তাদের প্রার্থনা করতে দেন, তাহলে তিনি তা পছন্দ করেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏رَجُلٌ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَخْطُبُ فَقَالَ ‏ ‏أَصَلَّيْتَ الرَّكْعَتَيْنِ فَقَالَ لَا قَالَ فَصَلِّهِمَا ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏جَابِرٌ ‏ ‏يَقُولُ ‏ ‏إِنْ صَلَّى فِي بَيْتِهِ يُعْجِبُهُ إِذَا دَخَلَ أَنْ يُصَلِّيَهُمَا ‏","","",""],[14378,14378,"","আমরা আমাদের কথোপকথনের কথা বলেছিলাম, কিন্তু যখন আমরা কাস্টমারের বাবার সাথে কথা বলেছিলাম তখন তারা ভালো ঘড়ি খাবে, ঈশ্বর তাকে তার কিছু চাহিদার মধ্যে পরিণত করতে বলেছেন ভবিষ্যদ্বাণীটা তার কাছে এসেছিল আর আমার সুযোগ করে দিল সে আবার এটা করবে, সে এটা করবে, আমি প্রার্থনা করেছিলাম যে সে তার ভ্রমণকারী।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَهُ لِبَعْضِ حَاجَتِهِ قَالَ فَجَاءَ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى رَاحِلَتِهِ قَالَ فَسَلَّمَ عَلَيْهِ فَسَكَتَ فَسَلَّمَ عَلَيْهِ فَسَكَتَ فَسَلَّمَ عَلَيْهِ فَسَكَتَ ثَلَاثَ مَرَّاتٍ قَالَ فَقَالَ لَهُ لَمَّا فَرَغَ ‏ ‏إِنَّهُ لَمْ يَمْنَعْنِي أَنْ أَرُدَّ عَلَيْكَ إِلَّا أَنِّي كُنْتُ أُصَلِّي قَالَ فَصَلَّى حَيْثُ تَوَجَّهَتْ بِهِ رَاحِلَتُهُ ‏","","",""],[14379,14379,"","তিনি গণনাটা ছেড়ে দেবেন এবং দ্বিতীয় বারের মতো তার হাতে ধরা পড়া থেকে বঞ্চিত হবেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏وَهُوَ مُحْرِمٌ مِنْ ‏ ‏وَثْيٍ ‏ ‏كَانَ بِهِ ‏","","",""],[14380,14380,"","আমি বলেছিলাম যে, আমরা নাকি এখানে আছি ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَقَقْتُ الْبَابَ فَقَالَ ‏ ‏مَنْ هَذَا قُلْتُ أَنَا قَالَ أَنَا أَنَا كَأَنَّهُ كَرِهَهُ ‏","","",""],[14381,14381,"","আমরা আমাদের আলোচনা জীবন্ত হয়ে উঠবে যখন আমরা প্রভুর অনুগ্রহের সাথে বেনের সাহায্য নিয়ে কথা বলেছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مِينَاءَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى ‏ ‏أَصْحَمَةَ النَّجَاشِيِّ ‏ ‏فَكَبَّرَ عَلَيْهِ أَرْبَعًا ‏","","",""],[14382,14382,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি সেই খুনিকে উদ্ধার করেছিলেন, যিনি পুতুলটা নেওয়ার পর তাকে ছেড়ে দেননি ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏مَطَرٌ ‏ ‏عَنْ ‏ ‏رَجُلٍ أَحْسَبُهُ ‏ ‏الْحَسَنَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏أُعْفِي مَنْ قَتَلَ بَعْدَ أَخْذِهِ ‏ ‏الدِّيَةَ ‏","","",""],[14383,14383,"","আমরা আমার বাবা সম্পর্কে কথা বলেছি আর বাবার থেকে ভালো কথা বলেছি, আমি এমন একটা ছেলে খুঁজে পেতে ক্লান্ত যে দেবতাদের দ্বারা বলা হয়েছে যারা আমি বিরুদ্ধে যুদ্ধ করেছি. সে বিশ্বাস করে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ يَزِيدَ ‏ ‏أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَحْيَا أَرْضًا دَعْوَةً مِنْ الْمَصْرِ ‏ ‏أَوْ ‏ ‏رَمْيَةً ‏ ‏مِنْ الْمَصْرِ ‏ ‏فَهِيَ لَهُ ‏","","",""],[14384,14384,"","সে একটা কাজ করতে চায়, সে অভ্যাস ত্যাগ করবে আর তার বাবা-মার ঘর থেকে বের হয়ে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ فِي ‏ ‏الْعِيدِ ‏ ‏وَيُخْرِجُ أَهْلَهُ ‏","","",""],[14385,14385,"","আমরা হামাদের সঙ্গে কথা বলেছিলাম, ঈশ্বরের কাছে উত্তর দেওয়ার পর আমরা এগিয়ে যেতে বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَيْسُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحَرَ الْبَدَنَةَ عَنْ سَبْعَةٍ وَالْبَقَرَةَ عَنْ سَبْعَةٍ ‏","","",""],[14386,14386,"","ঈশ্বর তাকে আদেশ দিয়েছেন, যখন নগর তাকে আদেশ দিয়েছিল যেন তিনি রাজার গৌরব খুঁজে পান । শহরের জমি.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏مُحَارِبُ بْنُ دِثَارٍ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏إِنَّهُ كَانَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ ‏ ‏فَلَمَّا أَتَى ‏ ‏الْمَدِينَةَ ‏ ‏أَمَرَهُ أَنْ يَأْتِيَ الْمَسْجِدَ فَيُصَلِّيَ رَكْعَتَيْنِ ‏","","",""],[14387,14387,"","আমরা আমার বাবাকে খুঁজে পাওয়ার চেষ্টার কথা বলেছিলাম, সে আমাদের কথা শুনে খুব মজা পাচ্ছে যে আমরা ঈশ্বরের কাছে প্রার্থনা করছি তার কাছে প্রার্থনা করতে আর বেঁচে থাকতে শেখাবো। আমরা মেয়েদের আনন্দ করি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏وَعَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏تَمَتَّعْنَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتْعَتَيْنِ الْحَجَّ وَالنِّسَاءَ ‏ ‏وَقَدْ قَالَ ‏ ‏حَمَّادٌ ‏ ‏أَيْضًا مُتْعَةَ الْحَجِّ وَمُتْعَةَ النِّسَاءِ ‏ ‏فَلَمَّا كَانَ ‏ ‏عُمَرُ ‏ ‏نَهَانَا عَنْهُمَا فَانْتَهَيْنَا ‏","","",""],[14388,14388,"","আমরা একজন সাক্ষীর কথা বলেছিলাম যে আমি একটা সালমনকে একটা উপহার দিতে চাই আর আমরা একটা লড়াই দেখতে চাই, ঈশ্বর তাকে শিখিয়েছিলেন আর সে ঘুরে ঘুরে ঘুরে ঘুরে ঘুরে ঘুরে ঘুরে ঘুরে ঘুরে ঘুরে ঘুরে ঘুরে ঘুরে বেড়াবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ سَأَلَ ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏عَطَاءً ‏ ‏وَأَنَا شَاهِدٌ ‏ ‏قَالَ حَدَّثَكَ ‏ ‏جَابِرٌ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يُنْبَذَ الْبُسْرُ وَالتَّمْرُ جَمِيعًا وَالزَّبِيبُ وَالتَّمْرُ جَمِيعًا قَالَ ‏ ‏عَطَاءٌ ‏ ‏نَعَمْ ‏","","",""],[14389,14389,"","সে বলেছে, তার দু'টো সেলমোন আছে, আর আমরা দেখছি যে তিনি ঈশ্বরের কাছে অনুরোধ করেছেন, আমি তার প্রতি বিরক্ত বা তার ভাইয়ের অসম্মান করছি না, আর তাকে আর না পুনরাবৃত্তি করছি।","‏ ‏و قَالَ ‏ ‏لَهُ ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏وَأَنَا شَاهِدٌ ‏ ‏حَدَّثَكَ ‏ ‏جَابِرٌ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَزْرَعْهَا ‏ ‏أَوْ لِيُزْرِعْهَا ‏ ‏أَخَاهُ وَلَا ‏ ‏يُكْرِيهَا قَالَ ‏ ‏عَطَاءٌ ‏ ‏نَعَمْ ‏","","",""],[14390,14390,"","আমরা বাপ্তিস্ম নিয়ে কথা বলেছিলাম কিন্তু আমরা একটা পাহাড় ছেড়ে যেতে বলেছিলাম, আমরা ঈশ্বরকে ভালবাসি, ঈশ্বর, আমি ঈশ্বর, আমাকে সতর্ক করে দিয়েছি হলে প্রার্থনা করার জন্য, আমি এখানে যাই। আমি এই বিষয়ে কথা বলি, আমি বলি, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, ঈশ্বর, আমি যখন প্রার্থনা করতে পারি, তখন আমি আপনাকে কল করি, আমি আপনাকে বলছি, আমি আপনাকে বলছি, আমি আপনাকে বলি, ঈশ্বর আমার প্রার্থনা করতে হবে। আমি আপনাকে বলছি, আমি যদি আমার প্রার্থনা করতে বলি, আমি আপনাকে বলছি, আমি আপনাকে ধন্যবাদ দিতে হবে। আমি আপনাকে বলছি, আমি কি করতে পারি? তাকে তোমার সম্পর্কে কিছু বলতে বলো.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏حَبِيبٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَجُلًا قَالَ يَوْمَ الْفَتْحِ يَا رَسُولَ اللَّهِ ‏ ‏إِنِّي نَذَرْتُ إِنْ فَتَحَ اللَّهُ عَلَيْكَ ‏ ‏مَكَّةَ ‏ ‏أَنْ أُصَلِّيَ فِي ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏فَقَالَ صَلِّ هَاهُنَا فَسَأَلَهُ فَقَالَ صَلِّ هَاهُنَا فَسَأَلَهُ فَقَالَ شَأْنَكَ إِذًا ‏","","",""],[14391,14391,"","আমরা শপথ করে বলেছিলাম আমাকে হত্যা করার কথা। এর মানে, ফুলগুলো আমাদের এমন কিছু খেতে দিবে না, যা আমরা পড়তে পারব না। সে যদি এটা খেতে ভালো হয়, তাহলে সে খুশি হবে। আমি কখনো বলিনি যে আমরা কখনো ঈশ্বরের বিয়েতে উপস্থিত হব না। হঠাৎ করে সে বলল যে সে আমার ভাইয়ের সাথে কথা বলেছে। সে মারা যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏سُلَيْمَانُ بْنُ هِشَامٍ ‏ ‏إِنَّ هَذَا ‏ ‏يَعْنِي ‏ ‏الزُّهْرِيَّ ‏ ‏لَا يَدَعُنَا نَأْكُلُ شَيْئًا إِلَّا أَمَرَنَا أَنْ نَتَوَضَّأَ مِنْهُ ‏ ‏يَعْنِي مَا مَسَّتْهُ النَّارُ ‏ ‏قَالَ فَقُلْتُ لَهُ ‏ ‏سَأَلْتُ عَنْهُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏فَقَالَ ‏ ‏إِذَا أَكَلْتَهُ فَهُوَ طَيِّبٌ لَيْسَ عَلَيْكَ فِيهِ وُضُوءٌ فَإِذَا خَرَجَ فَهُوَ خَبِيثٌ عَلَيْكَ فِيهِ الْوُضُوءُ ‏ ‏قَالَ فَهَلْ بِالْبَلَدِ أَحَدٌ قَالَ قُلْتُ نَعَمْ أَقْدَمُ رَجُلٍ فِي جَزِيرَةِ ‏ ‏الْعَرَبِ ‏ ‏عِلْمًا قَالَ مَنْ قُلْتُ ‏ ‏عَطَاءُ بْنُ أَبِي رَبَاحٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فَأَرْسَلَ إِلَيْهِ فَجِيءَ بِهِ ‏ ‏قَالَ فَبَعَثَ إِلَيْهِ فَقَالَ ‏ ‏حَدَّثَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّهُمْ ‏ ‏أَكَلُوا مَعَ ‏ ‏أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏خُبْزًا وَلَحْمًا فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[14392,14392,"","তিনি বললেন, আপনি চাঁদের অর্থ দিতে চান, তিনি আমাকে বললেন যে তিনি মুক্তি পেয়েছেন এবং বলেন, \"আমি দুঃখিত, আমি দুঃখিত\"।","‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏لِعَطَاءٍ ‏ ‏مَا تَقُولُ ‏ ‏يَعْنِي فِي الْعُمْرَى قَالَ حَدَّثَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعُمْرَى جَائِزَةٌ ‏","","",""],[14393,14393,"","আমার ছেলে এবং সুখী বেন মিনার কথা আমরা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏وَسَعِيدِ بْنِ مِينَا ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُحَاقَلَةِ ‏ ‏وَالْمُزَابَنَةِ ‏ ‏وَالْمُعَاوَمَةِ ‏ ‏فَقَالَ أَحَدُهُمَا ‏ ‏وَبَيْعِ السِّنِينَ ‏ ‏وَعَنْ بَيْعِ ‏ ‏الثُّنْيَا ‏ ‏وَرَخَّصَ فِي ‏ ‏الْعَرَايَا ‏","","",""],[14394,14394,"","আমি তার জন্য প্রার্থনা করেছি এবং বলবো যে তিনি জেলে যাবেন না, তারা আর কাজ করবে না এবং তারা তা করবে না। তাদের খাবার পরিকল্পনা করে নিজের সাহস বের করুন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ مِهْرَانَ الْأَعْمَشُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سُفْيَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَهْلَ الْجَنَّةِ يَأْكُلُونَ فِيهَا وَيَشْرَبُونَ لَا يَبُولُونَ وَلَا ‏ ‏يَتَغَوَّطُونَ ‏ ‏وَلَا يَتْفُلُونَ وَلَا يَمْتَخِطُونَ طَعَامُهُمْ ‏ ‏جُشَاءٌ ‏ ‏وَرَشْحٌ ‏ ‏كَرَشْحِ ‏ ‏الْمِسْكِ ‏","","",""],[14395,14395,"","আমাদের ভাই - বোনদের সঙ্গে কথা বলেছিলাম, যেন তারা ভীত না হয় । আপনার মুখে লোকেরা বলে, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং আমি যদি আমার আজ্ঞা মেনে চলি, তা হলে তিনি রক্ষা পাবেন । সে আমাদের কাছে হার মানতে চায়... ...যে সে একবার আমাদের পথ থেকে সরে যাবে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُهِلِّينَ ‏ ‏بِالْحَجِّ فَطُفْنَا ‏ ‏بِالْبَيْتِ ‏ ‏وَسَعَيْنَا بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَأَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَحِلَّ قَالَ فَخَرَجْنَا إِلَى ‏ ‏الْبَطْحَاءِ ‏ ‏قَالَ فَجَعَلَ الرَّجُلُ يَقُولُ عَهْدِي بِأَهْلِي ‏ ‏الْيَوْمَ فَقَالَ النَّاسُ فِي ذَلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ اسْتَقْبَلْتُ مِنْ أَمْرِي مَا اسْتَدْبَرْتُ مِنْهُ لَأَحْلَلْتُ وَلَمْ يَحِلَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَنَّهُ سَاقَ الْهَدْيَ فَأَحْرَمْنَا حِينَ تَوَجَّهْنَا إِلَى ‏ ‏مِنًى ‏","","",""],[14396,14396,"","আমরা বাবার সাথে কথা বলেছিলাম যে সে কাপুরুষ। আমরা ঈশ্বরের দয়ায় ঈশ্বরের দয়ায় ভ্রমণ করি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏نَحَرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏سَبْعِينَ بَدَنَةً الْبَدَنَةُ عَنْ سَبْعَةٍ ‏","","",""],[14397,14397,"","আমরা আমার বাবার মুখ নিয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَلَبَ وَسَأَلَ أَهْلَهُ ‏ ‏الْأُدْمَ ‏ ‏قَالُوا مَا عِنْدَنَا إِلَّا خَلٌّ قَالَ فَدَعَا بِهِ فَجَعَلَ يَأْكُلُ بِهِ وَيَقُولُ ‏ ‏نِعْمَ ‏ ‏الْأُدْمُ ‏ ‏الْخَلُّ ‏","","",""],[14398,14398,"","আমরা আমার বাবার উত্তর নিয়ে কথা বলেছি, তারা পৃথিবীতে হাত দেবে না যতক্ষণ না ঈশ্বরের দয়া তাঁর উপর থাকে এবং তার শান্তি শুরু হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُمْ كَانُوا لَا يَضَعُونَ أَيْدِيَهُمْ فِي الطَّعَامِ حَتَّى يَكُونَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ يَبْدَأُ ‏","","",""],[14399,14399,"","আমরা হামাদের ব্যাপারে কথা বলেছি কিন্তু আমরা বলেছি যে আমি ঈশ্বরের কাছে যেতে পারি, নবী ঈশ্বরের কাছে প্রার্থনা করেন আমি ঈশ্বরের কাছে প্রার্থনা করি যেন তিনি ঈশ্বরের কাছে প্রার্থনা করেন, আমি যেন তাঁর কাছে প্রার্থনা করি যে তিনি ব্যর্থ হন। প্রার্থনা করা হচ্ছে","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَجُلًا ذَبَحَ قَبْلَ أَنْ يُصَلِّيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَتُودًا ‏ ‏جَذَعًا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُجْزِئُ عَنْ أَحَدٍ بَعْدَكَ وَنَهَى أَنْ يَذْبَحُوا حَتَّى يُصَلُّوا ‏","","",""],[14400,14400,"","আমরা আমাদের মন পরিবর্তন করেছি, আমাদের নিজেদের দুই ছেলে, কিন্তু আমার বাবার অনেক প্রেম আছে, ঈশ্বর বলেছেন যে আমরা ঈশ্বরের অনুগ্রহের সাথে আত্মসমর্পণ করেছি, আমরা বিনয়ী ছিলাম। যে গাছ আমরা ঈশ্বরের কাছে যেতে পারি, তা তাঁর কাছে এসে একজন মানুষ হিসেবে তাকে উদ্ধার করে । তার আত্মা জমা দিয়ে, আমি ভয় পাই যে আমার কাছে এমন কোন মই আছে যে তোমাকে আমার থেকে রক্ষা করবে না যে ঈশ্বর তোমাকে জিতেছে এবং আমাকে যদি তুমি কে তাই করতে বলে ঈশ্বর তাকে দাবি করেছেন আর সে তলোয়ার আর তলোয়ার সরিয়ে দেবে। আমার গোলাপের উপরে তুলে নাও, অন্যরা তার কাছে ফিরে এসেছে ঈশ্বরের অনুগ্রহে ফিরে এসেছে, আর আমি প্রভুর কাছে আত্মসমর্পণ করেছি প্রভুর কাছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا كُنَّا ‏ ‏بِذَاتِ الرِّقَاعِ ‏ ‏قَالَ كُنَّا إِذَا أَتَيْنَا عَلَى شَجَرَةٍ ظَلِيلَةٍ تَرَكْنَاهَا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ ‏ ‏رَجُلٌ ‏ ‏مِنْ الْمُشْرِكِينَ وَسَيْفُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُعَلَّقٌ بِشَجَرَةٍ فَأَخَذَ سَيْفَ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاخْتَرَطَهُ ‏ ‏ثُمَّ قَالَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَخَافُنِي قَالَ لَا قَالَ فَمَنْ يَمْنَعُكَ مِنِّي قَالَ اللَّهُ عَزَّ وَجَلَّ يَمْنَعُنِي مِنْكَ قَالَ فَتَهَدَّدَهُ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَغْمَدَ ‏ ‏السَّيْفَ وَعَلَّقَهُ ‏ ‏فَنُودِيَ بِالصَّلَاةِ فَصَلَّى بِطَائِفَةٍ رَكْعَتَيْنِ وَتَأَخَّرُوا وَصَلَّى بِالطَّائِفَةِ الْأُخْرَى رَكْعَتَيْنِ فَكَانَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعُ رَكَعَاتٍ وَلِلْقَوْمِ رَكْعَتَانِ ‏","","",""]];
